import"./chunk-zIqBtW8h.js";import{t as r}from"./chunk-DN56IrFU.js";import"./bcdice-loader-DA-sGP6X.js";var a={"MagicaLogia.ja_jp":{ja_jp:{MagicaLogia:{special:`スペシャル(魔力1D6点か変調1つ回復)`,elements:{items:[`星`,`獣`,`力`,`歌`,`夢`,`闇`],format:`%{text}の魔素2が発生`},skill_table:{items:[[`星`,[`黄金`,`大地`,`森`,`道`,`海`,`静寂`,`雨`,`嵐`,`太陽`,`天空`,`異界`]],[`獣`,[`肉`,`蟲`,`花`,`血`,`鱗`,`混沌`,`牙`,`叫び`,`怒り`,`翼`,`エロス`]],[`力`,[`重力`,`風`,`流れ`,`水`,`波`,`自由`,`衝撃`,`雷`,`炎`,`光`,`円環`]],[`歌`,[`物語`,`旋律`,`涙`,`別れ`,`微笑み`,`想い`,`勝利`,`恋`,`情熱`,`癒し`,`時`]],[`夢`,[`追憶`,`謎`,`嘘`,`不安`,`眠り`,`偶然`,`幻`,`狂気`,`祈り`,`希望`,`未来`]],[`闇`,[`深淵`,`腐敗`,`裏切り`,`迷い`,`怠惰`,`歪み`,`不幸`,`バカ`,`悪意`,`絶望`,`死`]]],s_format:`「%{category_name}」≪%{skill_name}≫`},inveterate_enemy_table:{name:`宿敵表`,type:`1D6`,items:[`嫉妬。その人物は、実は調査者の実力をねたむ〈大法典〉の魔法使いだった。データは〈火刑人〉を使用する。ただし、魔法の使用には魔素を必要とし、魔法使いをコレクションすることはできない。GMは調査者やそのアンカーに魔法戦を挑み、邪魔をするように操作すること。`,`蒐集。その人物は、実は調査者をコレクションしようとする〈書籍卿〉だった。データは〈混血主義者〉を使用する。GMは〈断章〉に立ち会ったり、魔法戦を挑んだりして、調査者の邪魔をするように操作すること。`,`妨害。その人物は、実は現在調査者が追っている〈断章〉を奪おうとする〈書籍卿〉だった。データは〈囁きの誘惑者〉を使用する。GMは〈断章〉に立ち会ったり、魔法戦を挑んだりして、調査者の邪魔をするように操作すること。`,`断章。その人物には、今回の件と関係ない〈断章〉が憑依していた。データは〈猛獣〉を使用する。ただし特技と召喚する騎士は%{skill}に変更する。GMは〈断章〉に立ち会ったり、魔法戦を挑んだりして、調査者の邪魔するように操作すること。`,`黒服。その人物は、実は魔法やオバケなどのあらゆる超常現象を否定する秘密結社「サークルエンド」の工作員だった。データは〈サークルエンド〉を使用する。GMは【隠蔽工作】を使用したり、魔法戦を挑んだりして、調査者の邪魔をするように操作すること。`,`忍者。その人物は、実はあなたを殺せという使命を受けた忍者である。データは〈忍者〉を使用する。GMは〈断章〉に立ち会ったり、魔法戦を挑んだりして、調査者の邪魔をするようにそうさすること。`]},conspiracy_table:{name:`謀略表`,type:`1D6`,items:[`爆弾。その人物には、調査者の肉体を爆発させる魔法爆弾が仕掛けられていた。この【秘密】が公開されると、調査者は1d6点のダメージを受ける。`,`呪詛。その人物には、調査者に感染する呪いの魔法が仕掛けられていた。この【秘密】が公開されると、調査者はランダムに選んだ変調を一つ受ける。`,`幽閉。その人物には、調査者を異次元の牢獄に閉じ込める魔法が仕掛けられていた。この【秘密】が公開されると、調査者のプレイヤーがシーンプレイヤーになるか、クライマックスフェイズになるまで、シーンに登場できなくなる(マスターシーンでの登場の可否はGMが決定できる)。`,`強化。その人物には、調査者の運命の力を吸収する魔法が仕掛けられていた。この【秘密】が公開されると、調査者のアンカーの数と同じ数まで、セッションに登場する〈断章〉の憑依深度が1上昇する。`,`不幸。その人物には、調査者のアンカーに不幸な出来事を起こす魔法が仕掛けられていた。この【秘密】が公開されると、調査者のアンカーの中から〈愚者〉を一人選び、そのNPCに運命変転表を使用する。`,`脱走。その人物には、〈断章〉の逃亡を手助けする魔法が仕掛けられていた。この【秘密】が公開されると、GMは〈断章〉一つとNPC一人を選ぶ。その〈断章〉は、そのNPCに憑依できる。このときGMは、すでに魔法使いによって回収された〈断章〉を選んでも良く、その場合【魔力】は1d6点回復する。`]},fate_table:{name:`因縁表`,type:`1D6`,items:[`思慕。その人物は、実は調査者のことを知っており、深く愛していた。調査者はその人物に対する【運命】を2点上昇し、その属性を「恋愛」にする。その人物の【運命】の属性が「恋愛」の間、調査者は、この人物に対する【運命】が1点上昇するたび、【魔力】がその【運命】の値だけ回復する。`,`縁者。その人物は、実は調査者と血縁関係があった。調査者はその人物に対する【運命】を2点上昇し、その属性を「血縁」にする。その人物の【運命】の属性が「血縁」の間、調査者の復活判定に、その【運命】の値だけプラスの修正がつく。`,`怨恨。その人物は、実は調査者に深い恨みを持つ人物だった。調査者はその人物に対する【運命】を2点上昇し、その属性を「宿敵」にする。その人物の【運命】の属性が「宿敵」の間は、調査者がファンブルすると、その【運命】の値だけ【魔力】が減少する。`,`狂信。その人物は、実は調査者を崇拝していた。調査者はその人物に対する【運命】を2点上昇し、その属性を「支配」にする。その人物の【運命】の属性が「支配」の間、調査者は、その人物に憑依した〈断章〉に魔法戦を挑んだ場合、自動的に勝利することができる。ただし、調査者は、行為判定のとき、その【運命】の値以下の目が出るとファンブルになる。`,`分身。その人物は、実は調査者の魔法によって切り離された魂の一部だった。そのNPCは、調査者と融合し、調査者は功績点を1点獲得する。`,`無関係。その人物は、今回の事件に特に関係はなかった。しかし、この出会いは本当に無意味だったのだろうか？ 調査者は、その人物を対象として事件表を振ること。`]},cueball_table:{name:`奇人表`,type:`1D6`,items:[`寿命。その人物の命脈は尽きていた。この【秘密】が公開されると、その人物は死亡する。`,`殺意。その人物は、世の中に対する憎悪に溢れ、無差別に誰かを傷つけようとしていた。GMはサイクルの終わりにランダムにこの【秘密】の持ち主以外のNPCを一人選ぶ。そのNPCが〈断章〉に憑依されていない〈愚者〉なら死亡し、そうでなければ、この【秘密】の持ち主本人が死亡する。このとき、いずれにせよその死亡を望まないキャラクターは「闇」の分野かの中からランダムに特技一つを選び、判定を行うことができる。判定に成功するとその死亡を無効化できる。`,`強運。その人物は、一種の特異点で、とても強い幸運の持ち主だった。このNPCは、プライズとして扱う。このプライズの持ち主は、あらゆる行為判定を行うとき、プラス1の修正がつく。調査者は、このプライズを獲得する。`,`疵痕。その人物は、過去に魔法によって大切なものを奪われており、魔法とその関係者を憎んでいる。その人物がいるシーンでは、召喚と呪文の判定にマイナス2の修正がつく。`,`善人。その人物は、強く優しい精神の持ち主だった。その人物に対する【運命】を3点上昇する。`,`依代。その人物は、霊媒体質で何かに憑依されやすい。この人物に〈断章〉が憑依した場合、【攻撃力】と【防御力】が2点ずつ上昇する。この【秘密】が公開されると、GMはサイクルの終わりに〈断章〉一つを選び、その憑依の対象をこのNPCに変更することができるようになる。ただし、すでに魔法使いによって回収された〈断章〉を選ぶことはできない。`]},force_field_table:{name:`力場表`,type:`1D6`,items:[`加護。その人物の頭上には、常に星の恩寵が降り注いでいる。この【秘密】が公開されると、そのシーンに「星」の魔素が2点発生する。また、このセッションの間、この人物に対する【運命】が1点上昇したキャラクターは「星」の魔素を2点獲得する。`,`変化(へんげ)。その人物は、実は歳を経た動物―狐や狸などが化けた存在である。この【秘密】が公開されると、そのシーンに「獣」の魔素が2点発生する。また、このセッションの間、この人物に対する【運命】が1点上昇したキャラクターは「獣」の魔素を2点獲得する。`,`超能力。その人物には、ESPやPKなど、潜在的な超能力が眠っている。この【秘密】が公開されると、そのシーンに「力」の魔素が2点発生する。また、このセッションの間、この人物に対する【運命】が1点上昇したキャラクターは「力」の魔素を2点獲得する。`,`詩人。その人物は、詩神に祝福された存在である。この【秘密】が公開されると、そのシーンに「歌」の魔素が2点発生する。また、このセッションの間、この人物に対する【運命】が1点上昇したキャラクターは「歌」の魔素を2点獲得する。`,`夢想家。その人物には、大きな理想や実現したいと思っている夢がある。何か大きなことを成し遂げようとしている。。この【秘密】が公開されると、そのシーンに「夢」の魔素が2点発生する。また、このセッションの間、この人物に対する【運命】が1点上昇したキャラクターは「夢」の魔素を2点獲得する。`,`暗黒。その人物は、呪われた運命を背負っており、世界の破滅を呼び込む可能性を持っている。この【秘密】が公開されると、そのシーンに「闇」の魔素が2点発生する。また、このセッションの間、この人物に対する【運命】が1点上昇したキャラクターは「闇」の魔素を2点獲得する。`]},alliance_table:{name:`同盟表`,type:`1D6`,items:[`精霊。その人物は、実は姿を変え、人間界に顕現した精霊だった。象徴する特技は%{skill}である。調査者は、そのセッションの間だけ、その特技の【精霊召喚】を修得する。また、セッションに一度だけ、その【精霊召喚】の判定を自動的に成功にすることができる。`,`騎士。その人物は、実は姿を変え、人間界に顕現した騎士だった。象徴する特技は%{skill}である。調査者は、そのセッションの間だけ、その特技の【騎士召喚】を修得する。また、セッションに一度だけ、その【騎士召喚】の判定を自動的に成功にすることができる。`,`魔王。その人物は、実は姿を変え、人間界に顕現した魔王だった。象徴する特技は%{skill}である。調査者は、そのセッションの間だけ、その特技の【魔王召喚】を修得する。また、セッションに一度だけ、その【魔王召喚】の判定を自動的に成功にすることができる。`,`魔法屋。その人物は、魔法の道具を取引するタリスモンガーだった。以降、この人物のいるシーンでは、自分のチャージしている魔素1つを別の魔素1つに交換してもらうことができる。また、この人物のいるシーンでは、自分の装備魔法1つを修得可能な別の装備魔法1つに交換してもらうことができる。`,`師匠。その人物は、かつて調査者に魔法を教えた師匠だった。以降、この人物のいるシーンでは、自分の修得している特技1つを修得可能な別の特技1つに交換してもらうことができる。また、この人物のいるシーンでは、自分の呪文魔法1つを修得可能な別の呪文魔法1つに交換してもらうことができる。`,`無垢。その人物は、汚れ無き心の持ち主だった。このNPCは、プライズとして扱う。このプライズの持ち主は、セッション中に一度、【浄化】の呪文をコストなしで使用することができる。この判定は自動的に成功する。`]},tables:{TPT:{name:`時の流れ表`,type:`1D6`,items:[`標的となり追われる生活が続いた。ここ数年は苦しい戦いの日々だった。%{skill}の判定を行う。成功するとセッション終了時に追加の功績点1点。失敗すると「運命変転」発生。`,`冒険の日々の途中、大きな幸せが訪れる。%{skill}の判定を行う。成功すると、自分のアンカーの災厄か、自分の疵一つを無効化する。`,`瞑想から目を覚ます。もうそんな時間か。おかげで十分な魔素を得ることができた。「%{element}」「%{element}」「%{element}」の魔素を獲得する。`,`傷を癒すには十分な時間だ。自分の【魔力】を最大値まで回復する。もしくは「魔力のリセット」を行うことができる。好きな方を選ぶこと。`,`平穏な日々の中にも、ちょっとした事件が起きる。自分のアンカーを一人選んで「事件表」を振ることができる。`,`日々研鑚を重ね、魔法の修行に精進した。もしも望むなら、蔵書欄にある魔法を、自分の修得できる範囲の中で、現在とは別の魔法に変更して構わない。もしも、魔素がチャージされていた魔法を見習得にした場合、その魔素は失われる。`]},ST:{name:`シーン表`,type:`2D6`,items:[`魔法で作り出した次元の狭間。ここは時間や空間から切り離された、どこでもあり、どこでもない場所だ。`,`夢の中。遠く過ぎ去った日々が、あなたの前に現れる。`,`静かなカフェの店内。珈琲の香りと共に、優しく穏やかな雰囲気が満ちている。`,`強く風が吹き、雲が流されていく。遠く、雷鳴が聞こえた。どうやら、一雨きそうだ。`,`無人の路地裏。ここならば、邪魔が入ることもないだろう。`,`周囲で〈断章〉が引き起こした魔法災厄が発生する。%{skill}の判定を行うこと。成功すると、好きな魔素が一個発生する。失敗すると「運命変転表」を使用する。`,`夜の街を歩く。暖かな家々の明かりが、遠く見える。`,`読んでいた本を閉じる。そこには、あなたが知りたがっていたことが書かれていた。なるほど、そういうことか。`,`大勢の人々が行き過ぎる雑踏の中。あなたを気に掛ける者は誰もいない。`,`街のはるか上空。あなたは重力から解き放たれ、自由に空を飛ぶ。`,`未来の予感。このままだと起きるかもしれない出来事の幻が現れる。`]},FT:{name:`ファンブル表`,type:`1D6`,items:[`魔法災厄が、あなたのアンカーに降りかかる。「運命変転」が発生する。`,`魔法災厄が、あなたの魔素を奪い取る。チャージしている魔素の中から、好きな組み合わせで2点減少する。`,`魔法の制御に失敗してしまう。【魔力】が1点減少する。`,`魔法災厄になり、そのサイクルが終了するまで、行為判定にマイナス1の修正が付く。`,`魔法災厄が、直接あなたに降りかかる。変調表を振り、その変調を受ける。`,`ふぅ、危なかった。特に何も起こらない。`]},WT:{name:`変調表`,type:`1D6`,items:[`『封印』自分の魔法(習得タイプが装備以外)からランダムに一つ選ぶ。選んだ魔法のチェック欄をチェックする。その魔法を使用するには【魔力】を2点消費しなくてはいけない。`,`『綻び』魔法戦の間、各ラウンドの終了時に自分の【魔力】が1点減少する。`,`『虚弱』【攻撃力】が1点減少する。`,`『病魔』【防御力】が1点減少する。`,`『遮断』【根源力】が1点減少する`,`『不運』%{skill}のチェック欄をチェックする。その特技が使用不能になり、その分野の特技が指定特技になった判定を行うとき、マイナス1の修正が付く。`]},FCT:{name:`運命変転表`,type:`1D6`,items:[`『挫折』そのキャラクターは、自分にとって大切だった夢を諦める。`,`『別離』そのキャラクターにとって大切な人――親友や恋人、親や兄弟などを失う。`,`『大病』そのキャラクターは、不治の病を負う。`,`『借金』そのキャラクターは、悪人に利用され多額の借金を負う。`,`『不和』そのキャラクターは、人間関係に失敗し深い心の傷を負う。`,`『事故』そのキャラクターは交通事故にあい、取り返しのつかない怪我を負う。`]},AT:{name:`事件表`,type:`2D6`,items:[`不意のプレゼント、素晴らしいアイデア、悪魔的な取引……あなたは好きな魔素を1つ獲得するか【魔力】を1D6点回復できる。どちらかを選んだ場合、その人物に対する【運命】が1点上昇する。【運命】の属性は、ゲームマスターが自由に決定できる。`,`気高き犠牲、真摯な想い、圧倒的な力……その人物に対する【運命】が1点上昇する。【運命】の属性は「尊敬」になる。`,`軽い口論、殴り合いの喧嘩、魔法戦……互いに1D6を振り、低い目を振った方が、高い目を振った方に対して【運命】が1点上昇する。【運命】の属性は高い目を振った方が、自由に決定できる。`,`裏切り、策謀、不幸な誤解……その人物に対する【運命】が1点上昇する。【運命】の属性は「宿敵」になる。`,`意図せぬ感謝、窮地からの救済、一生のお願いを叶える……その人物に対する【運命】が1点上昇する。【運命】の属性は「支配」になる。`,`生ける屍の群れ、地獄の業火、迷宮化……魔法災厄に襲われる。%{skill}の判定を行う。成功すると好きな魔素が1点発生する。失敗すると、その人物に対し「運命変転表」を使用する。`,`道路の曲がり角、コンビニ、空から落ちてくる……偶然出会う。その人物に対する【運命】が1点上昇する。【運命】の属性は「興味」になる。`,`魂のひらめき、愛の告白、怪しい抱擁……その人物に対する【運命】が1点上昇する。【運命】の属性は「恋愛」になる。`,`師弟関係、恋人同士、すれ違う想い……その人物との未来が垣間見える。たがいに対する【運命】が1点上昇する。`,`懐かしい表情、大切な思い出、伴侶となる予感……その人物に対する【運命】が1点上昇する。【運命】の属性は「血縁」になる。`,`献身的な看護、魔法的な祝福、奇跡……その人物に対する【運命】が1点上昇する。【運命】の属性は自由に決定できる。もしも関係欄に疵があれば、その疵を1つ関係欄から消すことができる。`]},BGT:{name:`経歴表`,type:`1D6`,items:[`書警／ブックウォッチ`,`司書／ライブラリアン`,`書工／アルチザン`,`訪問者／ゲスト`,`異端者／アウトサイダー`,`外典／アポクリファ`]},DAT:{name:`初期アンカー表`,type:`2D6`,items:[`『恩人』あなたは、困っているところを、そのアンカーに助けてもらった。`,`『居候』あなたかアンカーは、どちらかの家や経営するアパートに住んでいる。`,`『酒友』あなたとアンカーは、酒飲み友達である。`,`『常連』あなたかアンカーは、その仕事場によくやって来る。`,`『同人』あなたは、そのアンカーと同じ趣味を楽しむ同好の士である。`,`『隣人』あなたは、そのアンカーの近所に住んでいる。`,`『同輩』あなたはそのアンカーと仕事場、もしくは学校が同じである。`,`『文通』あなたは、手紙やメール越しにそのアンカーと意見を交換している。`,`『旧友』あなたは、そのアンカーと以前に、親交があった。`,`『庇護』あなたは、そのアンカーを秘かに見守っている。`,`『情人』あなたは、そのアンカーと肉体関係を結んでいる。`]},FAT:{name:`運命属性表`,type:`1D6`,items:[`『血縁』自分や、自分が愛した者の親類や家族。`,`『支配』あなたの部下になることが運命づけられた相手。`,`『宿敵』何らかの方法で戦いあい、競い合う不倶戴天の敵。`,`『恋愛』心を奪われ、相手に強い感情を抱いている存在。`,`『興味』とても稀少だったり、不可解だったりして研究や観察をしたくなる対象。`,`『尊敬』その才能や思想、姿勢に対し畏敬や尊敬を抱く人物。`]},WIT:{name:`願い表`,type:`1D6`,items:[`自分以外の特定の誰かを助けてあげて欲しい。`,`自分の大切な人や憧れの人に会わせて欲しい。`,`自分をとりまく不幸を消し去って欲しい。`,`自分のなくした何かを取り戻して欲しい。`,`特定の誰かを罰して欲しい。`,`自分の欲望（金銭欲、名誉欲、肉欲、知識欲など）を満たして欲しい。`]},TCT:{name:`運命変転「典型的災厄」`,type:`1D6`,items:[`挫折。自分にとって大切だった夢をあきらめる。`,`別離。自分にとって大切な人―親友や恋人、親や兄弟などを失う。`,`大病。不治の病を負う。`,`借金。悪人に利用され、多額の借金を負う。`,`不和。人間関係に失敗し深い心の傷を負う。`,`事故。交通事故にあい、取り返しのつかないケガを負う。`]},PCT:{name:`運命変転「物理的災厄」`,type:`1D6`,items:[`火事。自分の家が焼け落ち、帰るところが無くなる。`,`盗難。自分の大切なものが盗まれ、失われる。`,`災害。自然災害に襲われ、生活環境が激変する`,`失明。眼が見えなくなる。`,`誘拐。何者かにさらわれ、監禁される。`,`傷害。通り魔やあなたを憎む者に傷を負わされる。`]},MCT:{name:`運命変転「精神的災厄」`,type:`1D6`,items:[`倦怠。疲労感に襲われ、何もやる気がなくなる。`,`家出。今、自分がいる場所に安らぎを感じなくなり、失踪する。`,`憎悪。周囲の誰かやPCに対して激しい憎悪を抱くようになる。`,`不眠。眠れなくなり、疲労する。`,`虚言。本当のことを話せなくなってしまう。`,`記憶喪失。友達やPCのことを忘れてしまう。`]},ICT:{name:`運命変転「狂気的災厄」`,type:`1D6`,items:[`二重人格。もう一つの人格が現れ、勝手な行動を始める。`,`恐怖。高所や異性、蜘蛛など、特定の何かに対する恐怖症になる。`,`妄想。突拍子もない奇妙な妄想が頭を離れなくなる。`,`偏愛。特定の物や状況などに熱狂的な愛情を示すようになる。`,`暴走。時折、自分の感情が制御できなくなり、凶暴化する。`,`発情。体温が上昇、脈拍が増大し、性的に興奮状態になる。`]},SCT:{name:`運命変転「社会的災厄」`,type:`1D6`,items:[`逮捕。無実の罪で捕らわれ、留置される。`,`裏切り。信頼していた人物に騙されたり、恋人に浮気されたりする。`,`暴露。自分の隠しておきたい秘密を暴露される。`,`籠絡。どう見てもよくない相手に心を奪われる。`,`加害。人を傷つけたり、殺めたりしてしまう。`,`多忙。とてつもない量の仕事に追われ、心身共に疲労する。`]},XCT:{name:`運命変転「超常的災厄」`,type:`1D6`,items:[`霊感。見えるはずのないものが見えるようになる。`,`不運。身の回りで、不幸な偶然が頻発するようになる。`,`感染。吸血鬼やゾンビなど、怪物になりかかってしまう。`,`阻害。自分の存在が、魔法的存在以外から見えなくなってしまう。`,`変身。姿が動物や別の人間に変わってしまう。`,`標的。殺人鬼や魔法災厄など、悪意を引き寄せてしまう。`]},WCT:{name:`運命変転「不思議系災厄」`,type:`1D6`,items:[`邪気眼。ついつい痛い言動を繰り返すようになってしまう。`,`ドジ。ありえないほどよく転び、物を壊す体質になってしまう。`,`方向音痴。信じられないくらい道に迷うようになってしまう。`,`変語尾。なぜか、自分が話す言葉の語尾が変になってしまう。`,`ひらがな。話す言葉が全てひらがなで聞こえるようになる。`,`ヤンデレ。PCのことを病的に愛するようになり、自分以外にPCへの好意を持つ者に対して攻撃的になる。`]},CCT:{name:`運命変転「コミカル系災厄」`,type:`1D6`,items:[`性別逆転。自分の肉体の性別が逆転してしまう。`,`猫耳。頭から猫耳が生える。`,`太る。びっくりするほど太る。`,`足がくさい。哀しくなるほど足がくさくなる。`,`ハラペコ。一回の食事で、ご飯を二十杯くらいおかわりしないと空腹でなにもできなくなる。`,`脱衣。その場ですべての服が脱げる。`]},BST:{name:`ブランク秘密表`},PT:{name:`プライズ表`,type:`2D6`,items:[`敗者は内側から破裂し、四散する。功績点を1点獲得する。`,`敗者は無数の蟲や小動物へと姿を変え、それを使い魔とする。勝者は好きな特技(魂の特技は除く)を一つ選ぶ。そのセッションの間、指定特技がその特技の【精霊召喚】【魔剣召喚】【悪夢召喚】のうち一つを修得する。`,`敗者は爆発音と共にどこかへと消え、辺りには硫黄のような匂いだけが残る。勝者はそのセッション中に、一度だけ好きなタイミングで「変調」一種を回復することができる。`,`敗者は奇妙な形をした数枚の金貨へと姿を変える。勝者は倒した相手のランクと等しい魔貨を獲得する`,`敗者は地面から突如現れた無数の腕に引き込まれながら、勝者に向かって賞賛の言葉と共に重要な何かを語る。公開されているハンドアウト一つを選び、その【秘密】を公開する。`,`敗者は無数の光の粒へとなっていき、そこから魔素を得る。勝者は好きな魔素を2点獲得する(立会人に渡してもよい)。`,`敗者はバラバラのページとなって地面に散らばり、そこから未知の力を読み取る。勝者は【一時的魔力】を2点獲得する。`,`敗者は妙なる音楽へと変わり、その曲は勝者の心にしみいる。勝者は倒した相手のランクと等しい魔貨を獲得する。`,`敗者は一輪の花となる。勝者はそのセッション中に、一度だけ自分が振った行為判定のサイコロを振り直す権利を得る。`,`敗者は言葉のかけらとなっていき、勝者はそこから未来の運命を読み取る。勝者は「事件表」を使用し、その結果を記録しておく。それ以降、そのセッション中のドラマシーンに、同じシーンに登場しているキャラクター一人を選び、一度だけその結果を適用できる。`,`敗者は影となって、その場に焼き付き、異境への入り口となる。勝者は、好きな異境を一つ選ぶ。そのセッションの間、その異境へ移動できるようになる。`]},XEST:{name:`極限環境シーン表`,type:`2D6`,items:[`上下左右も分からない、完全なる闇。このシーンに登場しているPCのうち一人は、≪光≫の判定を行う。成功すると、闇の魔素二個を獲得する。失敗すると、｢遮断｣の変調を受ける。誰かが判定を行うと、成否に関わらずこの効果はなくなる。`,`眼前に広がる業火の海。何もかも喰らい尽すような敵意は圧倒的だ。≪炎≫の判定を行う。失敗すると【魔力】が2点減少する。`,`激しい天候で地形が一変する。さきほどまでの光景が嘘のようだ。≪嵐≫で判定を行う。失敗すると、【魔力】が1点減少する。`,`どこまでも続く、砂漠。舞い上がる砂塵に、目を開けていられない。≪大地≫の判定を行う。失敗すると、｢封印｣の変調を受ける。`,`言葉さえも凍り付きそうな極寒。生き物の気配は感じられない。【魔力】が1点減少する。`,`苛酷な自然環境によってキミたちは窮地に立たされる。%{skill}の判定を行うこと。成功すると、なんとか使えそうなものを探し、好きな魔素が一個発生する。失敗すると、キミの負った傷は時間と空間を超えて、キミのアンカーに不幸をもたらす。「運命変転」が発生する。`,`一面の雪野原に、てんてんと足跡が残っている。どうやら、先客がいるらしい。`,`切り立つ崖の上。眼下には大きな海が広がっている。上空からは海鳥の鳴き声が聞こえてくる。`,`高重力の地。身体全体が鉛に変わってしまったかのように感じられる。≪重力≫の判定を行う。失敗すると【魔力】が1点減少する。`,`深い水の底。青に染まった空間に、何かが漂っている。このシーンに登場しているPCのうち一人は≪海≫の判定を行うことができる。成功すると、星の魔素を三個獲得する。失敗すると、【魔力】が2点減少する。誰かが判定を行うと、成否にかかわらずこの効果はなくなる。`,`鼓膜を破りそうな、轟音が鳴り響く。言葉による意思の疎通は諦めた方がよさそうだ。≪旋律≫の判定を行う。失敗すると、チャージしているまその中から好きなものを二個失う。`]},IWST:{name:`内面世界シーン表`,type:`2D6`,items:[`肌の色と熱い吐息で満たされた場所。無数の男女が、思いつく限りの肉の欲望を実践している。このシーンに登場しているPCのうち一人は、≪エロス≫の判定を行うことができる。成功すると【一時的魔力】を1点獲得する。失敗すると【魔力】が2点減少する。誰かが判定を行うと、成否にかかわらずこの効果はなくなる。`,`壁一面に、黒光りする虫がびっしりと張り付き、羽音を立てている部屋。この精神の持ち主は、虫が好きなのだろうか、嫌いなのだろうか。このシーンに登場しているPCのうち一人は、≪蟲≫の判定を行うことができる。成功すると、元型「蟲の騎士」をそのセッションの間、相棒にできる。相棒は、破壊か消滅するまで、自分が何らかのシーンに登場すると、そのシーンの種類に関わらず、同じタイミングで召喚される。失敗すると、虫が一斉に飛び立ち、そのシーンに登場しているPC全員の【魔力】が1点減少する。誰かが判定を行うと、成否にかかわらずこの効果はなくなる。`,`誰もいない教室。なぜか、ヒソヒソと囁く声がどこからともなく聞こえ、見られているような視線を感じる。このシーンに登場しているPCのうち一人は、≪不安≫の判定を行うことができる。成功すると、公開されているハンドアウトの中から、好きな【秘密】を公開することができる。失敗すると、「遮断」の変調を受ける。誰かが判定を行うと、成否にかかわらずこの効果はなくなる。`,`薄暗いが暖かく、ひどく安らぐ空間。ここはまるで、母親の胎内のようだ。このシーンに登場しているPCが、魔素を消費して、【魔力】の回復を行う場合、魔素一個につき、【魔力】を2点回復できる。`,`遊園地。賑やかなパレードが目の前を通り過ぎて行くが、客は一人もいない。`,`夜の道。もやもやと黒いものが後ろから、追いかけてくる。はっきりした姿も分からないのに、ひどく恐ろしく感じる。このシーンに登場するPCは、%{skill}の判定を行う。成功すると、好きな魔素二個を獲得できる。失敗した場合、もやもやとした黒いものは君のアンカーの前に現れる。「運命変転」が発生する。`,`夕暮れの街。なんだか寂しい気分になる。`,`床、壁、天井までが赤黒い色に染まった部屋。生臭い臭いが充満している。このシーンに登場しているPCのうち一人は≪血≫で判定を行うことができる。成功すると、【一時的魔力】2点を獲得する。失敗すると【魔力】が1点減少する。誰かが判定を行うと、成否にかかわらずこの効果はなくなる。`,`どこへとも行くか知れぬ電車の中。あなたの他に乗客はいないようだが……。このシーンに登場しているPCのうち一人は≪異界≫で判定を行うことができる。成功すると、好きな異境一つに行くことができる魔法門を発見できる。失敗するとこのシーンに登場しているPC全員の【魔力】が2点減少する。誰かが判定を行うと、成否にかかわらずこの効果はなくなる。`,`大勢の人が行き交う雑踏の中。誰も、あなたに関心を払わない。このシーンでは「不干渉」の世界法則を無視して、好きなキャラクターを調査することができる。`,`どことも知れぬ空間。あなたの最も愛しい人が、目の前に現れる。このシーンに登場しているPCのうち一人は、≪情熱≫の判定を行うことができる。成功すると、好きなアンカーに対する【運命】を1点上昇させることができる。失敗すると、「運命変転」が発生する。誰かが判定を行うと、成否にかかわらずこの効果はなくなる。`]},MCST:{name:`魔法都市シーン表`,type:`2D6`,items:[`急に爆発が起こる。誰かが実験で失敗したらしい。「綻び」の変調を受けた後、「力」の魔素を二個獲得する。`,`標本の並ぶ地下室。実験によって生み出された魔法生物が、瓶詰めにされて並んでいる。`,`ごった返す市場。色とりどり食料品や日用品を始め、幻獣の目玉やマンドラゴラの根といった、魔法の触媒となる品までが商われている。このシーンに登場しているPCは、一人一度だけ、功績点1点を消費することで、好きな魔素を二個獲得することができる。`,`魔法使いたちの集うサロン。ここなら、有益な情報が得られそうだ。このシーンに登場しているPCのうち一人は、≪物語≫の判定を行うことができる。成功すると、公開されているハンドアウトの中から、好きな【秘密】を公開することができる。失敗すると「封印」の変調を受ける。誰かが判定を行うと、成否にかかわらずこの効果はなくなる。`,`大通り。幻獣の引く馬車や、絨毯や箒などの空飛ぶ乗り物が、せわしなく通り過ぎる。`,`広場。魔法使い同士が喧嘩を始め、魔法が飛び交い始める。このシーンに登場したPCは、%{skill}で判定を行う。成功すると、好きな魔素を二個獲得する。失敗すると、この場所の魔法の影響が時空を超えて、アンカーに現れる。「運命変転」が発生する。`,`賑わう酒場。客の中には妖精や魔物たちの姿も多い。このシーンに登場したPCは、【魔力】が1点回復する。`,`入り組んだ路地裏。奇妙な異種族たちで構成された盗賊団に襲われる。≪雷≫で判定を行う。失敗すると【魔力】が2点減少するか、もし魔法にチャージした魔素を二個以上持っていればそれを消費するか、どちらかを選ぶ。`,`都市の門。新たなる知識を求めてやってきた者、自分の世界へ帰る者、様々な世界の様々な人々が行き来する。`,`歓楽街。角や尻尾、翼を持つ、肌もあらわな美女たちが、なまめかしい視線を送ってくる。このシーンに登場しているPCのうち一人は、≪エロス≫で判定を行うことができる。成功すると、元型「エロスの乙女」をそのセッションの間、相棒にできる。相棒は、破壊か消滅するまで、自分が何らかのシーンに登場すると、そのシーンの種類に関わらず、同じタイミングで召喚される。失敗すると【魔力】が1点減少する。誰かが判定を行うと、成否にかかわらずこの効果はなくなる。`,`闘技場。魔法使いが、強化した元型や幻獣を競い合わせている。シーンプレイヤーのPCは、一度だけ、基本ルールブックに載っている、ランク4以下の〈書籍卿〉か〈越境者〉に、魔法戦を挑むことができる。勝利すると、「プライズ表」を使用することができる。`]},WDST:{name:`死後世界シーン表`,type:`2D6`,items:[`寂しげな村。影のような人々が時折行き来する。ここでは、死んだキャラクターに会うことができる。このシーンに登場しているPCのうち一人は、疵をひとつだけ、克服することができる。`,`どこまでも広がる花畑。穏やかな雰囲気に満たされている。`,`裁判所。強面の裁判官が、溢れる死者の群れに、次々と裁きを下している。≪嘘≫の判定を行う。失敗すると、【魔力】が2点減少する。`,`白い光に包まれた食堂。豪勢な食事と美酒が、尽きることなく振る舞われる。このシーンに登場しているPCのうち一人は、≪肉≫の判定を行うことができる。成功すると、【一時的魔力】を1点獲得する。失敗すると、「病魔」の変調を受ける。誰かが判定を行うと、成否にかかわらずこの効果はなくなる。`,`床が白い雲になっている場所。雲の隙間からは、現世のような風景が見える。%{skill}の判定を行う。成功すると、このセッション中一度だけ、判定のサイコロを振り直すことができる。失敗すると、時空を越えて、アンカーが死後世界を垣間見てしまう。「運命変転」が発生する。`,`広い川の岸辺。向こう岸は、現世なのだろうか。このシーンに登場しているPCのうち一人は≪円環≫の判定を行うことができる。成功すると、魔力をリセットできる。誰かが判定を行うと、成否にかかわらずこの効果はなくなる。`,`礼拝堂。死んでもなお、祈り続ける魂が、無言で跪いている。このシーンに登場しているPCのうち一人は、≪祈り≫の判定を行うことができる。成功すると、【一時的魔力】を2点獲得する。失敗すると、「不運」の変調を受ける。誰かが判定を行うと、成否にかかわらずこの効果はなくなる。`,`ごく普通の住宅街。日常の営みを繰り返す魂の集う場所だ。`,`拷問場。鬼たちが、使者に無限の責め苦を味合わせている。このシーンに登場しているPCのうち一人は、≪絶望≫の判定を行うことができる。成功すると、【一時的魔力】を2点獲得する。失敗すると、「綻び」の変調を受ける。誰かが判定を行うと、成否にかかわらずこの効果はなくなる。`,`戦場。羽兜の乙女に率いられた戦士たちが、巨人と戦いを繰り広げている。このシーンに登場しているPCのうち一人は、≪天空≫で判定を行うことができる。成功すると、【一時的魔力】を3点獲得する。失敗すると、【魔力】が3点減少する。誰かが判定を行うと、成否にかかわらずこの効果はなくなる。`,`どことも知れぬ空間。あなたの最も愛しい人が、目の前に現れる。このシーンに登場しているPCのうち一人は、≪情熱≫の判定を行うことができる。成功すると、好きなアンカーに対する【運命】を1点上昇させることができる。失敗すると、「運命変転」が発生する。誰かが判定を行うと、成否にかかわらずこの効果はなくなる。`]},LWST:{name:`迷宮世界シーン表`,type:`2D6`,items:[`がらんとした、石畳の部屋。床に描かれた魔法陣が、不気味な光を放っている。このシーンに登場しているPCのうち一人は、≪異界≫で判定を行うことができる。成功すると、その魔法陣を地球に帰還できる魔法門として使用できる。失敗すると、魔法門から現れた道の怪物に襲われ、このシーンに登場しているPC全員の【魔力】が1D6減少する。誰かが判定を行うと、成否にかかわらずこの効果はなくなる。`,`微かなランプの明かりに照らし出される牢獄。檻の中には、誰かの朽ちた骸が転がっている。このシーンに登場しているPCのうち一人は、≪死≫で判定を行うことができる。成功すると公開されているハンドアウトの中から、好きな【秘密】を公開することができる。失敗すると、死体が呪詛の言葉を吐き、このシーンに登場しているPC全員が「綻び」の変調を受ける。誰かが判定を行うと、成否にかかわらずこの効果はなくなる。`,`通路の先に、扉と看板がある。看板の文字は宿屋と読める。このシーンに登場しているPC全員は、一度だけ、功績点1点を消費することで、調律を一度行うことができる。`,`人一人通るのが、やっとの狭い通路が続いている。この廊下はどこまで伸びているのだろう?`,`幾つもの扉と幾つもの分かれ道を進む。おや？いつの間にか、きみは迷ってしまった。シーンプレイヤー以外のPCが、このシーンに登場しようとする場合、≪道≫で判定を行う。失敗したPCは、このシーンに登場できない。`,`怪物が現れ、キミたちを襲う。このシーンに登場しているPC全員は、%{skill}の判定を行うこと。成功すると、怪物を倒し、好きな魔素が一個発生する。失敗すると、キミの負った傷は時間と空間を越えて、キミのアンカーに不幸をもたらす。「運命変転」が発生する。`,`目の前には、似たような扉がずらりとならんでいる。どの扉を開いたものか?`,`暗闇の中から、うなり声が聞こえてくる。どうやら、近くに怪物が潜んでいるようだ。うまくやりすごせないものか……。≪静寂≫で判定を行う。失敗すると、【魔力】が1点減少する。`,`通路が途切れ、深い谷が口を開けている。谷底まで光は届かず、まるで地の底まで続いているかのようだ。「闇」の魔素を一個獲得できる。`,`金貨や銀貨、宝石に王冠、山のような宝物の積み上げられた部屋。番人は見当たらないが……。このシーンに登場しているPCのうち一人は、≪黄金≫で判定を行うことができる。成功すると1D6点の魔貨かランダムに決定した魔素三個を獲得できる。失敗すると、このシーンに登場しているPC全員の【魔力】が1点減少する。誰かが判定を行うと、成否にかかわらずこの効果はなくなる。`,`行き止まりの壁には、一見、意味不明な文字が並んでいる。ここから先に進むためには、この文字の謎を解かねばならないのだろうか。このシーンに登場しているPCのうち一人は、≪謎≫で判定を行うことができる。成功すると公開されているハンドアウトの中から、好きな【秘密】を公開することができる。失敗すると、部屋に仕掛けられた罠が発動し、このシーンは強制的に終了する。誰かが判定を行うと、成否にかかわらずこの効果はなくなる。`]},STB:{name:`大判シーン表`,type:`2D6`,items:[`ここではないどこか。魔法の力が満ちた異境の一つへ、一瞬だけ旅をする。そのシーンに星の魔素が1点発生する。`,`夢の中。遠く過ぎ去った日々が、あなたの前に現れる。そのシーンに夢の魔素が1点発生する。`,`強く風が吹き、雲が流されていく。遠く、雷鳴が聞こえた。そのシーンに力の魔素が1点発生する。`,`静かなカフェの店内。珈琲の香りと共に、優しく穏やかな雰囲気が満ちている。`,`無人の路地裏。ここならば、邪魔が入ることもないだろう。`,`周囲で〈断章〉が引き起こした魔法災厄が発生する。%{skill}の判定を行うこと。成功すると、そのシーンに好きな魔素が1点発生する。失敗すると、「運命変転表」を使用する。`,`なんの変哲もないおだやかな風景。しかし、その日常の背後で魔法災厄の影を感じる。`,`読んでいた本を閉じる。そこには、あなたが知りたかったことが書かれていた。なるほど、そういうことか。`,`夜の街を歩く。暖かな家々の明かりが、遠く見える。そのシーンに歌の魔素が1点発生する。`,`大勢で賑わう広場。祭りでも行われているのだろうか？ 誰かを呼ぶ声が聞こえる。そのシーンに獣の魔素が1点発生する。`,`悲劇の予感。家族の不幸、友の絶望、仲間の死......このままだと起きてしまうかもしれない出来事の幻が見える。そのシーンに闇の魔素が1点発生する。`]},MGCT:{name:`運命変転「魔法使いの災厄」`,type:`1D6`,items:[`嫌悪。〈愚者〉たちを嫌悪し、〈大法典〉のやり方に疑問を覚えるようになる。この不幸が二度発生すると、その魔法使いは死亡しないで〈書籍卿〉になり、NPCとなる。この不幸が〈書籍卿〉に降り注いだ場合、不幸は無効化される。`,`悪心。魔法に関する強い願いや邪悪な欲望が肥大化していく。この不幸が二度発生すると、その魔法使いは死亡した後〈禁書〉となり、NPCとなる。`,`幽霊。肉体がほとんど失われ、霊的存在になる。この不幸が二度発生すると、その魔法使いは死亡ではなく消滅する。`,`連鎖。運命変転が発生する。この不幸が二度発生しても死亡しない。`,`変調。ランダムに変調1つを受ける。この不幸が二度発生しても死亡しない。`,`消耗。【魔力】が1点減少する。この不幸が二度発生しても死亡しない。`]},MBST:{name:`魔法書架シーン表`,type:`2D6`,items:[`〈禁書〉の保管庫へ入ることを許可された。幾重にも張り巡らされた決壊や、鋭い目つきの書警たちが目に付く。その隙をついて、〈禁書〉が襲い掛かってきた！このシーンに登場したPCは一人だけ《%{force}》の判定を行う。失敗すると、【魔力】が3点減少する。成功すると、【一時的魔力】を3点得る。誰かが判定すると、成否にかかわらず、この効果はなくなる。`,`私室。狭いけれど、一番落ち着ける場所だ。このシーンに登場しているPCのうち一人は、【魔力】を上限まで回復させることができる。`,`町の図書館。いつのまにか、人界に戻ってきてしまったようだ。このシーンに登場しているPCのうち一人は、好きなキャラクターを1人選び、事件表を一回振って、その効果を適用する。`,`巨大な円卓がしつらえられた部屋。どうやらここは、会議場のようだ。`,`長い廊下。学院の制服に身を包んだ少年少女が、笑いさざめきながら駆けていく。`,`荒れ果てた部屋。倒れた空っぽの本棚が、目に付く。これは〈大破壊〉の影響なのだろうか…。このシーンに登場するPCは、%{skill}の判定を行う。失敗すると、時空を超えてアンカーに影響が現れる。「運命変転」が発生する。`,`倉庫。未整理の本が山のように積まれて、司書たちが分類整理に追われている。`,`誰かの研究室に迷い込む。積まれている魔導書が興味深い。`,`高い天井と、天井まで続く壁を埋め尽くす、本の群れ。このすべてが、この書庫に所蔵された魔導書だ。このシーンに登場しているPCのうち一人は、【一時的魔力】を1点獲得する。`,`魔導書の閲覧室。数人の魔法使いが、熱心に魔導書を読んでいる。このシーンに登場しているPCのうち一人は、%{skill}の判定を行うことができる。成功すると、修得している魔法を一つ、修得可能な別の魔法に入れ替えることができる。失敗すると、「封印」の変調を受ける。誰かが判定すると、成否にかかわらず、この効果はなくなる。`,`本棚と本棚の間に、唐突に扉が浮かんでいる。この扉は、異界につながる戸口だ。一体どこにつながっているのだろう。異界シーン表の中からランダムに一つを選んで、その効果を適用する。`]},MAST:{name:`魔法学院シーン表`,type:`2D6`,items:[`目の前に美しい黒龍が現れた。学院の長、ザナルパトスだ。彼は、何を告げようとしているのだろうか。`,`突然何かが襲い掛かってきた！生徒が元型の召喚に失敗したようだ。このシーンに登場しているPCのうち一人は、≪%{force}≫の判定を行う。失敗すると、【魔力】が3点減少する。成功すると、【一時的魔力】を3点得る。誰かが判定すると、成否にかかわらず、この効果はなくなる。`,`ここは女子寮？このシーンに男性のPCが登場した場合、その男性PCは≪%{beast}≫の判定を行う。失敗すると、「封印」の変調を受ける。`,`寮の廊下。「どなたですか？」寮監のシグリットに呼び止められた。このシーンに登場しているPCは≪自由≫で判定を行う。失敗すると、このシーンで行う判定すべてにマイナス1の修正を受ける。`,`天井の高い廊下。分厚い扉の向こうからかすかに授業を行う講師の声が聞こえてくる。`,`扉を開けて現れたのは、よく知る相手だった。なぜか、学院に迷い込んでしまったようだ。%{skill}で判定を行う。失敗すると、「運命変転」が発生する。`,`誰かが作った秘密の小部屋に迷い込んでしまう。学院ではあまり食べられないお菓子が山のように仕舞われているようだ。`,`学院西部に広がるアーデンの森。鳥の鳴き声が聞こえる。`,`授業を行っている教室。講師が呼び出した元型がこちらに向かって飛んでくる。このシーンに登場しているPCは一人だけ%{skill}で判定を行う。失敗すると【魔力】が1点減少する。成功すると、その特技の精霊が召喚できる。誰かが判定すると、成否にかかわらず、この効果はなくなる。`,`生徒に何か魔法を見せて欲しいと乞われる。このシーンに登場しているPCは一人だけ、≪%{dream}≫の判定を行う。失敗すると、「不運」の変調を受ける。成功すると、「夢」の魔素をを2点獲得する。誰かが判定すると、成否にかかわらず、この効果はなくなる。`,`自習室。生徒たちが必死に魔導書を理解しようとしている。このシーンに登場しているPCは一人だけ、≪%{star}≫の判定を行う。成功すると、好きな魔素をを2点獲得する。誰かが判定すると、成否にかかわらず、この効果はなくなる。`]},TCST:{name:`クレドの塔シーン表`,type:`2D6`,items:[`目の前に一人の少女が現れる。眠り姫の長、ラトゥナだ。ずっと眠り続けている筈の彼女が現れたのは、いったい何を告げるためなのだろうか。`,`突然何かが襲い掛かってきた！未熟な魔法使いが元型の召喚に失敗したようだ。このシーンに登場しているPCは一人だけ、≪%{force}≫の判定を行う。失敗すると、【魔力】が3点減少する。成功すると、【一時的魔力】を3点得る。誰かが判定すると、成否にかかわらず、この効果はなくなる。`,`話しかけてきた天涯預言者が、不幸な未来を予言する。このシーンに登場しているPCは一人だけ、≪%{dream}≫の判定を行う。失敗すると、【魔力】が1点減少する。成功すると、「夢」の魔素をを1点獲得する。誰かが判定すると、成否にかかわらず、この効果はなくなる。`,`塔の内側の壁に並ぶ、無数の魔道書の前。この中から、なにかの手がかりが得られるかも知れない。このシーンに登場しているPCのうち一人は、【一時的魔力】を1点獲得する。`,`小さな客間で〈大法典〉からの使者との会合が行われている。天涯が新たな予言を伝えているのかも知れない。`,`こんな場所にいる筈のない人が君の前にあらわれる。眠り姫の眠りの中に迷い込んでしまったらしい。%{skill}で判定を行う。失敗すると、「運命変転」が発生する。`,`塔の上。山脈の連なりとその上に浮かぶ月が、塔を静かに見下ろしている。`,`塔の外壁に作られた螺旋階段の上。強い風が吹き付けている。`,`クレドの塔に続く、険しい山道。何かが潜んでいるんだろうか…。「獣」の魔素を1点獲得できる。`,`幻夢殿の中。眠り姫達の安らかな寝息が聞こえてくる。こちらも眠くなってくる。`,`突然、目の前に扉が現れる。この扉は、異界につながる戸口だ。一体どこにつながっているのだろう。異界シーン表の中からランダムに一つを選んで、その効果を適用する。`]},PWST:{name:`並行世界シーン表`,type:`2D6`,items:[`カフェのテーブル。FMラジオは、去年解散したはずのバンドの、先日発表した新曲を流している。このシーンに登場しているPCのうち一人は、「時の流れ表」を1回振り、効果を適用する。`,`賑やかな通り。向こうから、あなたにそっくりな人物が歩いてくる。あれはこの世界の、あなた自身だろうか。このシーンに登場しているPCの一人は、%{skill}の判定を行う。成功すると、好きな魔素をを2点獲得する。失敗すると、「病魔」の変調を受ける。誰かが判定すると、成否にかかわらず、この効果はなくなる。`,`夜の街を歩く。よく知っている筈の風景なのに、どこか違うという違和感がぬぐえない。`,`買い物客でにぎわう商店街。つぶれたはずの店が健在であったり、繁盛しているはずの店が潰れていたりしている。`,`繁華街。ビルの大型ビジョンから、知らない国同士の戦争に関するニュースが流れている。`,`縁のある人の家の前。玄関から、見知らぬ人が現れ、こちらを不審げに眺めている。この人はもしかして…？%{skill}で判定を行う。失敗すると、「運命変転」が発生する。`,`乗客のいない電車の中。時折、聞き覚えのない駅名がアナウンスされる。`,`学校帰りの学生たちが目立つ、駅前のロータリー。あの学校の制服のリボンは、赤だっただろうか？`,`洋館の前。ここに、こんな建物はなかった筈だが。`,`小学校の前を通る。音楽室の窓から、見知らぬ音楽家の肖像が見える。≪%{poem}≫の判定を行う。失敗すると、「封印」の変調を受ける。`,`目の前で、以前、経験した出来事が起きる。この世界では、これは、今から起きる出来事なのだ。このシーンに登場しているPCのうち一人は、このシーンの間、判定に+1の修正を受ける。`]},PAST:{name:`終末シーン表`,type:`2D6`,items:[`夜。雨宿りのために足を踏み入れた寺院に危険は気配はなく、ゆっくり休めそうだ。静に時が流れていく。`,`夜。雑草が生い茂り、ツタに覆われた人気のない山村で巨大な肉食獣が襲い掛かってくる。このシーンに登場しているPCのうち一人は、≪牙≫の判定を行わなければならない。失敗すると、【魔力】が2点減少する。誰かが判定すると、成否にかかわらず、この効果はなくなる。`,`夜。大規模な爆撃で地平線と化した戦場跡。どこの国ともわからぬ国旗が夜風に吠えている。虚憑が一体襲い掛かってくる。魔法戦を行うこと。この魔法戦はゲーム中に一度だけ発生する。`,`夜。もはや廃墟と化した埃っぽい都市。〈愚者〉が虚憑に襲われている。このシーンに登場しているPCの一人は、%{skill}の判定することができる。成功すれば救出でき、助け出した〈愚者〉に対し、好きな属性で運命を1点獲得する。失敗すると【魔力】を3点失う。`,`夜。虚憑の群れに付きまとわれる。シーンプレイヤーは≪悪意≫の判定を行う。失敗するとこのシーンの間、あらゆる判定がマイナス2される。`,`夜明け前。ハイウェイが一直線に突き抜ける灰色の荒野。静かすぎて自らの鼓動を感じるほどだ。虚憑が一体襲い掛かってくる。魔法戦を開始すること。2ラウンド経過するまでは夜、以降のラウンドは昼として処理する。この魔法戦はゲーム中に一度だけ発生する。`,`昼。〈愚者〉の子供が、歴史的な遺産を遊び場に、一人遊びをしている。この子の未来はどうなるのだろうか。`,`昼。世界大戦で墜落した戦闘機が、砂漠の砂に半ば埋もれている。だが、そのエンジンは死んでいない。このシーンに登場しているPCの一人は≪風≫で判定を行うことができる。成功すると魔力のリセットを行う。成否にかかわらず、この効果は一度だけ発生する。`,`昼。広い建物が並ぶ美しい海岸。かつてはリゾート地だったそこには、白い遺骨が大量に打ち上げられ、潮騒に洗われている。誰か一人が≪別れ≫の特技の判定に成功すると、ランダムに選んだ魔素3点を獲得する。誰かが判定すると、成否にかかわらず、この効果はなくなる。`,`昼。崩壊した農村のかたわらで、美味しそうな果実を発見する。≪大地≫の判定に成功すると【魔力】が2点回復する。`,`夕刻。錆び付いた線路。その先までたくさんのしゃれこうべが無造作に転がっている。虚憑が一体襲い掛かってくる。魔法戦を開始すること。2ラウンド経過するまでは昼、以降のラウンドは夜として処理する。この魔法戦はゲーム中に一度だけ発生する。`]},GBST:{name:`異世界酒場シーン表`,type:`2D6`,items:[`マスターの雷神に絡まれる。このシーンに登場しているPCのうち一人は、雷神相手に「事件表」を振る。`,`神々しく光輝く、威厳に溢れた神が現れ、場の雰囲気を支配する。このシーンの間、「世界法則」に「調査阻害」が加わる。`,`上の階に登ろうとすると、キマイラが待ち構えている。このシーンに登場しているPCのうち一人は、≪炎≫で判定を行う。失敗すると、【魔力】が1点減少する。成功するまで判定を行うこと。この効果は一度だけ発生する。`,`「かんぱーい！」注がれた酒をつい飲んでしまう。ずいぶん強いスピリッツのようだが。このシーンに登場しているPCのうち一人は、≪水≫で判定を行うことができる。成功すると魔貨を1点手に入れる。成否にかかわらずこの効果は一度だけ発生する。`,`乾杯のかけ声、酔っ払いの笑い声、あちこちのテーブルでは大きな話し声…。どこにでもある、酒場の光景だ。`,`客の一人に、無理矢理酒を飲まされる。なんて強い酒だろう。%{skill}で判定を行う。失敗すると、「運命変転」が発生する。`,`階段を上っている。いったいいつから登り始めたのか記憶にない。これはどこまで続くのだろう。`,`建物の中の筈なのに、雷雲が立ちこめ、嵐が巻き起こる。神々がケンカしている！このシーンに登場しているPCのうち一人は、≪嵐≫で判定を行う。失敗すると、【魔力】が2点減少する。成否にかかわらずこの効果は一度だけ発生する。`,`扉の前に、妖怪が張り付いていて、通してくれない。妖怪は何かくれと強請ってくる。このシーンに登場しているPCのうち一人は、好きな魔素を1点減少する。減少する魔素がない場合、【魔力】が1点減少する。`,`上の階に登ろうとすると、竜が待ち構えている。このシーンに登場しているPCのうち一人は、≪牙≫で判定を行う。失敗すると、「綻び」の変調を受ける。成否にかかわらず、この効果は一度だけ発生する。`,`美しい女神が、鏡をのぞき込んでいる。どうやら、運命が映る鏡だと言うのだが。このシーンに登場しているPCのうち一人は、≪未来≫で判定を行っても良い。成功すると好きなアンカーとの【運命】が1点上昇する。成否にかかわらず、この効果は一度だけ発生する。`]},SLST:{name:`ほしかげシーン表`,type:`2D6`,items:[`あなたの持つ「切符」は無効であると車掌に告げられる。他の乗客の視線を感じる。このシーンに登場しているPCのうち一人は、もう一度「切符」を調達しなければならない。魂の特技の判定を、成功するまで繰り返すこと。`,`ごとごと。ごとごと。ガラスより透き通る銀河の水辺を走る。色とりどりの花々が星の光に冴え渡っては通り過ぎて行く。`,`ふと目を覚ます。汽車に揺られていつの間にか眠っていたらしい。夢の中で誰かと会っていた気がしてならない。シーンプレイヤーが≪深淵≫の判定に成功すると、ランダムに選んだアンカーとの運命が1点上昇する。`,`銀河の水辺にぽつりと浮かぶ島に、目の覚めるような白い立派な十字架がそびえたっている。このシーンに登場しているPCのうち一人は、≪祈り≫で判定を行うことができる。成功すると、以降このゲーム中に発生する魔法災厄が一回だけ無効化される。誰かが判定すると、成否にかかわらず、この効果はなくなる。`,`窓から銀河を見つめる、黒い外套を着た少女がいる。あなたに気づくとお菓子を差し出し、にこりと笑って去っていく。シーンプレイヤーはランダムに選んだ魔素を1点獲得する。`,`ノイズ混じりの車内放送が「停車駅」への到着を告げる。しばらくすると「汽車」が止まった。キャラクターは「停車駅」で降りることができる。降りる場合、「停車駅」の世界法則を決定し、その法則に従ってシーンを進めること。`,`車窓の向こうに、星明りに照らされたススキ野原が青白く広がる。そんな中で、不思議な紋様の書かれた三角標が何本か、ぽつり、ぽつりと立ち尽くしているのが見えた。`,`気づくと誰もいない。青いビロウドを張った座席だけが、空間をむなしく彩っている。シーンプレイヤー以外のPCが、このシーンに登場しようとする場合、≪静寂≫で判定を行う。失敗したPCは、このシーンに登場できない。`,`「この席、よろしいかな？」あなたの隣に〈書籍卿〉が座る。%{skill}の判定に成功すると公開されているハンドアウトの中から、好きなものを選び、その【秘密】を公開することができる。誰かが判定すると、成否にかかわらず、この効果はなくなる。`,`銀河を超える渡り鳥の群れ。しばし「汽車」と並走し、やがて離れ、天の川のようにきらきらした光の帯になっていく。このシーンに登場しているPCのうち一人は、≪翼≫で判定を行うことができる。成功すると魔力をリセットできる。誰かが判定すると、成否にかかわらず、この効果はなくなる。`,`隣の車輛から誰かが移ってきた。なんと、あなたのアンカーである。このシーンに登場しているPCをランダムに一人選び、そのPCのアンカーの中から、この異境に存在しない〈愚者〉のアンカーをランダムで一人選ぶこと。そのアンカーが、元の世界へ無事戻ることができたら、ゲーム終了時に功績点を1点獲得する。`]},WLAT:{name:`世界法則追加表`,type:`1D6`,items:[`世界法則「楽園」。この「停車駅」は美しく、慰めに満ちている。この「停車駅」で降りた〈愚者〉は魅了され、ここで一生を過ごすことになる。「刻印百景」の特技で判定に成功すると、これを押しとどめることができる。この判定は、対象の〈愚者〉一人につき一回しかできない。`,`世界法則「夜祭」。星の明かりや提灯を頼りに、終わらないお祭りが続いている。このシーンに登場しているキャラクターは、「刻印百景」の特技で判定に成功すると、【手当】の俗呪を使用したとき、消費した魔素1点につき、【魔力】を2点回復できるようになる。`,`世界法則「遺棄」。この「停車駅」の周辺は、様々なモノが捨てられている。シーンプレイヤーが「刻印百景」の特技で判定に成功すると、魔法【回想】と同じ効果が一回だけ発生する。誰を対象とするかは、シーンに登場しているキャラクターの中から、ランダムに選ばれる。`,`世界法則「妖蝶」。この「停車駅」の周辺は、魔素を帯びた不思議な色合いの羽をもつ蝶が生息している。このシーンに登場しているキャラクターは、「刻印百景」の特技で判定に成功すると、任意の魔素を2点獲得できる。失敗すると、ランダムに選んだ変調1つを受ける。`,`この「停車駅」の周辺は死んだ〈愚者〉たちの終着点でもある。もしここで降りる〈愚者〉がいれば、その人物は死んでいたことになる。このシーンに登場しているキャラクターがその〈愚者〉をアンカーとしている場合、「刻印百景」の特技で判定に成功すると、「疵」になることなく運命欄から消去できる。`,`世界法則「魔法門」。他の異境への入り口が存在する。「刻印百景」の特技で判定に成功すると、その魔法門を発見できる。`]},WMT:{name:`さまよう怪物表`,type:`1D6`,items:[`トロールに率いられたオークとゴブリンの大軍団に遭遇する。数百という怪物たちが野蛮な叫び声をあげながら、魔法使いたちに襲い掛かってくる。≪%{star}≫の判定を行う。全員の判定が終わったら、失敗したPCは1d6点のダメージを受ける。このとき、判定に成功したPCの数だけそのダメージの値を軽減できる。`,`大きな猛牛の頭をした巨漢…ミノタウロスが立ち塞がる。手に持った青銅の斧を振りかぶる。シーンに登場しているPCの中からランダムに代表を1人選ぶ。代表は≪%{beast}≫の判定を行う。失敗すると、PC全員は2点のダメージと「綻び」の変調を受ける。`,`突如、ドラゴンが現れる。深紅の鱗に覆われた巨影は、鎌首をもたげると、数瞬後、強烈な炎を吐いた。シーンに登場しているPC全員は≪%{force}≫の判定を行う。全員の判定が終わったら、PC全員は、1+判定に失敗した人数点のダメージを受ける。`,`白銀の鎧に身を包んだ騎士が現れる。騎士は一対一の勝負を挑んできた。シーンに登場しているPCの中から代表を1人選ぶ。代表は≪%{poem}≫の判定を行う。失敗すると代表は5点のダメージを受ける。`,`美しい上半身と獣の下半身を持つ女怪が現れる。艶めかしくその体をくゆらせながら、手を差し出してくる。シーンに登場しているPC全員は≪%{dream}≫の判定を行う。失敗したPCは、3点のダメージを受け、好きな魔素を3点失う。`,`黒いローブをまとった幽鬼が現れる。枯れ木のような細い腕を振り上げて、勇気は呪いの言葉を叫ぶ。幽鬼の【魔力】は4点。シーンに登場しているPC全員は≪%{night}≫の判定を行う。失敗したPCは、「不幸」の変調を受け、運命変転が発生する。`]},FFT:{name:`落花表`,type:`1D6`,items:[`肉体が枯れるように崩壊する。その苦痛は耐え難いもののようだ。人の言葉にならない断末魔が聞く者を苛み、死ぬ。〈永遠〉をアンカーにしているものは、それが疵になる。`,`精神が壊れる。その唇から、〈永遠〉が抱く夢や願望だけが小さく小さく、壊れた楽器のように吐き出され、季節が変わる頃に、死ぬ。〈永遠〉をアンカーにしているものは、それが疵になる。`,`その生命力が暴走し、死と再生が繰り返される。助けてくれと懇願する声すら出せない。1d6ヶ月後、死ぬ。〈永遠〉をアンカーにしているものは、それが疵になる。`,`〈禁書〉とともに封印に飲み込まれる。運命を結んでいるPCの夢に、暗い、怖い、助けてくれと繰り返し現れるが、次の新月の夜にふつりと途切れる。〈永遠〉をアンカーにしているものは、それが疵になる。`,`その時は何も起きない。運良く助かったか、〈愚者〉に戻れたようにも見える。だが一度でも眠りにつけば、目を覚ますことなく死ぬ。〈永遠〉をアンカーにしているものは、それが疵になる。`,`身体がしおれ、「種」が落ちる。しかし、再生することはない。もし大地に埋めてやれば、何かの植物として芽吹くだろう。（〈永遠〉をアンカーにしているものは、そのアンカーを失う。疵にはならない）`]},OLST:{name:`旧図書館シーン表`,type:`2D6`,items:[`曲がり角。唐突に〈禁書〉が現れ、襲いかかってきた！このシーンに登場するPCは、%{skill}で判定を行う。失敗すると、【魔力】を3点失う。`,`通路の真ん中。扉を開けて〈旧世界秩序〉の〈書籍卿〉「古き書物の化身」が現れた。彼はこのシーンに登場しているPCに協力を申し出る。このシーンに登場しているPCの一人は、《嘘》で判定を行う。成功すると〈書籍卿〉はこのシナリオの間、そのPCが行う魔法戦で、一度だけ立会人になる。失敗すると〈書籍卿〉は怒り出し、次のシーンでそのPCに対して、魔法戦をしかけてくる。誰かが判定すると、成否にかかわらず、この効果はなくなる。`,`元・研究室。壊れた実験道具が床に散らばっている。`,`元・閲覧室。数人の魔法使いたちが休んでいる。ここならば、色々な話が聞けそうだ。`,`空の書架が並ぶ、開けた空間。ここならば、一息つけるだろう。`,`破壊された魔導書が、山のように積み重なる場所。本の山に隠れていた〈断章〉が襲い掛かってくる。このシーンに登場するPCは、%{skill}で判定を行う。成功すると、〈断章〉を倒し、好きな魔素を一個手に入れる。失敗すると、時空を超えてアンカーに影響が現れる。「運命変転」が発生する。`,`破壊された書架が重なり合って作り上げた、迷路のような通路が続く。この先には、何があるのだろうか`,`元・宿舎。簡素な寝台が、いくつか残っている。`,`通路の行き止まり。目の前になぜか大きな箱がある。このシーンに登場しているPCの一人は、《謎》で判定を行うことができる。成功すると、箱の中にプライズを発見する。「プライズ表」を1回使用することができる。失敗すると、トラップが発動する。箱は爆発し、このシーンに登場しているPC全員の【魔力】が1点減少する。誰かが判定すると、成否にかかわらず、この効果はなくなる。`,`どこからか湧き出した水が、床の上に泉を作っている場所。泉の上に何者かの呼び出した元型が浮かんでいる。%{skill}で判定を行う。成功すると、【一時的魔力】を1点手に入れる。失敗すると、攻撃され、【魔力】が1点減少する。誰かが判定すると、成否にかかわらず、この効果はなくなる。`,`なぜ、君がここに？扉を開けると、そこにはPCのアンカーがいた。シーンプレイヤーのアンカーの中から、ランダムに一人を選ぶ。そのアンカーが登場する。シーンプレイヤーは、そのアンカーに「事件」を行っても、行動済みにならない。`]},TPTB:{name:`大判時の流れ表`,type:`1D6`,items:[`波乱万丈の人生を送る。この時代に起きた有名な事件の背後では、多くの魔法的存在が暗躍していた。あなたも、その事件に関わり、〈禁書〉や〈書籍卿〉たちと戦いを繰り広げる。%{skill}の判定を行う。成功するとセッション終了時に追加で功績点を1点獲得する。失敗すると、自分に「運命変転」が発生する。`,`冒険の日々の途中、大きな幸せがおとずれる。%{skill}の判定を行う。成功すると、自分のアンカーが負っている不幸か、自分が負っている疵一つを無効化する。`,`瞑想していたのか。それとも何か封印されていたのか。長い眠りから目を覚ます。もうそんな時間か。おかげで十分に休息できた。ランダムに魔素を三個獲得するか、自分が「魔力のリセット」を行うか、自分の受けている変調をすべて回復する。`,`特殊な異境に旅をしていた。そのせいか、人界で何が起きていたのかまったく分からない。浦島太郎になった気分だ。異境の土産として、魔貨を1d6点獲得する。`,`市井の人々に交じって平穏な日々をおくる。そんな日々の中にも、ちょっとした事件が起きた。自分のアンカーを一人目標に選んで「事件表」を振ることができる。`,`日々研鑚を重ね、魔法の修行に精進した。もしも望むなら、蔵書欄にある魔法を、自分の修得可能な別の魔法に変更して構わない。もしも、魔素がチャージされていた魔法を未習得にした場合、その魔素は失われる。`]},FLT:{name:`その後表`,items_lower:[`成就者は、邪悪な魔法の力にひかれるようになる。成就者が、そのセッションで〈断章〉に憑依されていたり、魔法災厄の犠牲になったりしていた場合、【堕落値】が1点上昇し、堕落チェックを行う。堕落チェックに失敗した場合、成就者は命を落とし、そのPCの疵となる。`,`成就者は、自分の不幸が魔法使いによるものだと信じるようになる。成就者が何らかの不幸に見舞われていた場合、【堕落値】が1点上昇し、堕落チェックを行う。堕落チェックに失敗した場合、願いを叶えたPCの成就者との【運命】の値が2点減少する。`,`成就者は、自分が特別な人間だと信じるようになる。願いを叶える努力を放棄するようになり、自堕落になる。成就者の【堕落値】が2点上昇する。堕落チェックを行う。堕落チェックに失敗した場合、「運命変転表『狂気的災厄』」を使用し、その不幸を受ける。`,`成就者は、願いが叶い、欲望が増大する。次はより大きな願いを求めるようになるだろう。成就者の【堕落値】が1点上昇する。堕落チェックを行う。堕落チェックに失敗した場合、「運命変転表『社会的災厄』」を使用し、その不幸を受ける。`,`成就者は、自分の願いを叶えたのが魔法によるものだと気付く。成就者の【堕落値】が1点上昇する。堕落チェックを行う。堕落チェックに失敗した場合、「運命変転表『超常的災厄』」を使用し、その不幸を受ける。`,`成就者は、自分の願いを叶えたのがPCだと気付く。成就者の【堕落値】が、そのPCの成就者との【運命】の値と同じ値になる。もし、この効果によって【堕落値】が以前より増えていた場合、堕落チェックを行う。堕落チェックに失敗した場合、成就者は〈愚者〉ではなくなり、魔法使いとなる。`],items_higher:[`成就者は、突如自分に訪れた幸運に罪悪感を覚えるようになる。もし成就者の【堕落値】が1点以上だった場合、堕落チェックを行う。堕落チェックに失敗した場合、「運命変転表『精神的災厄』」を使用し、その不幸を受ける。`,`成就者は、願いを叶えたPCに対して不信感を感じるようになる。自分は利用されているのでは無いかと疑い始め、願いを叶えたPCと距離を取る。成就者との【運命】の値が1点減少する。`,`成就者は、叶えて貰った願いを失うことになる。堕落チェックを行う。堕落チェックに成功すると、【堕落値】が1点減少する。`,`成就者は、願いを叶えたPCが魔法使いだと気付く。以降、その成就者の【堕落値】が上昇することがあった場合、その上昇値が1点増える（この効果は累積しない）。この効果が気に入らない場合、PCはその成就者の自分に関する記憶を消すことで、この効果を無効化することもできる。その場合、PCの成就者との【運命】の値は1になる。`,`成就者は、突然の幸運に感謝しつつも、自分の日常と戦っていく。もし、成就者に【堕落値】が1点以上ある場合、その値が1点減少する。`,`成就者は、信じれば夢が叶うと思うようになり、少しだけ前向きになる。PCは功績点を1点獲得する。`]}}}}},"MagicaLogia.ko_kr":{ko_kr:{MagicaLogia:{special:`스페셜(마력 1D6점 또는 상태이상 하나 회복)`,elements:{items:[`별`,`짐승`,`힘`,`노래`,`꿈`,`어둠`],format:`%{text} 마소 2점 발생`},skill_table:{items:[[`별`,[`황금`,`대지`,`숲`,`길`,`바다`,`정적`,`비`,`폭풍`,`태양`,`천공`,`이계`]],[`짐승`,[`살`,`벌레`,`꽃`,`피`,`비늘`,`혼돈`,`이빨`,`외침`,`분노`,`날개`,`에로스`]],[`힘`,[`중력`,`바람`,`흐름`,`물`,`파문`,`자유`,`충격`,`우레`,`불`,`빛`,`원환`]],[`노래`,[`이야기`,`선율`,`눈물`,`이별`,`미소`,`마음`,`승리`,`사랑`,`정열`,`치유`,`시간`]],[`꿈`,[`추억`,`수수께끼`,`거짓`,`불안`,`잠`,`우연`,`환각`,`광기`,`기도`,`희망`,`미래`]],[`어둠`,[`심연`,`부패`,`배신`,`방황`,`나태`,`왜곡`,`불행`,`바보`,`악의`,`절망`,`죽음`]]],s_format:`「%{category_name}」≪%{skill_name}≫`},inveterate_enemy_table:{name:`숙적 표`,type:`1D6`,items:[`질투. 그 인물은 사실 조사자의 실력을 시샘하는 <대법전>의 마법사였다. 데이터는 <화형 집행인>을 사용한다. 단, 마법을 사용하려면 마소가 필요하며, 마법사를 콜렉션으로 삼지는 못한다. GM은 조사자의 앵커나 조사자에게 마법전을 신청하는 등 조사자를 방해하는 방침으로 이 NPC를 조작해야 한다.`,`수집. 그 인물은 사실 조사자를 콜렉션으로 삼으려는 <서적경>이었다. 데이터는 <혼혈주의자>를 사용한다. GM은 조사자와 적대하는 <단장> 쪽에 입회하거나, 마법전을 신청하는 등 조사자를 방해하는 방침으로 이 NPC를 조작해야 한다.`,`방해. 그 인물은 사실 현재 조사자가 쫓는 <단장>을 빼앗으려는 <서적경>이었다. 데이터는 <유혹을 속삭이는 자>를 사용한다. GM은 조사자와 적대하는 <단장> 쪽에 입회하거나, 마법전을 신청하는 등 조사자를 방해하는 방침으로 이 NPC를 조작해야 한다.`,`단장. 그 인물에게는 이번 사건과 관계 없는 <단장>이 빙의되어 있었다. 데이터는 <열락>을 사용한다. GM은 조사자와 적대하는 <단장> 쪽에 입회하거나, 마법전을 신청하는 등 조사자를 방해하는 방침으로 이 NPC를 조작해야 한다.`,`검은 옷. 그 인물은 사실 마법이나 요괴 같은 온갖 초자연적 현상을 부정하는 비밀 결사, 「서클 엔드」의 공작원 이었다. 데이터는 <서클 엔드>를 사용한다. GM은 【은폐 공작】을 사용하거나 마법전을 신청하는 등 조사자를 방해하는 방침으로 이 NPC를 조작해야 한다.`,`닌자. 그 인물은 사실 당신을 죽이라는 사명을 띤 닌자다. 데이터는 <닌자>를 사용한다. GM은 <단장> 쪽에 입회하거나 마법전을 신청하는 등 조사자를 방해하는 방침으로 이 NPC를 조작해야 한다.`]},conspiracy_table:{name:`모략 표`,type:`1D6`,items:[`폭탄. 그 인물에게는 조사자의 육체를 폭발시키는 마법 폭탄이 설치되어 있다. 이 【비밀】이 공개되면 조사자는 1D6의 대미지를 입는다.`,`저주. 그 인물에게는 조사자에게 감염되는 저주의 마법이 걸여 있었다. 이 【비밀】이 공개되면 조사자는 무작위로 선택한 상태이상 한 종류에 걸린다.`,`유폐. 그 인물에게는 조사자를 다른 차원의 감옥에 가두는 마법이 걸려 있었다. 이 【비밀】이 공개되면, 조사자는 담당 플레이어가 장면 플레이어일 때를 제외하면 클라이맥스 페이즈가 될 때까지 장면에 등장할 수 없다(메인 페이즈의 마스터 장면에서는 GM이 등장 여부를 마음대로 결정할 수 있다).`,`강화. 그 인물에게는 조사자가 맺은 운명의 힘을 흡수하는 마법이 걸려 있었다. 이 【비밀】이 공개되면 세션에 등장한 <단장>을 조사자의 앵커 수와 같은 수까지 선택한다. 선택한 <단장>의 빙의 심도가 1 상승한다.`,`불행. 그 인물에게는 조사자의 앵커에게 불행한 사건을 일으키는 마법이 걸려 있었다. 이 【비밀】이 공개되면 조사자의 앵커 중에서 <우자>를 한 명 선택한다. 그 NPC에게 운명 변전 표를 사용한다.`,`탈주. 그 인물에게는 <단장>의 도주를 돕는 마법이 걸려 있었다. 이 【비밀】이 공개되면, GM은 <단장> 하나와 NPC 한 명을 선택한다. 그 <단장>은 해당 NPC에게 빙의할 수 있다. 이때, GM은 이미 마법사가 회수한 <단장>을 선택할 수도 있으며, 이때는 【마력】을 1D6점 회복한다.`]},fate_table:{name:`인연 표`,type:`1D6`,items:[`사모. 그 인물은 사실 조사자에 대해 알고 있으며, 깊이 사랑하고 있다. 조사자는 그 인물에 대한 【운명】을 2점 상승시키고, 속성을 「연애」로 정한다. 그 인물의 【운명】 속성이 「연애」인 동안, 조사자는 그 인물에 대한 【운명】이 1점 상승할 때마다 【마력】을 해당하는 【운명】 수치만큼 회복한다.`,`친인척. 그 인물은 사실 조사자와 혈연 관계였다. 조사자는 그 인물에 대한 【운명】을 2점 상승시키고, 속성을 「혈연」으로 정한다. 그 인물의 【운명】 속성이 「혈연」인 동안, 조사자의 부활 판정에 해당하는 【운명】 수치만큼 플러스 수정을 적용한다.`,`원한. 그 인물은 사실 조사자에게 깊은 원한이 있는 인물이었다. 조사자는 그 인물에 대한 【운명】을 2점 상승시키고, 속성을 「숙적」으로 정한다. 그 인물의 【운명】 속성이 「숙적」인 동안, 조사자는 펌블을 일으켰을 때 해당하는 【운명】 수치만큼 【마력】이 감소한다.`,`광신. 그 인물은 사실 조사자를 숭배하고 있었다. 조사자는 그 인물에 대한 【운명】을 2점 상승시키고, 속성을 「지배」로 정한다. 그 인물의 【운명】 속성이 「지배」인 동안, 조사자는 그 인물에게 빙의한 <단장>에게 마법전을 신청했을 때 자동으로 승리할 수 있다. 단, 조사자가 행동 판정에서 해당하는 【운명】 수치 이하의 눈을 내면 그 판정은 펌블이 된다.`,`분신. 그 인물은 사실 조사자의 마법으로 분할된 혼의 일부였다. 그 NPC는 조사자와 융합하며, 조사자는 공적점을 1점 획득한다.`,`무괸계. 그 인물은 이번 사건과 딱히 관계가 없었디. 하지만 이 만남이 정말로 무의미했을까? 조사자는 그 인물을 대상으로 사건표를 사용한다.`]},cueball_table:{name:`기인 표`,type:`1D6`,items:[`수명. 그 인물의 명백은 한계에 도달했다. 이 【비밀】이 공개되면 그 인물은 사망한다.`,`살의. 그 인물은 세상에 대한 넘쳐나는 증오에 사로잡혀 닥치는 대로 남을 해치려 하고 있었다. GM은 사이클을 끝낼 때 무작위로 이 【비밀】의 소유자 이외의 NPC를 1명 선택한다. 그 NPC가 <단장>에 빙의되지 않은 <우자>라면 사망하며, 그렇지 않다면 이 【비밀】의 소유자 본인이 사망한다. 이때, 어느 쪽이 죽든 간에 이런 사망을 바라지 않는 캐릭터는 「어둠」 분야에서 무작위로 특기를 하나 선택해서 판정할 수 있다. 판정에 성공하면 그 사망을 무효로 할 수 있다.`,`행운. 그 인물은 일종의 특이점으로, 매우 운이 좋다. 이 NPC는 프라이즈로 간주한다. 이 프라이즈의 소유자는 모든 행동판정에 +1의 수정을 적용한다. 조사자는 이 프라이즈를 획득한다.`,`흉터. 그 인물은 과거에 마법 때문에 소중한 이를 빼앗겼으며, 마법과 거기에 관계된 자를 증오하고 있다. 그 인물이 있는 장면에서는 소환과 주문 판정에 -2의 수정을 적용한다.`,`선량한 인물. 그 인물은 마음이 매우 상냥했다. 그 인물에 대한 【운명】을 3점 상승시킨다.`,`그릇. 그 인물은 영매 체질이라 무언가에 빙의당하기 쉽다. 이 인물에게 <단장>이 빙의하면 【공격력】과 【방어력】이 2점씩 상승한다. 이 【비밀】이 공개되면 GM은 이 사이클을 끝낼 때 <단장>을 하나 선택해서, 그 <단장>의 빙의 대상을 이 NPC로 변경할 수 있다. 단, 이미 마법사에게 회수당한 <단장>은 선택할 수 없다.`]},force_field_table:{name:`역장 표`,type:`1D6`,items:[`가호. 그 인물의 머리 위에는 항상 별의 은총이 내리고 있다. 이 【비밀】이 공개되면, 그 장면에 「별」 마소가 2점 발생한다. 또, 이번 세션동안 이 인물에 대한 【운명】이 1점 상승한 캐릭터는 「별」 마소를 2점 획득한다.`,`둔갑 동물. 그 인물은 사실 나이를 먹은 여우나 너구리 같은 동물이 둔갑한 존재다. 이 【비밀】이 공개되면, 그 장면에 「짐승」 마소가 2점 발생한다. 또, 이번 세션 동안 이 인물에 대한 【운명】이 1점 상승한 캐릭터는 「짐승」 마소를 2점 획득한다.`,`초능력. 그 인물에게는 ESP나 PK 같은 초능력이 잠재되어 있었다. 이 【비밀】이 공개되면, 그 장면에 「힘」 마소가 2점 발생한다. 또, 이번 세션 동안 이 인물에 대한 【운명】이 1점 상승한 캐릭터는 「힘」 마소가 2점 발생한다. 또, 이번 세션 동안 이 인물에 대한 【운명】이 1점 상승한 캐릭터는 「힘」 마소가 2를 획득한다.`,`시인. 그 인물은 시의 신에게 축복받은 존재다. 이 【비밀】이 공개되면, 그 장면에 「노래」 마소가 2점 발생한다. 또, 이번 세션 동안 이 인물에 대한 【운명】이 1점 상승한 캐릭터는 「노래」 마소를 2점 획득한다.`,`몽상가. 그 인물에게는 장대한 이상이나 실현하고 싶은 꿈이 있다. 뭔가 큰 일을 이루려고 한다. 이 【비밀】이 공개되면, 그 장면에 「꿈」 마소가 2점 발생한다. 또, 이번 세션 동안 이 인물에 대한 【운명】이 1점 상승한 캐릭터는 「꿈」 마소를 2점 획득한다.`,`암흑. 그 인물은 저주받은 운명을 짊어지고 있으며, 세계의 파멸을 초래할 가능성을 품고 있다. 이 【비밀】이 공개되면, 그 장면에 「어둠」 마소가 2점 발생한다. 또, 이번 세션 동안 이 인물에 대한 【운명】이 1점 상승한 캐릭터는 「어둠」 마소를 2점 획득할 수 있다.`]},alliance_table:{name:`동맹 표`,type:`1D6`,items:[`정령. 그 인물은 사실 변신한 모습으로 인간계에 나타난 정령이었다. %{skill}(이)가 그 원형이 상징하는 특기다. 조사자는 그 세션 동안에만 그 특기에 해당하는 【정령 소환】을 습득한다. 또, 세션마다 한 번씩 그 【정령 소환】의 판정에 자동으로 성공할 수 있다.`,`기사. 그 인물은 사실 변신한 모습으로 인간계에 나타난 기사였다. %{skill}(이)가 그 원형이 상징하는 특기다. 조사자는 그 세션 동안에만 그 특기에 해당하는 【기사 소환】을 습득한다. 또, 세션마다 한 번씩 그 【기사 소환】의 판정에 자동으로 성공할 수 있다.`,`마왕. 그 인물은 사실 변신한 모습으로 인간계에 나타난 마왕이었다. %{skill}(이)가 그 원형이 상징하는 특기다. 조사자는 그 세션 동안에만 그 특기에 해당하는 【마왕 소환】을 습득한다. 또, 세션마다 한 번씩 그 【마왕 소환】의 판정에 자동으로 성공할 수 있다.`,`마법 상인. 그 인물은 마법 도구를 거래하는 탈리스몽거였다. 이후, 이 인물이 있는 장면에서는 자신이 충전한 마소 하나를 다른 마소 하나와 교환할 수 있다. 또, 이 인물이 있는 장면에서는 자신의 장비 마법 하나를 습득 가능한 다른 장비 마법 하나와 교환할 수 있다.`,`스승. 그 인물은 일찍이 조사자에게 마법을 가르친 스승이었다. 이후, 이 인물이 있는 장면에서는 자신이 습득한 특기 하나를 습득 가능한 다른 특기 하나로 교환할 수 있다. 또, 이 인물이 있는 장면에서는 자신의 주문 바법 하나를 습득 가능한 다른 주문 마법 하나와 교환할 수 있다.`,`무구. 그 인물은 티 없는 마음의 소유자였다. 이 NPC는 프라이즈로 간주한다. 이 프라이즈의 소유자는 세션 동안 한번만 【정화】 주문을 코스트 없이 사용할 수 있다. 이때, 판정은 자동으로 성공한다.`]},tables:{TPT:{name:`시간의 흐름 표(구판)`,type:`1D6`,items:[`標的となり追われる生活が続いた。ここ数年は苦しい戦いの日々だった。%{skill}の判定を行う。成功するとセッション終了時に追加の功績点1点。失敗すると「運命変転」発生。`,`冒険の日々の途中、大きな幸せが訪れる。%{skill}の判定を行う。成功すると、自分のアンカーの災厄か、自分の疵一つを無効化する。`,`瞑想から目を覚ます。もうそんな時間か。おかげで十分な魔素を得ることができた。「%{element}」「%{element}」「%{element}」の魔素を獲得する。`,`傷を癒すには十分な時間だ。自分の【魔力】を最大値まで回復する。もしくは「魔力のリセット」を行うことができる。好きな方を選ぶこと。`,`平穏な日々の中にも、ちょっとした事件が起きる。自分のアンカーを一人選んで「事件表」を振ることができる。`,`日々研鑚を重ね、魔法の修行に精進した。もしも望むなら、蔵書欄にある魔法を、自分の修得できる範囲の中で、現在とは別の魔法に変更して構わない。もしも、魔素がチャージされていた魔法を見習得にした場合、その魔素は失われる。`]},ST:{name:`장면 표(구판)`,type:`2D6`,items:[`魔法で作り出した次元の狭間。ここは時間や空間から切り離された、どこでもあり、どこでもない場所だ。`,`夢の中。遠く過ぎ去った日々が、あなたの前に現れる。`,`静かなカフェの店内。珈琲の香りと共に、優しく穏やかな雰囲気が満ちている。`,`強く風が吹き、雲が流されていく。遠く、雷鳴が聞こえた。どうやら、一雨きそうだ。`,`無人の路地裏。ここならば、邪魔が入ることもないだろう。`,`周囲で〈断章〉が引き起こした魔法災厄が発生する。%{skill}の判定を行うこと。成功すると、好きな魔素が一個発生する。失敗すると「運命変転表」を使用する。`,`夜の街を歩く。暖かな家々の明かりが、遠く見える。`,`読んでいた本を閉じる。そこには、あなたが知りたがっていたことが書かれていた。なるほど、そういうことか。`,`大勢の人々が行き過ぎる雑踏の中。あなたを気に掛ける者は誰もいない。`,`街のはるか上空。あなたは重力から解き放たれ、自由に空を飛ぶ。`,`未来の予感。このままだと起きるかもしれない出来事の幻が現れる。`]},FT:{name:`펌블 표`,type:`1D6`,items:[`마법재액이 당신의 앵커를 덮친다. 자신에게 「운명 변전」이 발생한다.`,`마법재액이 당신의 마소를 빼앗는다. 충전한 마소를 임의의 조합으로 2점 감소한다.`,`마법의 제어에 실패한다. 【마력】이 1점 감소한다.`,`마법재액이 일어나는 바람에, 그 사이클이 끝날 때까지 자신의 행동판정에 -1의 수정이 붙는다.`,`마법재액이 직접 당신을 덮친다. 상태이상 표를 사용하여 정해진 상태이상을 받는다.`,`휴우, 큰일날 뻔했다. 아무 일도 일어나지 않는다.`]},WT:{name:`상태이상 표`,type:`1D6`,items:[`봉인. 자신이 습득한 장비 타입 이외의 마법 중에서 무작위로 하나를 선택한다. 선택한 마법의 체크칸에 체크한다. 그 마법을 사용하려면 【마력】을 2점 소비해야 한다.`,`타짐. 마법전 동안 각 라운드가 종료할 때 자신의 【마력】이 1점 감소한다.`,`허약. 【공격력】이 1점 감소한다.`,`병마. 【방어력】이 1점 감소한다.`,`차단. 【근원력】이 1점 감소한다.`,`불운. %{skill}의 체크칸에 체크한다. 이 특기를 사용할 수 없게 되며, 그 분야의 특기가 지정특기인 판정을 할 때는 -1의 수정이 붙는다.`]},FCT:{name:`운명 변전 표`,type:`1D6`,items:[`좌절. 그 캐릭터는 자신의 소중한 꿈을 포기한다.`,`이별. 그 캐릭터는 가장 소중한 사람(절친한 친구, 연인, 부모나 형제 등)을 잃는다.`,`중병. 그 캐릭터는 불치병에 걸린다.`,`빚. 그 캐릭터는 악인에게 이용당해 거액의 빚을 진다.`,`불화. 그 캐릭터는 인간 관계를 망쳐서 깊은 마음의 상처를 입는다.`,`사고. 그 캐릭터는 교통사고를 당해 돌이킬 수 없는 상처를 입는다.`]},AT:{name:`사건 표`,type:`2D6`,items:[`예기치 못한 선물, 멋진 아이디어, 악마의 거래…… 목표가 당신이 바라는 것을 주려고 한다. 당신은 아무거나 마소를 1점 획득하거나, 【마력】을 1D6점 회복할 수 있다. 어느 한쪽을 선택했다면 목표에 대한 당신의 【운명】이 1점 상승한다. 【운명】의 속성은 GM이 마음대로 결정할 수 있다.`,`고귀한 희생, 진지한 마음, 압도적인 힘…… 목표가 영웅적인 행위를 한다. 목표에 대한 당신의 【운명】이 1점 상승한다. 【운명】의 속성은 「존경」이 된다.`,`가벼운 말다툼, 치고받는 싸움, 마법전…… 그 인물과 충돌했다. 당신과 목표는 서로 1D6을 굴린다. 더 높은 눈이 나온 쪽에 대한, 더 낮은 눈이 나온 쪽의 【운명】이 1점 상승한다(결과가 같다면 둘 중 하나가 더 높은 눈을 낼 때까지 주사위를 다시 굴린다.). 【운명】의 속성은 더 높은 눈을 굴린 쪽이 마음대로 결정할 수 있다.`,`배신, 책모, 불행한 오해…… 목표는 갑자기 당신의 소중한 것을 파괴한다. 목표에 대한 당신의 【운명】이 1점 상승한다. 【운명】의 속성은 「숙적」이 된다.`,`의도치 않은 감사, 위기 상황에서 찾아온 구제, 평생에 걸친 소원의 달성…… 목표가 당신에게 큰 빚을 진다. 목표에 대한 당신의 【운명】이 1점 상승한다. 【운명】의 속성은 지배가 된다.`,`살아있는 시체의 무리, 지옥의 업화, 미궁화…… 목표와 함께 있을 때 마법 재액에 휘말린다. %{skill}(으)로 판정한다. 성공하면 아무거나 마소가 1점 발생한다. 실패하면 「운명 변전 표」를 사용해서 정한 불행이 목표에게 닥친다.`,`길 모퉁이, 편의점, 하늘에서 추락…… 우연히 목표와 만난다. 목표에 대한 당신의 【운명】이 1점 상승한다. 【운명】의 속성은 「흥미」가 된다.`,`영혼의 번뜩임, 사랑의 고백, 요염한 포옹…… 목표를 사랑하게 된다. 목표에 대한 당신의 【운명】이 1잠 상승한다. 【운명】의 속성은 「연애」가 된다.`,`사제 관계, 연인 사이, 엇갈린 마음…… 목표와 당신이 얽힌 미래를 엿본다. 당신과 목표는 서로에 대한 【운명】이 1점 상승한다. 【운명】의 속성은 각자 마음대로 결정할 수 있다.`,`반가운 표정, 소중한 추억, 반려가 될 예감…… 목표와 함께 행복한 시간을 보내면서 소중한 것을 떠올린다. 목표에 대한 【운명】이 1점 상승한다. 【운명】의 속성은 「혈연」이 된다.`,`헌신적인 간호, 마법의 축복, 기적…… 목표가 당신을 구했다. 목표에 대한 【운명】이 1점 상승한다. 【운명】의 속성은 마음대로 결정할 수 있다. 만약 관계칸에 상흔이 있다면, 상흔 하나를 관계칸에서 지울 수 있다.`]},BGT:{name:`경력 표`,type:`1D6`,items:[`서경 / 북 워치`,`사서 / 라이브러리언`,`서공 / 아티전`,`방문자 / 게스트`,`이단자 / 아웃사이더`,`외전 / 아포크리파`]},DAT:{name:`초기 앵커 표`,type:`2D6`,items:[`은인. 당신은 곤란한 상황에서 그 앵커의 도움을 받았다.`,`식객. 당신 또는 앵커는 상대방의 집, 또는 상대가 경영하는 연립주택에 산다.`,`술친구. 당신과 앵커는 술친구다.`,`단골. 당신 또는 앵커는 상대방의 직장에 자주 찾아온다.`,`동인. 당신은 그 앵커와 같은 취미를 애호하는 동호인이다.`,`이웃. 당신은 그 앵커의 이웃에 산다.`,`동기. 당신은 그 앵커와 직장 또는 학교가 같다.`,`펜팔. 당신은 편지나 메일을 통해 그 앵커와 의견을 교환한다.`,`옛 친구. 당신은 예전에 그 앵커와 친교가 있었다.`,`비호. 당신은 그 앵커를 남몰래 지켜본다.`,`애인. 당신은 그 앵커와 육체 관계를 맺고 있다.`]},FAT:{name:`운명 속성 표`,type:`1D6`,items:[`혈연. 자신이나 자신이 사랑한 이의 친척 또는 가족.`,`지배. 당신의 부하가 될 운명인 상대.`,`숙적. 어떤 방법으로 싸우고 경쟁하는 불구대천의 적.`,`연애. 마음을 빼앗겨, 상대에게 강한 애정을 품고 있는 존재.`,`흥미. 매우 희귀하거나 불가해하여, 연구나 관찰을 하고 싶어지는 대상.`,`존경. 그 재능과 사상, 자세에 대해 외경심이나 존경심을 품은 인물.`]},WIT:{name:`소원 표`,type:`1D6`,items:[`자신 이외의 특정한 누군가를 도와달라.`,`소중한 사람이나 동경하는 사람과 만나게 해달라.`,`자신을 둘러싼 불행을 없애달라.`,`자신이 잃어버린 무언가를 되찾아달라.`,`특정한 누군가를 벌해달라.`,`자신의 욕망(금전욕, 명예욕, 육욕, 지식욕 등)을 충족시켜달라.`]},TCT:{name:`운명 변전 표 「전형적 재액」`,type:`1D6`,items:[`좌절. 그 캐릭터는 자신의 소중한 꿈을 포기한다.`,`이별. 그 캐릭터는 가장 소중한 사람(절친한 친구, 연인, 부모나 형제 등)을 잃는다.`,`중병. 그 캐릭터는 불치병에 걸린다.`,`빚. 그 캐릭터는 악인에게 이용당해 거액의 빚을 진다.`,`불화. 그 캐릭터는 인간 관계를 망쳐서 깊은 마음의 상처를 입는다.`,`사고. 그 캐릭터는 교통사고를 당해 돌이킬 수 없는 상처를 입는다.`]},PCT:{name:`운명 변전 표 「물리계 재액」`,type:`1D6`,items:[`화재. 집이 불타서 돌아갈 곳이 없어진다.`,`도난. 소중한 것을 도둑맞이 잃는다.`,`재해. 자연 재해에 휘말려 생활 환경이 격변한다.`,`실명. 눈이 보이지 않게 된다.`,`유괴. 누군가에게 납치당해 감금된다.`,`상해. 무차별 폭행을 당하거나, 당신을 증오하는 이에게 상처를 입는다.`]},MCT:{name:`운명 변전 표 「정신계 재액」`,type:`1D6`,items:[`권태. 피로감에 사로잡혀 아무 일도 하기 싫어진다.`,`가출. 지금 자신이 있는 장소를 불편하게 여겨 실종된다.`,`증오. 주위의 누군가가 PC에 대해 격심한 증오를 품게 된다.`,`불면. 잠을 자지 못하게 되어 피폐해진다.`,`허언. 사실을 말하지 못하게 된다.`,`기억상실. 친구나 PC를 잊어버린다.`]},ICT:{name:`운명 변전 표 「광기계 재액」`,type:`1D6`,items:[`이중인격. 또 하나의 인격이 나타나 제멋대로 행동하기 시작한다.`,`공포. 높은 곳이나 이성, 거미 등 특정한 무언가에 대한 공포증에 걸린다.`,`망상. 당치도 않는 기묘한 망상이 머리에서 떠나지 않게 된다.`,`편애. 특정한 물건이나 상황 등에 열광적인 애정을 보이게 된다.`,`폭주. 종종 자신의 감정을 제어하지 못하고 흉포하게 군다.`,`발정. 체온이 상승하고 맥박이 빨라지며 성적인 흥분 상태가 된다.`]},SCT:{name:`운명 변전 표 「사회계 재액」`,type:`1D6`,items:[`체포. 저지르지도 않은 죄로 잡혀서 유치된다.`,`배신. 믿었던 인물에게 속거나, 연인이 바람을 피운다.`,`폭로. 숨기고 싶었던 비밀을 폭로당한다.`,`농락. 누가 봐도 건실하지 못한 상대에게 마음을 빼앗긴다.`,`가해. 남을 다치게 하거나 죽여버린다.`,`과로. 터무니 없는 양의 업무에 쫓겨 심신 모두 피로에 찌든다.`]},XCT:{name:`운명 변전 표 「초자연계 재액」`,type:`1D6`,items:[`영감. 보일 리가 없는 것이 보이게 된다.`,`불운. 주위에서 불행한 우연이 빈발하게 된다.`,`감염. 흡혈귀나 좀비 같은 괴물로 변하기 시작한다.`,`저해. 비마법적인 이들의 눈에 보이지 않게 된다.`,`변신. 모습이 동물이나 다른 인간으로 변해버린다.`,`표적. 살인마나 마법 재액 같은 악의적인 존재의 관심을 끌어들이고 만다.`]},WCT:{name:`운명 변전 표 「불가사의계 재액」`,type:`1D6`,items:[`중2병. 종종 안쓰러운 언동을 반복하게 된다.`,`덜렁이. 비정상적으로 자주 넘어지거나 물건을 망가뜨리닌 체질이 된다.`,`방향치. 믿기지 않을 정도로 길을 헤메게 된다.`,`이상한 어미. 왠지 자신이 말하는 말의 어미가 이상해진다.`,`어색한 발음. 외래어 발음이 모조리 어색해진다.`,`얀데레. PC를 병적으로 사랑하게 되며, 자기 이외의 누군가가 PC에게 호감을 품으면 공격적으로 대한다.`]},CCT:{name:`운명 변전 표 「코믹계 재액」`,type:`1D6`,items:[`성별 역전. 육체의 성별이 반전한다.`,`고양이 귀. 머리에 고양이 귀가 생긴다.`,`똥보. 깜짝 놀랄 정도로 살이 찐다.`,`발냄새. 서글플 정도로 발냄새가 심해진다.`,`굶주림. 식사를 한 번 할 때마다 밥을 스무 그릇 정도 먹지 않으면 배가 고파서 아무것도 못 한다.`,`탈의. 그 자리에서 모든 옷을 벗는다.`]},BST:{name:`백지 비밀 표`},PT:{name:`프라이즈 표`,type:`2D6`,items:[`패자는 안쪽부터 파열하여 산산이 흩어진다. 공적점을 1점 획득한다.`,`패자는 무수한 벌레나 작은 동물로 변하고, 승자가 그것을 사역마로 삼는다. 승자는 아무거나 특기(혼의 특기는 제외)를 하나 선택한다. 그 세션 동안 지정 특기가 해당 특기인 【정령 소환】, 【마검 소환】, 【악몽 소환】 중 하나를 습득한다.`,`패자는 폭발음과 함께 어딘가로 사라지고, 주위에는 유황 냄새 같은 냄새만이 남는다. 승자는 그 세션 중에 한 번만 원하는 타이밍에 「상태이상」 한 종류를 회복할 수 있다.`,`패자는 기묘한 형태의 금화 여러 닢으로 변한다. 승자는 쓰러트린 상대의 랭크만큼 마화를 획득한다.`,`패자는 지면에서 갑자기 나타난 무수한 팔에 끌려가면서, 승자를 향해 찬사의 말고 함께 중요한 정보를 이야기한다. 공개된 핸드아웃 하나를 선택하여 해당하는 【비밀】을 공개한다.`,`패자는 무수한 빛의 입자로 변해가고, 승자는 거기에서 마소를 얻는다. 승자는 아무거나 마소를 2점 획득한다.(자신의 입호인에게 넘겨줄 수도 있다).`,`패자는 무수한 페이지가 되어 지면에 흩어지고, 승자는 거기에서 미지의 힘을 읽어낸다. 승자는 【일시적 마력】을 2점 획득한다.`,`패자는 감미로운 음악으로 변하고, 그 곡은 승자의 마음에 스며든다. 승자는 쓰러트린 상대의 랭크와 같은 수치의 마화를 획득한다.`,`패자는 한 송이 꽃이 된다. 승자는 그 세션 동안 한 번만 자신이 굴린 행동판정의 주사위를 다시 굴릴 권리를 얻는다.`,`패자는 말의 파편으로 변해가고, 승자는 거기에서 미래의 운명을 읽어낸다. 승자는 「사건 표」를 사용한 후, 그 결과를 기록해둔다. 그 후, 그 세션 중에 연 드라마 장면에, 같은 장면에 등장한 캐릭터 한 명을 골라서 한 번만 해당 결과를 적용할 수 있다.`,`패자는 그림자가 되어 그 자리에 새겨져서 이경의 입구가 된다. 승자는 아무거나 이경을 하나 선택한다. 그 세션 동안 해당하는 이경으로 이동할 수 있다.`]},XEST:{name:`극한 환경 장면 표`,type:`2D6`,items:[`상하좌우조차 알 수 없는 완전한 어둠. 이 장면에 등장한 PC 중 한 명은 《빛》으로 판정한다. 판정에 성공하면 「어둠」 마소 2점을 획득하지만, 실패하면 「차단」 상태이상에 걸린다. 누군가가 판정을 했다면 성공 여부와 관계없이 이 효과는 없어진다.`,`눈앞에 펼쳐진 업화의 바다. 모든 것을 집어 삼킬 듯한 적의는 압도적이다. 《불》로 판정한다. 실패하면 【마력】이 2점 감소한다.`,`거친 날씨로 지형이 일변한다. 조금 전까지의 광경이 거짓말 같다. 《폭풍》으로 판정한다. 실패하면 【마력】이 1점 감소한다.`,`한없이 펼쳐진 사막. 날아오르는 모래먼지 때문에 눈을 뜰 수 없다. 《대지》로 판정한다. 실패하면 「봉인」 상태이상에 걸린다.`,`입에서 꺼낸 말조차 얼어버릴 것만 같은 지독한 추위. 생물의 기척은 느껴지지 않는다. 【마력】이 1점 감소한다.`,`가혹한 자연 환경 탓에 여러분은 궁지에 몰렸다. 이 장면에 등장한 PC는 %{skill}(으)로 판정한다. 성공하면 어떻게든 쓸 만한 것을 찾아서 임의로 선택한 마소가 1점 발생한다. 실패하면 자신이 입은 부상이 시간과 공간을 넘어 앵커에게 불행을 가져다준다. 「운명 변전」이 발생한다.`,`시야를 가득 채우는 눈 덮인 들판에 띄엄띄엄 발자국이 남아 있다. 아무래도 선객이 있는 모양이다.`,`깍아지른 절벽 위. 아래에는 넓은 바다가 펼쳐져 있다. 하늘에서는 바닷새의 울음소리가 들려온다.`,`고중력 지대. 몸 전체가 납으로 변한 것 같은 기분이다. 《중력》으로 판정한다. 실패하면 【마력】이 1점 감소한다.`,`깊은 물속의 밑바닥. 푸른색 공간에 무언가가 떠 다닌다. 이 장면에 등장한 PC 중 한 명은 《바다》로 판정할 수 있다. 판정에 성공하면 「별」 마소를 3점 획득하지만, 실패하면 【마력】이 2점 감소한다. 누군가가 판정을 했다면 성공 여부와 관계없이 이 효과는 없어진다.`,`고막을 때리는 굉음이 울려 퍼진다. 말을 통한 의사 소통은 포기하는게 나을 것 같다. 《선율》로 판정한다. 실패하면 충전한 마소 중에서 임의로 선택한 것을 2점 감소한다.`]},IWST:{name:`내면 세계 장면 표`,type:`2D6`,items:[`드러난 피부와 뜨거운 숨결이 가득한 장소. 무수한 남녀가 정신 없이 육욕을 탐하고 있다. 이 장면에 등장한 PC 중 한 명은 《에로스》로 판정할 수 있다. 판정에 성공하면 【일시적 마력】을 1점 획득하고, 실패하면 【마력】이 2점 감소한다. 누간가가 판정을 했다면 성공 여부와 관계없이 이 효과는 없어진다.`,`검은 광택이 나는 벌레가 벽 전체에 빈틈없이 달라붙어 날갯소리를 내고 있는 방. 이 정신의 주인은 벌레를 좋아하는 걸까, 아니면 싫어하는 걸까? 이 장면에 등장한 PC 중 한 명은 《벌레》로 판정할 수 있다. 판정에 성공하면 원형 「벌레의 기사」를 그 세션 동안 파트너로 삼을 수 있다. 자신이 어떤 장면에 등장할 때, 파트너는 파괴되거나 소멸하지 않았다면 장면의 종류를 불문하고 같은 타이밍에 소환된다. 판정에 실패했다면 벌레가 일제히 날아올라 이 장면에 등장한 PC 전원의 【마력】이 1점 감소한다. 누간가가 판정을 했다면 성공 여부와 관계없이 이 효과는 없어진다.`,`아무도 없는 방. 왠지 어딘가에서 속닥속닥 속삭이는 소리가 들려오고, 그 누군가가 자신을 지켜보는 기분이 든다. 이 장면에 등장한 PC 중 한 명은 《불안》으로 판정할 수 있다. 판정에 성공하면 공개된 핸드아웃 중 원하는 것의 【비밀】을 공개할 수 있다. 판정에 실패하면 「차단」 상태이상에 걸린다. 누간가가 판정을 했다면 성공 여부와 관계없이 이 효과는 없어진다.`,`좀 어둡긴 하지만 따뜻하고, 매우 안락한 공간. 마치 어머니의 뱃속 같다. 이 장면에 등장한 PC가 속주 【치료】를 사용하면 마소 1점당 2점의 【마력】을 회복할 수 있다.`,`유원지. 시끌벅적한 퍼레이드가 눈앞을 지나가고 있는데, 손님은 한 명도 없다.`,`밤길. 뒤에서 검은 무언가가 아른거리며 쫓아온다. 명확한 모습도 알아볼 수 없건만, 굉장히 무섭다. 이 장면에 등장한 PC는 %{skill}(으)로 판정한다. 판정에 성공하면 원하는 마소 2점을 획득할 수 있다. 판정에 실패하면 아른거리는 형체의 검은 무언가가 자신의 앵커 앞에 나타난다. 「운명 변전」이 발생한다.`,`해 질 녘의 거리. 왠지 쓸쓸한 기분이 든다.`,`바닥, 벽, 천장까지 검붉게 물든 방. 비린내가 진동한다. 이 장면에 등장한 PC 중 한 명은 《피》로 판정할 수 있다. 판정에 성공하면 【일시적 마력】을 2점 획득하고, 실패하면 【마력】이 1점 감소한다. 누군가가 판정을 했다면 성공 여부와 관계없이 이 효과는 없어진다.`,`어디로 가는지 알 수 없는 전철 안. 달리 승객은 없는 것 같은데...... 이 장면에 등장한 PC 중 한 명은 《이계》로 판정할 수 있다. 판정에 성공하면 임의의 이경 한 군데로 갈 수 있는 마법문을 발견할 수 있다. 판정에 실패하면 이 장면에 등장한 PC 전원의 【마력】이 2점 감소한다. 누군가가 판정을 했다면 성공 여부와 관계없이 이 효과는 없어진다.`,`길을 왕래하는 행인들로 북적이는 거리. 누구도 당신에게 관심을 보이지 않는다. 이 장면에서는 「불간섭」 세계 법칙을 무시하고 임의로 선택한 캐릭터를 조사할 수 있다.`,`어딘지 알 수 없는 공간. 당신이 가장 사랑하는 인물이 눈앞에 나타난다. 이 장면에 등장한 PC 중 한 명은 《정열》로 판정할 수 있다. 판정에 성공하면 임의의 앵커에 대한 【운명】을 1점 상승시킬 수 있다. 판정에 실패하면 「운명 변전」이 발생한다. 누군가가 판정을 했다면 성공 여부와 관계없이 이 효과는 없어진다.`]},MCST:{name:`마법 도시 장면 표`,type:`2D6`,items:[`갑자기 폭발이 일어난다. 누군가가 실험에 실패한 모영이다. 「타짐」 상태이상에 걸린 후, 「힘」 마소를 2점 획득한다.`,`표본이 죽 늘어선 지하실. 실험으로 태어난 마법생물이 병 속에 갇힌 채 나열되어 있다.`,`매우 혼잡한 시장. 형형색색의 식료품이나 일용품을 비롯해서 환수의 눈알이나 만드라고라의 뿌리 같은 마법 촉매까지 팔고 있다. 이 장면에 등장한 PC는 각자 한 번씩 공적점이나 마화 1점을 소비해서 원하는 마소를 2점 획득할 수 있다.`,`마법사들이 모이는 살롱. 이곳이라면 유익한 정보를 얻을 수 있을 것 같다. 이 장면에 등장한 PC 중 한 명은 《이야기》로 판정할 수 있다. 판정에 성공하면 공개된 핸드아웃 중 원하는 것의 【비밀】을 공개할 수 있다. 판정에 실패하면 「봉인」 상태이상에 걸린다. 누군가가 판정을 했다면 성공 여부와 관계없이 이 효과는 없어진다.`,`대로. 환수가 끄는 마차, 하늘을 나는 융단이나 빗자루 따위의 탈것이 바쁘게 눈앞을 지나간다.`,`광장. 마법사끼리 다투기 시작하더니, 결국 마법까지 주고받으며 싸운다. 이 장면에 등장한 PC는 %{skill}(으)로 판정한다. 판정에 성공하면 원하는 마소를 2점 획득하지만, 실패하면 이 장소에서 사용된 마법의 영향이 시공을 넘어 앵커에게 미친다. 「운명 변전」이 발생한다.`,`떠들썩한 술집. 손님 중에는 요정이나 마물도 많이 있다. 이 장면에 등장한 PC는 【마력】이 1점 회복한다.`,`복잡한 뒷골목. 기묘한 이종족들로 구성된 도적단의 습격을 받는다. 《우레》로 판정한다. 판정에 실패하면 【마력】을 2점 감소하든지, 아니면 마법에 충전한 마소가 2점 이상 있을 경우 그것을 감소하든지 선택해야 한다.`,`도시의 문. 새로운 지식을 얻기 위해 찾아온 이, 자신의 세계로 돌아가는 이...... 다양한 세계의 다양한 사람들이 왕래한다.`,`환락가. 뿔이나 꼬리, 날개가 달린 미녀들이 피부를 노출하는 차림으로 요염한 시선을 보낸다.`,`투기장. 마법사가 강화한 원형이나 환수를 싸움 붙이고 있다. 장면 플레이어의 PC는 한 번만 기본 룰북에 실린 랭크4 이하의 〈서젹경〉이나 〈월경자〉에게 마법전을 신청할 수 있다. 여기에 승리하면 「프라이즈 표」를 사용할 수 있다.`]},WDST:{name:`사후 세계 장면 표`,type:`2D6`,items:[`한적한 거리. 그림자 같은 형상의 사람들이 때때로 왕래한다. 여기에서는 죽은 캐릭터를 만날 수 있다. 이 장면에 등장한 PC 중 한 명은 상흔을 하나 극복할 수 있다.`,`한없이 넓은 꽃밭. 평온한 분위기가 충만하다.`,`재판소. 험악한 표정의 재판관이 넘쳐나는 망자들에게 순서대로 판결을 내리고 있다. 《거짓》 판정을 한다. 판정에 실패하면 【마력】이 2점 감소한다.`,`새하얀 빛에 휩싸인 식당. 호화로운 식사와 맛있는 술을 끝없이 대접받는다. 이 장면에 등장한 PC 중 한 명은 《살》로 판정할 수 있다. 판정에 성공하면 【일시적 마력】을 1점 획득하지만, 실패하면 「병마」 상태이상에 걸린다. 누군가가 판정을 했다면 성공 여부와 관계없이 이 효과는 없어진다.`,`바닥이 하얀 구름으로 이루어진 장소. 구름 틈새로는 현세로 추정되는 풍경이 보인다. %{skill}(으)로 판정한다. 판정에 성공하면 이 세션 동안 한 번만 판정에서 굴린 주사위를 다시 굴릴 수 있다. 실패하면 시공을 넘어 앵커가 사후 세계를 엿보고 만다. 「운명 변전」이 발생한다.`,`넓은 강이 흐르는 강변. 강 건너편은 현세일까? 이 장면에 등장한 PC 중 한 명은 《원환》으로 판정할 수 있다. 판정에 성공하면 마력을 리셋할 수 있다. 누군가가 판정을 했다면 성공 여부와 관계없이 이 효과는 없어진다.`,`예배당. 죽어서도 여전히 기도를 올리는 영혼이 말 없이 무릎을 꿇고 있다. 이 장면에 등장한 PC 중 한 명은 《기도》로 판정할 수 있다. 판정에 성공하면 【일시적 마력】을 2점 획득하지만, 실패하면 「불운」 상태이상에 걸린다. 누군가가 판정을 했다면 성공 여부와 관계없이 이 효과는 없어진다.`,`지극히 평범한 주택가. 일상적인 행동을 되풀이하는 혼이 모이는 장소다.`,`고문장. 죽은 이들이 악귀들의 손에 무한한 고통을 맛보고 있다. 이 장면에 등장한 PC 중 한 명은 《절망》으로 판정할 수 있다. 판정에 성공하면 【일시적 마력】을 2점 획득하지만, 실패하면 「타짐」 상태이상에 걸린다. 누군가가 판정을 했다면 성공 여부와 관계없이 이 효과는 없어진다.`,`전장. 발키리가 이끄는 전사들이 거인과 싸우고 있다. 이 장면에 등장한 PC 중 한 명은 《천공》으로 판정할 수 있다. 판정에 성공하면 【일시적 마력】을 3점 획득할 수 있지만, 실패하면 【마력】이 2점 감소한다. 누군가가 판정을 했다면 성공 여부와 관계없이 이 효과는 없어진다.`,`어딘지 알 수 없는 공간. 당신이 가장 사랑하는 인물이 눈앞에 나타난다. 이 장면에 등장한 PC 중 한 명은 《정열》로 판정할 수 있다. 판정에 성공하면 임의의 앵커에 대한 【운명】을 1점 상승시킬 수 있다. 판정에 실패하면 「운명 변전」이 발생한다. 누군가가 판정을 했다면 성공 여부와 관계없이 이 효과는 없어진다.`]},LWST:{name:`미궁 세계 장면 표`,type:`2D6`,items:[`석제 타일이 깔려 있는 텅 빈 방. 바닥에 그린 마법진이 묘하게 기분 나쁜 빛을 내고 있다. 이 장면에 등장한 PC 중 한 명은 《이계》로 판정할 수 있다. 판정에 성공하면 그 마법진을 지구로 귀환하는 마법문으로 사용할 수 있다. 판정에 실패하면 마법문에서 나타난 미지의 괴물에게 습격받아 이 장면에 등장한 PC 전원의 【마력】이 1D6점 감소한다. 누군가가 판정을 했다면 성공 여부와 관계없이 이 효과는 없어진다.`,`희미하게 빛나는 램프가 밝히는 감옥. 감옥 안에는 누군가의 해골이 굴러다니고 있다. 이 장면에 등장한 PC 중 한 명은 《죽음》으로 판정할 수 있다. 판정에 성공하면 공개된 핸드아웃 중 원하는 것의 【비밀】을 공개할 수 있다. 판정에 실패하면 시체가 저주의 말을 내뱉으면서 이 장면에 등장한 PC 전원이 「타짐」 상태이상에 걸린다. 누군가가 판정을 했다면 성공 여부와 관계없이 이 효과는 없어진다.`,`통로 건너편에 문과 간판이 있다. 간판의 문자를 읽어보니 여관이라는 의미다. 이 장면에 등장한 PC 전원은 한 번만 공적점이나 마화 1점을 소비해서 조율을 1회 할 수 있다.`,`사람 한 명이 겨우 지나갈 정도로 좁은 통로가 계속된다. 이 복도는 대체 어디까지 이어지는 걸까?`,`몇 개의 문과 몇 개의 갈림길을 통과했다. 어라? 어느새 길을 잃은 것 같다. 장면 플레이어 이외의 PC가 이 장면에 등장하고 싶다면 《길》로 판정해야 한다. 실패한 PC는 이 장면에 등장할 수 없다.`,`괴물이 나타나 여러분을 덮친다. 이 장면에 등장한 PC 전원은 %{skill}(으)로 판정한다. 판정에 성공하면 괴물을 쓰러트리며, 임의로 선택한 마소가 1점 발생한다. 판정에 실패하면 싸우다 입은 부상이 사간과 공간을 넘어 앵커에게 불행을 가져다준다. 「운명 변전」이 발생한다.`,`눈앞에는 비슷한 모양의 문이 죽 이어지고 있다. 어느 문을 열어야 할까?`,`어둠 속에서 무언가가 낮게 으르릉거리는 소리가 들린다. 아무래도 근처에 괴물이 숨어 있는 것 같다. 무사히 잘 지나가야 할 텐데...... 《정적》으로 판정한다. 실패하면 【마력】이 1점 감소한다.`,`통로가 끊기고, 깊은 균열이 입을 벌리고 있다. 빛도 바닥까지 닿지 않아 마치 땅속 끝까지 이어져 있는 것만 같다. 「어둠」 마소를 1점 획득할 수 있다.`,`금화나 은화, 보석에 왕관 같은 보물이 산처럼 쌓여 있는 방. 파수꾼은 없는 것 같은데...... 이 장면에 등장한 PC 중 한 명은 《황금》으로 판정할 수 있다. 판정에 성공하면 1D6점의 마화나 무작위로 결정한 마소 3점을 획득할 수 있다. 판정에 실패하면 이 장면에 등장한 PC 전원의 【마력】이 3점 감소한다. 누군가가 판정을 했다면 성공 여부와 관계없이 이 효과는 없어진다.`,`막다른 길의 벽에는 언뜻 보기에 의미를 알 수 없는 문자가 나열되어 있다. 이 앞으로 가려면 이 문자의 수수께끼를 풀어야 한다는 걸까? 이 장면에 등장한 PC 중 한 명은 《수수께끼》로 판정할 수 있다. 판정에 성공하면 공개된 핸드아웃 중 원하는 것의 【비밀】을 공개할 수 있다. 실패하면 방에 설치된 함정이 발동해서 이 장면이 강제로 종료된다. 누군가가 판정을 했다면 성공 여부와 관계없이 이 효과는 없어진다.`]},STB:{name:`대형판 장면 표`,type:`2D6`,items:[`여기가 아닌 어딘가. 마법의 힘이 충만한 이경 중 한곳으로 한순간의 여행을 떠난다. 그 장면에 별 마소가 1점 발생한다.`,`꿈 속, 먼 과거의 풍경이 당신의 앞에 나타난다. 그 장면에 꿈 마소가 1점 발생한다.`,`거센 바람이 불며 구름이 흘러간다. 멀리서 천둥 소리가 들렸다. 그 장면에 힘 마소가 1점 발생한다.`,`고요한 카페 안. 커피 향기와 함께 우아하고 온화한 분위기가 충만하다.`,`아무도 없는 뒷골목. 여기라면 방해받을 일도 없겠지.`,`주위에서 <단장>이 일으킨 마법 재액이 발생한다. %{skill}(으)로 판정한다. 성공하면 그 장면에 원하는 마소가 1점 발생한다. 실패하면 「운명 변전 표」를 사용한다.`,`평범하기 그지 없는 평화로운 풍경. 하지만 그런 일상의 배후에서 마법 재액의 그림자를 느낀다.`,`읽던 책을 덮는다. 거기에는 당신이 알고 싶었던 정보가 적혀 있었다. 과연, 그렇게 된 거였나.`,`밤의 길거리를 걷는다. 저 멀리 집집마다 따스하게 빛나는 조명이 보인다. 그 장면에 노래 마소가 1점 발생한다.`,`인파로 북적이는 광장. 축제라도 열었나? 누군가가 부르는 소리가 들린다. 그 장면에 짐승 마소가 1점 발생한다.`,`비극의 예감. 가족의 불행, 친구의 절망, 동료의 죽음….. 이대로 내버려두면 일어날지도 모를 사건의 환각이 보인다. 그 장면에 어둠 마소가 1점 발생한다.`]},MGCT:{name:`운명 변전 표 「마법사 재액」`,type:`1D6`,items:[`혐오. 우자들을 혐오하고, 〈대법전〉의 방식에 의문을 품게 된다. 이 불행이 두 번 발생하면, 그 마법사는 사망하는 대신 〈서적경〉이 되어 NPC가 된다. 이 불행이 〈서적경〉에게 내렸을 때는 불행이 무효가 된다.`,`악의. 마법과 관련된 절실한 소원이나 사악한 욕망이 점점 비대화한다. 이 불행이 두 번 발생하면, 그 마법사는 사망한 후 〈금서〉가 되어 NPC가 된다.`,`유령. 육체를 거의 잃어 영적인 존재가 된다. 이 불행이 두 번 발생하면, 그 마법사는 사망하는 대신 소멸한다.`,`연쇄. 운명 변전이 발생한다. 이 불행이 두 번 발생해도 사망하지 않는다.`,`상태이상. 무작위로 상태이상을 하나 입는다. 이 불행이 두 번 발생해도 사망하지 않는다.`,`소모. 【마력】이 1점 감소한다. 이 불행이 두 번 발생해도 사망하지 않는다.`]},MBST:{name:`마법 서가 장면 표`,type:`2D6`,items:[`<금서> 보관고의 입장을 허가받았다. 몇 겹의 결계와 예리한 눈매의 서경들이 눈에 띈다. 그 틈을 노려 〈금서〉가 습격해 왔다! 이 장면에 등장한 PC 중 한 명만 《%{force}》(으)로 판정을 한다. 실패하면 【마력】을 3점 감소한다. 성공하면 【일시적 마력】을 3점 얻는다. 누군가가 판정을 하면 성공 여부와 관계없이 이 효과는 없어진다.`,`개인용 방. 좁지만 가장 마음이 놓이는 장소다. 이 장면에 등장한 PC 중 한 명은 【마력】을 상한까지 회복할 수 있다.`,`도시의 도서관. 어느새 인계로 돌아와버린 것 같다. 이 장면에 등장한 PC 중 한 명은 임의의 캐릭터를 한 명 골라 사건 표에서 주사위를 1회 굴리고, 그 효과를 적용한다.`,`거대한 원탁이 준비된 방. 아무래도 이곳은 회의장인 것 같다.`,`긴 복도. 학원의 제복을 입은 소년, 소녀들이 웃고 떠들며 달려간다.`,`황폐해진 방. 텅 빈 책장이 쓰러져 있는 모습이 눈에 띈다. 이것은 〈대파괴〉의 영향일까......? %{skill}(으)로 판정한다. 실패하면 시공을 넘어 앵커에게 영향이 나타난다. 「운명 변전」이 발생한다.`,`창고. 아직 정리하지 않은 책이 산처럼 쌓여 있고, 사서들이 정신 없이 분류 작업을 하고 있다.`,`길을 헤매다가 누군가의 연구실에 들어갔다. 쌓여있는 마도서가 흥미를 끈다.`,`높은 천장, 그리고 천장에서 이어지는 벽을 가득 메우는 책들. 이 모두가 이 서고에 보관하는 마도서다. 이 장면에 등장한 PC 중 한 명은 【일시적 마력】을 1점 획득한다.`,`마도서 열람실. 몇 명의 마법사가 열심히 마도서를 읽고 있다. 무작위로 특기 하나를 선택한다. 이 장면에 등장한 PC 중 한 명은 %{skill}(으)로 판정한다. 판정에 성공하면 습득한 마법 하나를 습득 가능한 다른 마법으로 바꿀 수 있다. 실패하면 「봉인」 상태이상에 걸린다. 누군가가 판정을 했다면 성공 여부와 관계없이 이 효과는 없어진다.`,`책장과 책장 사이에 갑자기 문이 나타난다. 이 문은 이경으로 이어지는 출입구다. 도대체 어디로 연결되어 있는 걸까? 이경 장면 표 중 하나를 무작위로 선택해서 2D6을 굴리고, 해당하는 효과를 적용한다.`]},MAST:{name:`마법 학원 장면 표`,type:`2D6`,items:[`눈앞에 아름다운 흑룡이 나타났다. 학원장 자날파토스다. 대체 무슨 말을 하러 나타난 걸까?`,`갑자기 무언가가 덤벼들었다! 학생이 원형 소환에 실패한 모양이다. 이 장면에 등장한 PC 중 한 명만 ≪%{force}≫(으)로 판정한다. 판정에 실패하면 【마력】이 2점 감소한다. 판정에 성공하면 【일시적 마력】을 3점 얻는다. 누군가가 판정을 했다면 성공 여부와 관계없이 이 효과는 없어진다.`,`이곳은...... 여자 기숙사? 이 장면에 남성 PC가 등장했다면 그 남성 PC는 ≪%{beast}≫(으)로 판정한다. 실패하면 「봉인」 상태이상에 걸린다.`,`기숙사 복도. 「거기 누구죠?」 사감 시그리드가 불러 세웠다. 이 장면에 등장한 PC는 《자유》로 판정한다. 실패하면 이 장면에서 시도하는 모든 판정에 -1의 수정을 적용한다.`,`천장이 높은 복도. 두꺼운 문 너머에서 수업을 하는 강사의 목소리가 희미하게 들려온다.`,`문을 열며 나타난 것은 잘 아는 상대였다. 무슨 이유인지 학원에 들어와버린 모양이다. %{skill}(으)로 판정한다. 여기에 실패하면 「운명 변전」이 발생한다.`,`길을 잃고 헤매다가 누군가가 만든 좁고 비밀스러운 방에 들어갔다. 학원에서는 그다지 먹을 기회가 없는 과자를 잔뜩 넣어둔 모양이다.`,`학원 서부에 펼쳐진 아덴의 숲. 새의 울음소리가 들린다.`,`수업 중인 교실. 강사가 불러낸 원형이 이쪽으로 날아온다. 이 장면에 등장한 PC 중 한 명만 %{skill}(으)로 판정한다. 판정에 실패하면 【마력】이 1점 감소한다. 성공하면 그 특기의 정령을 소환할 수 있다. 누군가가 판정을 했다면 성공 여부와 관계없이 이 효과는 없어진다.`,`학생이 뭔가 마법을 보여달라고 청한다. 이 장면에 등장한 PC 중 한 명만 ≪%{dream}≫(으)로 판정한다. 판정에 실패하면 「불운」 상태이상에 걸린다. 성공하면 「꿈」 마소를 2점 획득한다. 누군가가 판정을 했다면 성공 여부와 관계없이 이 효과는 없어진다.`,`자습실. 학생들이 필사적으로 마도서의 내용을 이해하려고 애쓴다. 이 장면에 등장한 PC 중 한 명만 ≪%{star}≫(으)로 판정한다. 판정에 성공하면 원하는 마소를 2점 획득한다. 누군가가 판정을 했다면 성공 여부와 관계없이 이 효과는 없어진다.`]},TCST:{name:`크레도의 탑 장면 표`,type:`2D6`,items:[`눈 앞에 한 소녀가 나타난다. 잠자는 공주의 우두머리, 라투나다. 항상 잠만 자고 있을 그녀가 나타나다니, 도대체 무엇을 전하러 온 걸까?`,`갑자기 무언가가 습격해 왔다! 미숙한 마법사가 원형 소환에 실패한 모양이다. 이 장면에 등장한 PC 중 한 명만 ≪%{force}≫(으)로 판정한다. 판정에 실패하면 【마력】이 2점 감소한다. 판정에 성공하면 【일시적 마력】을 3점 얻는다. 누군가가 판정을 했다면 성공 여부와 관계없이 이 효과는 없어진다.`,`말을 걸어온 천애의 예언자가 불행한 미래를 예언한다. 이 장면에 등장한 PC 중 한 명만 ≪%{dream}≫(으)로 판정한다. 판정에 실패하면 【마력】이 1점 감소한다. 판정에 성공하면 「꿈」 마소를 1점 획득할 수 있다. 누군가가 판정을 했다면 성공 여부와 관계없이 이 효과는 없어진다.`,`탑 안쪽 벽에 진열된 무수한 마도서의 앞. 여기에서 뭔가 단서를 얻을 수 있을지도 모른다. 이 장면에 등장한 PC 중 한 명은 【일시적 마력】을 1점 획득한다.`,`작은 객실에서 〈대법전〉에서 온 사자와의 회합이 진행되고 있다. 천애가 새로운 예언을 전달하고 있는 걸까?`,`이런 곳에 있을 리가 없는 인물이 당신의 앞에 나타난다. 잠자는 공주의 꿈속에 우연히 들어와버린 모양이다. %{skill}(으)로 판정한다. 실패하면 「운명 변전」이 발생한다.`,`탑 위. 끝없이 이어진 산맥과 그 위에 떠오른 달이 탑을 조용히 내려다보고 있다.`,`탑 외벽에 설치된 나선 계단 위. 강풍이 불어닥치고 있다.`,`크레도의 탑으로 이어지는 험악한 산길. 뭔가가 숨어 있기라도......? 「짐승」 마소를 1점 획득할 수 있다.`,`환몽전 내부. 잠자는 공주들의 편안한 숨소리가 들려온다. 이쪽까지 졸려온다.`,`갑자기 눈앞에 문이 나타난다. 이 문은 이경으로 이어지는 출입구다. 도대체 어디로 연결되어 있는 걸까? 이경 장면 표 중 하나를 무작위로 선택해서 2D6을 굴리고, 해당하는 효과를 적용한다.`]},PWST:{name:`병행 세계 장면 표`,type:`2D6`,items:[`카페의 테이블. FM 라디오에서는 작년에 해산했을 밴드가 어제 발표한 신곡이 흘러나오고 있다. 이 장면에 등장한 PC 중 한 명은 「시간의 흐름 표」에서 주사위를 한번 굴려 효과를 적용한다.`,`인파로 북적이는 길거리. 건너편에서 당신과 쏙 빼닮은 인물이 걸어온다. 저것은 이 세계의 당신 자신일까? PC 중 한 명은 %{skill}(으)로 판정한다. 판정에 성공하면 원하는 마소를 2점 획득하지만, 실패하면 「병마」 상태이상에 걸린다. 누군가가 판정을 했다면 성공 여부와 관계없이 이 효과는 없어진다.`,`밤에 거리를 돌아다닌다. 잘 아는 풍경인데도 어딘가 다르다는 위화감을 떨칠 수가 없다.`,`손님으로 북적이는 상점가. 망한 가게가 멀쩡히 장사를 하고 있거나, 장사가 잘 되던 가게가 문을 닫은 모습이 보인다.`,`번화가. 건물의 대형 모니터에서 어딘지 모를 나라들의 전쟁 소식을 전하는 뉴스가 나온다.`,`알고 지내는 인물의 집 앞. 현관에서 낯선 사람이 나타나 이쪽을 수상하다는 듯이 바라본다. 이 사람, 혹시......? %{skill}(으)로 판정한다. 판정에 실패하면 「운명 변전」이 발생한다.`,`승객이 없는 전철 내부. 안내 방송에서 종종 듣도 보도 못한 역의 이름이 흘러 나온다.`,`역전의 로터리에 나가 보니 귀가 중인 학생들이 눈에 들어온다. 저 학교 교본의 리본이 빨간색이었던가?`,`양옥 앞. 여기에는 이런 건물 없었을 텐데?`,`초등학교 앞을 지나간다. 음악실 창 너머로 낯선 음악가의 초상화가 보인다. ≪%{poem}≫(으)로 판정한다. 판정에 실패하면 「봉인」 상태이상에 걸린다.`,`눈앞에서 예전에 경험한 적이 있는 일이 일어난다. 이 세계에서는 지금부터 일어나는 일이다. 이 장면에 등장한 PC 중 한 명은 이 장면 동안 판정에 +1의 수정을 적용한다.`]},PAST:{name:`종말 장면 표`,type:`2D6`,items:[`밤. 비를 피하러 사원에 들어간다. 위험한 기척은 느껴지지 않는 것을 보니 느긋하게 쉴 수 있을 것 같다. 조용한 시간이 흘러간다.`,`밤. 잡초가 무성하고 덩굴로 뒤덮인, 인기척 없는 산골 마을에서 거대한 육식 동물이 덤벼든다. 이 장면에 등장한 Pc 중 한 명은 《이빨》로 판정해야 한다. 실패하면 【마력】을 2점 잃는다. 누군가가 판정을 했다면 성공 여부와 관계없이 이 효과는 없어진다.`,`밤. 대규모 폭격에 의해 지평선으로 변한 전쟁터. 어느 나라의 것인지도 알 수 없는 국기가 밤바람에 펄럭인다. 허무 빙의자 하나가 나타나 덤벼든다. 마법전을 한다. 이 마법전은 게임 동안 한 번만 발생한다.`,`밤. 이미 폐허가 되어버린 먼지투성이 도시. 〈우자〉가 허무 빙의자에게 습격당하고 있다. 이 장면에 등장한 PC 중 한 명은 %{skill}(으)로 판정할 수 있다. 성공하면 구출에 성공하며, 도와준 〈우자〉에 대해 임의의 속성으로 운명을 1점 획득한다. 실패하면 【마력】을 3점 잃는다.`,`밤. 허무 빙의자의 무리가 따라붙었다. 장면 플레이어는 《악의》로 판정을 한다. 실패하면 이 장면 동안 모든 판정에 -2의 수정을 적용한다.`,`날이 새기 전. 회색 황야와 그 중앙을 일직선으로 관통하는 고속 도로. 너무나도 조용해서 자신의 심장 소리가 느껴질 정도다. 허무 빙의자가 하나 나타나 덤벼든다. 마법전을 개시한다. 2라운드가 경과할 때까지는 밤, 이후의 라운드는 낮으로 처리한다. 이 마법전은 게임 동안 한 번만 발생한다.`,`낮. 〈우자〉 어린이가 역사적인 유산을 놀이터 삼아 혼자 놀고 있다. 이 아이의 미래는 어찌 될 것인가.`,`낮. 세계 대전으로 추락한 전투기가 사막의 모래에 반쯤 파묻혀 있다. 하지만 엔진은 아직 죽지 않았다. 이 장면에 등장한 PC 중 한 명은 《바람》으로 판정할 수 있다. 성공하면 마력 리셋을 한다. 성공 여부와 관계없이 이 효과는 한 번만 발생한다.`,`낮. 하얀 건물이 줄지어 서 있는 아름다운 해변. 한때는 휴양지였겠지만, 지금 그 곳에는 대량의 하얀 유골이 떠밀려와 바닷물에 휩쓸리고 있다. 아무나 한 명이 《이별》 특기로 판정해서 성공하면 무작위로 선택한 마소 3점을 획득한다. 누군가가 판정을 했다면 성공 여부와 관계없이 이 효과는 없어진다.`,`낮. 폐허가 된 농촌 근처에서 맛있어 보이는 과일을 발견한다. 《대지》로 판정해서 성공하면 【마력】이 2점 회복한다.`,`저녁. 녹슨 선로. 그 앞쪽까지 대량의 해골이 아무렇게나 굴러다니고 있다. 허무 빙의자가 하나 나타나 덤벼든다. 마법전을 개시한다. 2라운드가 경과할 때까지는 낮, 이후의 라운드는 밤으로 처리한다. 이 마법전은 게임 동안 한 번만 발생한다.`]},GBST:{name:`이세계 술집 장면 표`,type:`2D6`,items:[`주인장인 뇌신에게 트집을 잡힌다. 이 장면에 등장한 PC 중 한 명은 뇌신을 상대로 「사건 표」에서 주사위를 굴린다.`,`신성한 광휘와 함께 위엄이 넘치는 신이 나타나 그 자리의 분위기를 휘어잡는다. 이 장면 동안 「세계 법칙」에 「조사 저해」가 추가된다.`,`윗층으로 올라가려고 했더니 카미아리가 버티고 있다. 이 장면에 등장한 PC 중 한 명은 《불》로 판정한다. 실패하면 【마력】이 1점 감소한다. 성공할 때까지 판정을 계속해야 한다. 이 효과는 한 번만 발생한다.`,`「건배!」 따라준 술을 무심코 마셔버렸다. 어지간히 독한 증류주인 모양인데...... 이 장면에 등장한 PC 중 한 명은 《물》로 판정할 수 있다. 성공하면 마화를 1점 입수한다. 성공 여부와 관계없이 이 효과는 한 번만 발생한다.`,`건배를 외치는 소리, 주정뱅이의 웃음소리, 이쪽저쪽에서 목청껏 이야기를 나누는 소리...... 흔히 볼 수 있는 술집의 풍경이다.`,`손님 한 사람이 억지로 술을 먹였다. 뭐 이렇게 독한 술이 다 있지? %{skill}(으)로 판정한다. 실패하면 「운명 변전」이 발생한다.`,`계단을 오른다. 도대체 언제부터 오르기 시작했는지 기억나지 않는다. 이 계단 어디에서 끝나는 거지?`,`분명히 건물 안인데, 먹구름이 끼고 폭풍이 불기 시작한다. 신들이 싸우고 있다! 이 장면에 등장한 PC 중 한 명은 《폭풍》으로 판정한다. 실패하면 【마력】이 2점 감소한다. 성공 여부와 관계없이 이 효과는 한 번만 발생한다.`,`요괴가 문 앞에서 버티면서 지나가지 못하게 막는다. 요괴는 뭔가 달라고 졸라댄다. 이 장면에 등장한 PC 중 한 명은 아무거나 마소를 1점 감소한다. 감소할 마소가 없다면 【마력】이 1점 감소한다.`,`윗층으로 올라가려고 했더니 용이 버티고 있다. 이 장면에 등장한 PC 중 한 명은 《이빨》로 판정한다. 실패하면 「타짐」 상태이상에 걸린다. 성공 여부와 관계없이 이 효과는 한 번만 발생한다.`,`아름다운 여신이 거울을 들여다보고 있다. 듣자하니 운명이 비치는 거울이라는 모양인데...... 이 장면에 등장한 PC 중 한 명은 《미래》로 판정할 수 있다. 성공하면 원하는 앵커와의 【운명】이 1점 상승한다. 성공 여부와 관계없이 이 효과는 한 번만 발생한다.`]},SLST:{name:`별빛 장면 표`,type:`2D6`,items:[`차장이 나타나 당신이 가진 「표」는 효력이 없다고 알린다. 다른 승객의 눈이 따갑다. 이 장면에 등장한 PC 중 한 명은 다시 한 번 「표」를 조달해야 한다. 혼의 특기 판정을 성공할 때까지 반복해야 한다.`,`덜컹, 덜컹. 덜컹, 덜컹. 유리보다 더 투명한 은하수의 곁을 달린다. 형형색색의 꽃들이 별빛을 받으며 창 너머로 지나간다.`,`문득 눈을 떴다. 흔들리는 기차 안에서 어느새 잠들었던 모양이다. 꿈 속에서 누군가와 만난 듯한 기분이 든다. 장면 플레이어가 《심연》 판정에 성공하면 무작위로 선택한 앵커와의 운명이 1점 상승한다.`,`은하수 곁에 오도카니 떠 있는 섬에 어딘가에서 본 듯한 하얗고 근사한 십자가가 우뚝 서 있다. 이 장면에 등장한 PC 중 한명은 《기도》로 판정할 수 있다. 성공하면 이후 이 게임 동안 발생하는 마법 재액을 한 번만 무효로 할 수 있다. 누군가가 판정을 했다면 성공 여부와 관계없이 이 효과는 없어진다.`,`창밖으로 은하를 지켜보는, 검은 외투를 입은 소녀가 있다. 당신을 알아차리더니 과자를 주며 빙그레 웃고는 그 자리를 떠났다. 장면 플레이어는 무작위로 선택한 마소를 1점 획득한다.`,`노이즈 섞인 차내 방송이 「정차역」 도착을 알린다. 잠시 후, 「기차」가 멈췄다. 캐릭터는 「정차역」에서 내릴 수 있다. 내린다면 「정차역」의 세계 법칙을 경정하고, 그 법칙에 따라 장면을 진행한다.`,`차장 너머로 별빛을 받아 푸름스름하게 빛나는 억새밭이 펼쳐져 있다. 그 가운데에서 이상한 무늬가 그려진 삼각 표지판에 몇 개가 듬성듬성 서 있는 것이 보였다.`,`정신을 차리고 보니 아무도 없다. 푸른 벨벳을 씌운 좌석만이 이 공간을 덧없이 장식하고 있다. 장면 플레이어 이외의 PC가 이 장면에 등장하기 위해서는 《정적》 판정을 해야 한다. 실패한 PC는 이 장면에 등장할 수 없다.`,`「여기 앉아도 될까요?」 당신의 옆자리에 〈서적경〉이 앉는다. %{skill}(으)로 판정한다. 판정에 성공하면 공개된 핸드아웃 중에서 원하는 것을 골라 해당하는 【비밀】을 공개할 수 있다. 누군가가 판정을 했다면 성공 여부와 관계없이 이 효과는 없어진다.`,`은하를 건너는 철새 떼. 잠시 「기차」와 나란히 날다가, 이윽고 다시 거리를 두고 은하수처럼 반짝거리는 빛의 띠로 변해간다. 이 장면에 등장한 PC 중 한 명은 《날개》로 판정할 수 있다. 성공하면 마력을 리셋할 수 있다. 누군가가 판정을 했다면 성공 여부와 관계없이 이 효과는 없어진다.`,`옆 차량에서 누군가가 넘어왔다. 놀랍게도 당신의 앵커다. 이 장면에 등장한 PC를 무작위로 한 명 선택하고, 그 PC의 앵커 중에서 이 이경에 존재하지 않는 〈우자〉 앵커를 무작위로 한 명 선택한다. 그 앵커가 원래 세계로 무사히 돌아갈 수 있었다면 게임을 종료할 때 공적점을 1점 획득한다.`]},WLAT:{name:`세계 법칙 추가 표`,type:`1D6`,items:[`세계 법칙 「낙원」. 이 「정차역」은 아름답고 마음에 위안이 되는 곳이다. 이 「정차역」에 내린 〈우자〉는 그 장소에 매료되어 이곳에서 평생을 보내게 된다. 「각인에 따른 풍경」에서 지정한 특기로 판정해서 성공하면 이를 말릴 수 있다. 이 판정은 대상이 되는 〈우자〉마다 한 번씩만 할 수 있다.`,`세계 법칙 「밤 축제」. 별빛이나 제등을 조명 삼아 끝없는 축제가 계속된다. 이 장면에 등장한 캐릭터는 「각인에 따른 풍경」에서 지정한 특기로 판정해서 성공할 경우 【치료】 속주를 사용했을 때 소비한 마소 1점당 2점씩의 【마력】을 회복할 수 있다.`,`세계 법칙 「유기」. 이 「정차역」 주변에는 다양한 것들이 버려져 있다. 장면 플레이어가 「각인에 따른 풍경」에서 지정한 특기로 판정해서 성공할 경우, 마법 【회상】과 같은 효과가 한 번 발생한다. 누구를 대상으로 할지는 장면에 등장한 캐릭터 중에서 무작위로 선택한다.`,`세계 법칙 「요접」. 이 「정차역」 주변에는 마소를 띤 신기한 색깔의 날개가 달린 나비가 서식한다. 이 장면에 등장한 캐릭터는 「각인에 따른 풍경」에서 지정한 특기로 판정해서 성공할 경우, 임의의 마소를 2점 획득할 수 있다. 실패하면 무작위로 선택한 한 가지 상태이상에 걸린다.`,`이 「정차역」 주변은 죽은 〈우자〉들의 종착점이기도 하다. 혹시 여기에서 내리는 〈우자〉가 있다면, 그 인물은 죽은 것이다. 이 장면에 등장한 캐릭터가 그 〈우자〉를 앵커로 두고 있다면, 「각인에 따른 풍경」에서 지정한 특기로 판정해서 성공할 경우 대상을 「상흔」으로 만들지 않고 운명 칸에서 소거할 수 있다.`,`세계 법칙 「마법문」. 다른 이경으로 통하는 입구가 있다. 「각인에 따른 풍경」에서 지정한 특기로 판정해서 성공하면 그 마법문을 발견할 수 있다.`]},WMT:{name:`떠돌이 괴물 표`,type:`1D6`,items:[`트롤이 이끄는 오크와 고블린의 대군과 만난다. 수백 마리의 괴물들이 야만적인 고함 소리와 함께 마법사들을 덮친다. 장면에 등장한 PC 전원은 ≪%{star}≫(으)로 판정한다. 전원의 판정을 마쳤다면, 실패한 PC는 1D6점의 대미지를 입는다. 이때, 판정에 성공한 PC의 수만큼 대미지 수치를 경감할 수 있다.`,`거대한 소의 머리가 달린 거한, 미노타우로스가 앞 길을 막더니, 손에 든 청동 도끼를 치켜 올린다. 장면에 등장한 PC 중에서 무작위로 대표 한 명을 선택한다. 대표는 ≪%{beast}≫(으)로 판정해야 한다. 실패하면 PC 전원은 2점의 대미지를 입고, 「타짐」 상태이상에 걸린다.`,`갑자기 드래곤이 나타난다. 진홍 비늘에 뒤덮인 거대한 그림자는 머리를 쳐들더니 그 직후 강렬한 불길을 뿜었다. 이 장면에 등장한 PC 전원은 ≪%{force}≫(으)로 판정한다. 전원의 판정을 마쳤다면, PC 전원은 1+ 판정에 실패한 멤버의 수만큼 대미지를 입는다.`,`백은 갑옷을 입은 기사가 나타난다. 기사는 일대일 결투를 신청했다. 장면에 등장한 PC 중에서 대표 한 명을 선택한다. 대표는 ≪%{poem}≫(으)로 판정해야 한다. 실패하면 대표가 5점의 대미지를 입는다.`,`아름다운 상반신과 짐승의 하반신을 가진 여성형 괴물이 나타나더니, 몸을 요염하게 흔들면서 손을 내민다. 장면에 등장한 PC 전원은 ≪%{dream}≫(으)로 판정한다. 실패한 PC는 3점의 대미지를 입고, 임의로 선택한 마소를 3점 잃는다.`,`검은 로브를 걸친 유귀가 나타난다. 말라 죽은 나무처럼 가느다란 팔을 치켜 올리더니, 저주의 말을 외친다. 장면에 등장한 PC 전원은 ≪%{night}≫(으)로 판정한다. 실패한 PC는 「불행」 상태이상에 걸리며, 운명 변전이 발생한다.`]},FFT:{name:`낙화 표`,type:`1D6`,items:[`육체가 초목이 시들 듯이 붕괴한다. 견딜 수 없을 만큼 고통스러운 것 같다. 〈영원〉은 의미조차 없는 단말마로 듣는 이를 괴롭히며 죽는다. 〈영원〉을 앵커로 두고 있다면, 그 앵커는 상흔이 된다.`,`정신이 망가진다. 〈영원〉은 망가진 악기처럼 자신의 꿈이나 소망을 작은 목소리로 되풀이해서 말하다가 계절이 바뀔 때 죽는다. 〈영원〉을 앵커로 두고 있다면, 그 앵커는 상흔이 된다.`,`〈영원〉의 생명력이 폭주해서 죽음과 재생을 되풀이한다. 도와달라는 애원조차 하지 못한다. 1D6개월 후, 죽는다. 〈영원〉을 앵커로 두고 있다면, 그 앵커는 상흔이 된다.`,`〈금서〉와 함께 봉인된다. 운명을 맺은 PC의 꿈에 나타나 '어둡다', '무섭다', '도와달라'는 말을 되풀이 하지만, 다음 초승달이 뜰 무렵에는 그조차 뚝 끊긴다. 〈영원〉을 앵커로 두고 있다면, 그 앵커는 상흔이 된다.`,`그 순간에는 아무 일도 일어나지 않는다. 운 좋게 살아남아 〈우자〉로 돌아간 것처럼 보인다. 하지만 일단 잠들면 두 번 다시 눈을 뜨지 못하고 죽는다. 〈영원〉을 앵커로 두고 있다면, 그 앵커는 상흔이 된다.`,`몸이 시들며 「씨앗」을 떨군다. 하지만 재생하지는 않는다. 땅에 심어주면 종류야 어떻든 식물로서 싹을 틔울 것이다(〈영원〉을 앵커로 두고 있다면 그 앵커를 잃는다. 상흔이 되지는 않는다).`]},OLST:{name:`구 도서관 장면 표`,type:`2D6`,items:[`曲がり角。唐突に〈禁書〉が現れ、襲いかかってきた！このシーンに登場するPCは、%{skill}で判定を行う。失敗すると、【魔力】を3点失う。`,`通路の真ん中。扉を開けて〈旧世界秩序〉の〈書籍卿〉「古き書物の化身」が現れた。彼はこのシーンに登場しているPCに協力を申し出る。このシーンに登場しているPCの一人は、《嘘》で判定を行う。成功すると〈書籍卿〉はこのシナリオの間、そのPCが行う魔法戦で、一度だけ立会人になる。失敗すると〈書籍卿〉は怒り出し、次のシーンでそのPCに対して、魔法戦をしかけてくる。誰かが判定すると、成否にかかわらず、この効果はなくなる。`,`元・研究室。壊れた実験道具が床に散らばっている。`,`元・閲覧室。数人の魔法使いたちが休んでいる。ここならば、色々な話が聞けそうだ。`,`空の書架が並ぶ、開けた空間。ここならば、一息つけるだろう。`,`破壊された魔導書が、山のように積み重なる場所。本の山に隠れていた〈断章〉が襲い掛かってくる。このシーンに登場するPCは、%{skill}で判定を行う。成功すると、〈断章〉を倒し、好きな魔素を一個手に入れる。失敗すると、時空を超えてアンカーに影響が現れる。「運命変転」が発生する。`,`破壊された書架が重なり合って作り上げた、迷路のような通路が続く。この先には、何があるのだろうか`,`元・宿舎。簡素な寝台が、いくつか残っている。`,`通路の行き止まり。目の前になぜか大きな箱がある。このシーンに登場しているPCの一人は、《謎》で判定を行うことができる。成功すると、箱の中にプライズを発見する。「プライズ表」を1回使用することができる。失敗すると、トラップが発動する。箱は爆発し、このシーンに登場しているPC全員の【魔力】が1点減少する。誰かが判定すると、成否にかかわらず、この効果はなくなる。`,`どこからか湧き出した水が、床の上に泉を作っている場所。泉の上に何者かの呼び出した元型が浮かんでいる。%{skill}で判定を行う。成功すると、【一時的魔力】を1点手に入れる。失敗すると、攻撃され、【魔力】が1点減少する。誰かが判定すると、成否にかかわらず、この効果はなくなる。`,`なぜ、君がここに？扉を開けると、そこにはPCのアンカーがいた。シーンプレイヤーのアンカーの中から、ランダムに一人を選ぶ。そのアンカーが登場する。シーンプレイヤーは、そのアンカーに「事件」を行っても、行動済みにならない。`]},TPTB:{name:`대형판 시간의 흐름 표`,type:`1D6`,items:[`파란만장한 인생을 보낸다. 이 시대에 일어난 유명한 사건의 배후에는 많은 마법적 존재가 암약했다. 당신도 그 사건에 관여하여 〈금서〉나 〈서적경〉들과 싸웠다. %{skill}(으)로 판정한다. 판정에 성공하면 세션을 종료할 때 공적점을 1점 더 획득한다. 실패했다면 자신에게 「운명 변전」이 발생한다.`,`모험의 나날을 보내던 도중에 큰 행복이 찾아온다. %{skill}(으)로 판정한다. 판정에 성공하면 자신의 앵커가 짊어지고 있는 불행이나 자신이 짊어지고 있는 상흔 하나를 무효로 한다.`,`명상 중이었는지, 아니면 무언가 봉인되고 있었는지...... 오랜 잠에서 눈을 뜬다. 벌써 이런 시간인가. 덕분에 충분히 쉴 수 있었다. 「%{element}」「%{element}」「%{element}」(을)를 획득하거나, 「마력 리셋」을 하거나, 자신에게 걸린 상태 이상을 모두 회복한다.`,`특수한 이경을 여행옸다. 그 때문인지 인계에서 무슨 일이 일어났는지 전혀 모른다. 우리사미 타로가 된 기분이다. 이경의 특산물을 구해왔다. 마화 1D6점을 획득한다.`,`거리의 사람들 사이에서 평온하게 살아간다. 그런 나날 속에서 사소한 사건이 일어났다. 자신의 앵커 한 명을 목표로 선택하여 「사건 표」에서 주사위를 굴릴 수 있다.`,`날마다 연찬을 거듭해서 마법 수행에 정진했다. 만약 바란다면 장서 칸에 있는 마법을 자신이 습득할 수 있는 다른 마법으로 변경할 수 있다. 만약 마소가 충전되어 있던 마법을 미습득 상태로 되돌렸다면, 그 마소는 잃는다.`]},FLT:{name:`그 후의 전개 표`,items_lower:[`성취자는 사악한 마법의 힘에 이끌린다. 성취자가 그 세션에서 <단장>에게 빙의당했거나 마법 재액에 희생당했다면 【타락치】가 1점 상승하며, 타락 체크를 해야 한다. 타락 체크에 실패하면 성취자는 목숨을 잃고, 해당하는 PC의 상흔이 된다.`,`성취자는 자신이 겪은 불행이 마법사의 탓이라고 믿게 된다. 성취자가 불행한 일을 당하면 【타락치】가 1점 상승한다. 타락 체크를 해야 한다. 타락 체크에 실패하면 소원을 들어준 PC는 성취자와의 【운명】 수치가 2점 감소한다.`,`성취자는 자신이 특별한 사람이라고 믿게 된다. 소원을 이루고자 하는 노력을 포기하여 나태해진다. 성취자의 【타락치】가 2점 상승한다. 타락 체크를 해야 한다. 타락 체크에 실패하면 성취자는 「운명 변전 표 『광기계 재액』」을 사용해서 해당하는 불행에 휘말린다.`,`성취자는 소원을 이루면서 욕망이 더욱 커졌다. 다음에는 더 큰 소원을 바라게 될 것이다. 성취자의 【타락치】가 1점 상승한다. 타락 체크를 해야 한다. 타락 체크에 실패하면 성취자는 「운명 변전 표 『사회계 재액』」을 사용해서 해당하는 불행에 휘말린다.`,`성취자는 자신의 소원이 마법에 의해 이루어졌다는 것을 알아차린다. 성취자의 【타락치】가 1점 상승한다. 타락 체크를 해야 한다. 타락 체크에 실패하면 성취자는 「운명 변전 표 『초자연계 재액』」을 사용해서 해당하는 불행에 휘말린다.`,`성취자는 자신의 소원을 들어준 것이 PC라는 것을 알아차린다. 성취자의 【타락치】는 해당 PC가 성취자에 대해 맺은 【운명】 수치와 같아진다. 만약 이 효과로 【타락치】가 이전보다 늘었다면 타락 체크를 해야 한다. 타락 체크에 실패하면 성취자는 우자가 아니게 되며, 마법사가 된다.`],items_higher:[`성취자는 갑작스럽게 자신에게 찾아온 행운에 죄책감을 느끼게 된다. 만약 성취자의 【타락치】가 1 이상이라면 타락 체크를 해야 한다. 타락 체크에 실패하면 성취자는 「운명 변전 표 『정신계 재액』」을 사용해서 해당하는 불행에 휘말린다.`,`성취자는 소원을 들어준 PC에 대해 불신감을 품게 된다. 자기가 이용당하는 것은 아닌지 의심하기 시작하며, 소원을 들어준 PC와 거리를 둔다. 소원을 들어준 PC는 성취자와의 【운명】 수치가 1점 감소한다.`,`성취자는 PC가 들어준 소원을 잃는다. 타락 체크를 해야 한다. 타락 체크에 실패하면 【타락치】가 1점 상승한다. 타락 체크에 성공하면 【타락치】가 1점 감소한다.`,`성취자는 소원을 들어준 PC가 마법사라는 것을 알아차린다. 이후, 그 성취자의 【타락치】가 상승할 때는 상승량이 1점 늘어난다(이 효과는 누적되지 않는다). 이 결과가 마음에 들지 않는다면 PC는 그 성취자로부터 자신에 관한 기억을 지워 이 효과를 무효로 할 수 있다. 이러면 성취자에 대한 PC의 【운명】 수치는 1이 된다.`,`성취자는 갑작스러운 행운에 감사하면서도 여전히 자신의 삶과 싸워나간다. 만약 성취자의 【타락치】 1점 이상이라면 해당 수치가 1점 감소한다.`,`성취자는 믿으면 꿈이 이루어진다고 여기게 되어 조금 긍정적으로 바뀐다. PC는 공적점을 1점 획득한다.`]}}}}},"MagicaLogia.zh_hans":{zh_hans:{MagicaLogia:{special:`大成功(回复1D6点魔力或恢复1种变调)`,elements:{items:[`星`,`兽`,`力`,`歌`,`梦`,`暗`],format:`产生2个%{text}魔素`},skill_table:{items:[[`星`,[`黄金`,`大地`,`森`,`道路`,`海`,`静寂`,`雨`,`岚`,`太阳`,`天空`,`异界`]],[`兽`,[`肉`,`虫`,`花`,`血`,`鳞`,`混沌`,`牙`,`吼叫`,`愤怒`,`翼`,`爱欲`]],[`力`,[`重力`,`风`,`流动`,`水`,`波`,`自由`,`冲击`,`雷`,`炎`,`光`,`圆环`]],[`歌`,[`物语`,`旋律`,`泪`,`离别`,`微笑`,`思念`,`胜利`,`恋`,`热情`,`治愈`,`时间`]],[`梦`,[`追忆`,`谜`,`谎言`,`不安`,`睡眠`,`偶然`,`幻`,`狂气`,`祈祷`,`希望`,`未来`]],[`暗`,[`深渊`,`腐败`,`背叛`,`迷茫`,`怠惰`,`歪曲`,`不幸`,`愚昧`,`恶意`,`绝望`,`死`]]],s_format:`「%{category_name}」《%{skill_name}》`},inveterate_enemy_table:{name:`宿敌表`,type:`1D6`,items:[`嫉妒。这个人物其实是嫉妬调查者实力的《大法典》的魔法使。该人物使用《火刑人》（大判P.174）的数据，但使用魔法时需要消耗魔素，且无法收藏魔法使。GM操作时，请让该人物向调查者或者调查者的锚点发起魔法战，阻碍他们的行动。`,`搜集。这个人物其实是试图收藏调查者的《书籍卿》。该人物使用《混血主义者》（大判P.175）的数据。GM操作时，请让该人物成为《断章》的立会人、或者发起魔法战来阻碍调查者的行动。`,`妨碍。这个人物其实是试图夺走调查者正在追查的《断章》的《书籍卿》。该人物使用《低语的诱惑者》（大判P.174）的数据。GM操作时，请让该人物成为《断章》的立会人、或者发起魔法战来阻碍调查者的行动。`,`断章。这个人物其实被与这次事件无关的《断章》凭依。该人物使用《悦乐》（大判P.173）的数据。GM操作时，请让该人物成为《断章》的立会人、或者发起魔法战来阻碍调查者的行动。`,`黑衣人。这个人物其实是否定魔法、妖怪等一切超常现象的秘密结社「Circle End」的间谍。该人物使用《Circle End》（大判P.177）的数据。GM操作时，请让该人物实行【掩饰行为】、或者发起魔法战来阻碍调查者的行动。`,`忍者。这个人物其实是奉命刺杀你的忍者。该人物使用《忍者》（大判P.177）的数据。GM操作时，请让该人物成为《断章》的立会人、或者发起魔法战来阻碍调查者的行动。`]},conspiracy_table:{name:`谋略表`,type:`1D6`,items:[`炸弹。这个人物的身上其实藏着会使调查者的肉身爆炸的魔法炸弹。公开该【秘密】时，调查者受到1D6的伤害。`,`诅咒。这个人物的身上其实藏着让调查者感染的诅咒魔法。公开该【秘密】时，调查者随机承受一种变调。`,`幽闭。这个人物的身上其实藏着将调查者囚禁至异次元的监狱中的魔法。公开该【秘密】时，扮演调查者的PL直到由自己发起新的场景、或者进入高潮阶段为止，都无法在场景中登场（能否在主持人场景中登场由GM决定）。`,`强化。这个人物的身上其实藏着吸收调查者的命运之力的魔法。公开该【秘密】时，本局游戏中登场的《断章》的凭依深度上升1。上升后的凭依深度最高只能等同于调查者的锚点数量。`,`不幸。这个人物的身上其实藏着让调查者的锚点遭遇不幸的魔法。公开该【秘密】时，调查者从锚点中选择一名愚者，并对这名NPC愚者使用命运转变表。`,`逃脱。这个人物的身上其实藏着协助《断章》逃跑的魔法。公开该【秘密】时，GM选择一本《断章》及一名NPC，让《断章》凭依在NPC身上。此时GM也可以选择已经被魔法使回收的《断章》，然后回复《断章》1D6的魔力。`]},fate_table:{name:`因缘表`,type:`1D6`,items:[`思慕。这个人物其实早就认识并深爱着调查者。调查者对该人物的【命运】值上升2，属性为「恋爱」。在对该人物的【命运】属性为「恋爱」期间，每当调查者对该人物的【命运】值上升1时，回复与【命运】值相等的【魔力】。`,`亲戚。这个人物其实与调查者有血缘关系。调查者对该人物的【命运】值上升2，属性为「血缘」。在对该人物的【命运】属性为「血缘」期间，调查者进行复活判定时，获得与【命运】值相等的向上修正。`,`怨恨。这个人物其实对调查者抱有深深的恨意。调查者对该人物的【命运】值上升2，属性为「宿敌」。在对该人物的【命运】属性为「宿敌」期间，调查者大若失败，减少与【命运】值相等的【魔力】。`,`狂信。这个人物其实崇拜着调查者。调查者对该人物的【命运】值上升2，属性为「支配」。在对该人物的【命运】属性为「支配」期间，调查者向凭依于该人物的《断章》挑起魔法战时，可以自动获得胜利。但是当调查者进行行为判定时，点数如果小于【命运】值则视为大失败。`,`分身。这个人物其实是因魔法而分离的调查者的灵魂碎片。该NPC与调查者融合，调查者获得1个功绩点。`,`无关。这个人物与本次事件无关，但这次相遇真的是无意义的吗？调查者对该人物使用事件表。`]},cueball_table:{name:`奇人表`,type:`1D6`,items:[`寿命。这个人物的命数已尽。公开该【秘密】时，该人物死亡。`,`杀意。这个人物对世间满是憎恨，无差别地伤害他人。循环结束时，GM从持有该【秘密】的人物之外随机选择一名NPC。若被选中的NPC是未被《断章》凭依的“愚者”则当场死亡；如若不是，则持有该【秘密】的人物死亡。不论是何种情况，不希望死亡发生的PC可以从「暗」领域中随机选择特技进行判定，判定若成功可使死亡无效化。`,`强运。这个人物是某种特异点，拥有非同一般的好运气。该NPC被视为战利品，持有该战利品的角色进行任何行为判定都会获得＋1向上修正。调查者获得该战利品。`,`疵痕。这个人物曾经被魔法夺走了宝贵的东西，憎恨着魔法及与魔法有关的人。该人物登场的场景中，召唤和咒文的判定需要附加-2向下修正。`,`善人。这个人物拥有坚强又温柔的心。调查者对该人物的【命运】值上升3。`,`依代。这个人物因灵媒体质容易被凭依。该人物被《断章》凭依时，《断章》的【攻击力】与【防御力】均上升2。公开该【秘密】后，循环结束时GM可以选择一本《断章》，将凭依对象变更为该NPC。但GM无法选择已经被魔法使回收的《断章》。`]},force_field_table:{name:`力场表`,type:`1D6`,items:[`加护。这个人物的头顶总会降落星之恩宠。公开该【秘密】时，该场景内产生2个「星」魔素。并且在本局游戏中，对该人物的【命运】值上升1的角色获得2个「星」魔素。`,`变化。这个人物其实是历经岁月的动物（狐或者狸之类的）幻化而来。公开该【秘密】时，该场景内产生2个「兽」魔素。并且在本局游戏中，对该人物的【命运】值上升1的角色获得2个「兽」魔素。`,`超能力。这个人物的体内其实沉眠着ESP、PK之类的潜在超能力。公开该【秘密】时，该场景内产生2个「力」魔素。并且在本局游戏中，对该人物的【命运】值上升1的角色获得2个「力」魔素。`,`诗人。这个人物是被诗神祝福的存在。公开该【秘密】时，该场景内产生2个「歌」魔素。并且在本局游戏中，对该人物的【命运】值上升1的角色获得2个「歌」魔素。`,`梦想家。这个人物怀有远大理想或想要实现的梦想，尝试干出一番伟业。公开该【秘密】时，该场景内产生2个「梦」魔素。并且在本局游戏中，对该人物的【命运】值上升1的角色获得2个「梦」魔素。`,`暗黑。这个人物背负着被诅咒的命运，可能招致世界毁灭。公开该【秘密】时，该场景内产生2个「暗」魔素。并且在本局游戏中，对该人物的【命运】值上升1的角色获得2个「暗」魔素。`]},alliance_table:{name:`同盟表`,type:`1D6`,items:[`精灵。这个人物其实是改变了姿态、在人界显现的精灵。象征特技是%{skill}。调查者在本局游戏间习得该特技的【精灵召唤】。并且在本局游戏中，有且仅有一次可使该【精灵召唤】自动成功。`,`骑士。这个人物其实是改变了姿态、在人界显现的骑士。象征特技是%{skill}。调查者在本局游戏间习得该特技的【骑士召唤】。并且在本局游戏中，有且仅有一次可使该【骑士召唤】自动成功。`,`魔王。这个人物其实是改变了姿态、在人界显现的魔王。象征特技是%{skill}。调查者在本局游戏间习得该特技的【魔王召唤】。并且在本局游戏中，有且仅有一次可使该【魔王召唤】自动成功。`,`魔法商人。这个人物是贩卖魔法道具的魔法商人。此后，在该人物登场的场景中，可以将自己已经填充的一个魔素交换为另一种魔素。此外，在该人物登场的场景中，可以将自己的一个装备魔法更换为另一种可习得的装备魔法。`,`师父。这个人物是曾经向调查者教授魔法的老师。此后，在该人物登场的场景中，可以将自己习得的一个特技更换为另一种可习得的特技。此外，在该人物登场的场景中，可以将自己的一个咒文魔法更换为另一种可习得的咒文魔法。`,`无垢。这个人物拥有纯洁无瑕的心灵。该NPC被视为战利品。持有该战利品的角色在本局游戏中有且仅有一次机会，可以无需消耗魔素就发动咒文魔法【净化】（大判P.120）并自动成功。`]},tables:{TPT:{name:`时间流逝表`,type:`1D6`,items:[`持续过着被当作目标被他人追逐的生活。最近几年每天都在艰苦的战斗中度过。以%{skill}进行判定。若成功在本局游戏结束后额外获得1个功绩点；若失败发生「命运转变」。`,`在冒险的旅途中，无上的幸福降临了。以%{skill}进行判定。若成功使降临在自身锚点身上的一种灾厄、或者是自己背负的一个创伤无效化。`,`从冥想中醒来，不知不觉已经是这个时间了。得益于冥想，获得了充足的魔素。获得「%{element}」「%{element}」「%{element}」魔素。`,`经过了足以让伤口愈合的漫长时间。可以自由选择将【魔力】回复至最大值、或进行「魔力重置」。`,`在安稳和平的日子里发生了些事件。选择自己的一名锚点，使用「事件表」。`,`每日刻苦钻研，精进魔法修行。如果玩家愿意，可以将藏书栏中的魔法变更为自己可习得的其他魔法。如果将已填充魔素的魔法更改为未习得的，则失去已填充的魔素。`]},ST:{name:`场景表`,type:`2D6`,items:[`用魔法创造出的次元间隙。这里是无关时间与空间的地方，既随处可见、又不属于任何地方。`,`梦境之中。遥远的往事浮现在你眼前。`,`安静的咖啡店内。伴随着咖啡的香气，满溢着温馨平和的气氛。`,`狂风呼啸，云层翻动，远处传来了雷鸣声。看来快要下雨了。`,`无人的小巷。在这里不会被任何人打扰。`,`周围发生了由《断章》引起的魔法灾厄。以%{skill}进行判定。若成功任意获得1个魔素；若失败使用「命运转变表」。`,`行走在夜晚的街道上，远处能看到温暖的万家灯火。`,`合上正在阅读的书籍。书中记载了许多你想要知晓的事情。原来如此，是这么一回事啊。`,`熙熙攘攘的人群中，谁都不会在意。`,`城市遥远的上空。挣脱了重力的你在空中自由飞翔。`,`未来的预感。眼前浮现了可能会发生的事情。`]},FT:{name:`大失败表`,type:`1D6`,items:[`魔法灾厄降临在你的锚点身上。发生「命运转变」。`,`魔法灾厄夺走了你的魔素。从已填充的魔素当中自行选择，共减少2个魔素。`,`魔法脱离控制。【魔力】减少1。`,`发生了魔法灾厄，直到本循环结束为止，行为判定附加-1向下修正。`,`魔法灾厄直接降临在了你身上。使用变调表，并承受变调。`,`啊，好险呀。幸好什么也没发生。`]},WT:{name:`变调表`,type:`1D6`,items:[`『封印』随机选择一个自己的魔法（装备魔法除外），并在魔法的确认栏内打上勾。使用该魔法时必须消耗2点【魔力】。`,`『破绽』在魔法战期间，每回合结束时自己的【魔力】减少1。`,`『虚弱』【攻击力】下降1。`,`『病魔』【防御力】下降1。`,`『遮蔽』【根源力】下降1。`,`『不幸』在%{skill}的确认栏内打上勾。此后无法使用该特技，并且当该特技所属领域内的特技成为指定特技时，判定附加-1向下修正。`]},FCT:{name:`命运转变表`,type:`1D6`,items:[`『挫折』这个角色放弃了自身重要的梦想。`,`『离别』这个角色失去了重要之人——亲友、恋人、父母或者兄弟姐妹等。`,`『大病』这个角色患上了不治之症。`,`『欠债』这个角色被坏人利用，背负上巨额债务。`,`『不和』这个角色因为人际关系的不顺利，心灵遭到重创。`,`『事故』这个角色遇到交通事故，受了无法治愈的伤。`]},AT:{name:`事件表`,type:`2D6`,items:[`意外的礼物、出色的主意、恶魔般的交易……你可以任意获得1个【魔素】、或者回复1D6【魔力】。不论如何选择，对该人物的【命运】值上升1。【命运】属性可由GM自由决定。`,`崇高的牺牲、真挚的念想、压倒性的实力……对该人物的【命运】值上升1。【命运】属性为「尊敬」。`,`些许口角争吵、互相扭打斗殴、进行魔法战……双方均掷1D6，点数低的一方对点数高的一方的【命运】值上升1。【命运】属性可由点数高的一方自由决定。`,`背叛、阴谋、不幸的误解……对该人物的【命运】值上升1。【命运】属性为「宿敌」。`,`不经意的感谢、绝境之中的救赎、实现毕生夙愿……对该人物的【命运】值上升1。【命运】属性为「支配」。`,`行走的僵尸群、地狱的业火、迷宫化……以%{skill}进行判定。若成功任意获得1个魔素；若失败对该人物使用「命运转变表」。`,`街道的转角处、便利店、从天空落下……偶然的相遇。对该人物的【命运】值上升1。【命运】属性为「兴趣」。`,`灵魂闪光的瞬间、爱的告白、可疑的拥抱……对该人物的【命运】值上升1。【命运】属性为「恋爱」。`,`师徒、恋人、错过的彼此……窥见了与这个人物的未来一角。彼此的【命运】值上升1。`,`令人怀念的表情、重要的回忆、成为伴侣的预感……对该人物的【命运】值上升1。【命运】属性为「血缘」。`,`献身的看护、魔法的祝福、奇迹……对该人物的【命运】值上升1。【命运】属性可自由决定。如果关系栏中有创伤，可以从关系栏中消去一个创伤。`]},BGT:{name:`经历表`,type:`1D6`,items:[`书警／Bookwatch`,`司书／Librian`,`书工／Artisan`,`访问者／Guest`,`异端者／Outsider`,`外典／Apocrypha`]},DAT:{name:`初期锚点表`,type:`2D6`,items:[`『恩人』在你困难之时，得到了锚点的相助。`,`『寄居』你与锚点其中一方住在另一方的家中或者另一方经营的公寓里。`,`『酒友』你与锚点是酒友。`,`『常客』你与锚点其中一方经常去另一方工作的地方。`,`『同好』你与锚点是有着共同兴趣爱好的同好。`,`『邻居』你住在锚点附近。`,`『同辈』你与锚点在同一个地方工作、或者是同一个学校的。`,`『笔油』你与锚点通过书信或邮件交换意见。`,`『旧友』你与锚点以前就有深交。`,`『庇护』你秘密地守护着锚点。`,`『情人』你与锚点有肉体关系。`]},FAT:{name:`命运属性表`,type:`1D6`,items:[`『血缘』自己或者自己所爱之人的家属亲戚。`,`『支配』命中注定要成为你的部下。`,`『宿敌』以某种方式相互战斗、相互竞争的不共戴天之敌。`,`『恋爱』被夺走了心，对其抱有强烈的感情。`,`『兴趣』非常稀少、难以理解的的存在。想要研究或者观察的对象。`,`『尊敬』对这个人物的才能、思想、态度抱有敬畏或尊重。`]},WIT:{name:`愿望表`,type:`1D6`,items:[`希望拯救自己以外的某个特定的人。`,`希望见到自己重要的人或者憧憬的人。`,`希望消去缠绕着自己的不幸。`,`希望取回自己失去的某样东西。`,`希望惩罚某个特定的人。`,`希望满足自己的欲望（财欲、名欲、肉欲、求知欲等）。`]},TCT:{name:`命运转变「典型性灾厄」`,type:`1D6`,items:[`挫折。这个角色放弃了自身重要的梦想。`,`离别。这个角色失去了重要之人——亲友、恋人、父母或者兄弟姐妹等。`,`大病。这个角色患上了不治之症。`,`欠债。这个角色被坏人利用，背负上巨额债务。`,`不和。这个角色因为人际关系的不顺利，心灵遭到重创。`,`事故。这个角色遇到交通事故，受了无法治愈的伤。`]},PCT:{name:`命运转变「物理性灾厄」`,type:`1D6`,items:[`火灾。自己的家被烧毁，无家可归。`,`盗窃。自己重要的东西被盗走后丢失了。`,`灾害。遭遇自然灾害，生活环境发生突变。`,`失明。双眼无法看见。`,`诱拐。被某人绑架并监禁。`,`伤害。被路过的歹徒或者憎恨你的人所伤。`]},MCT:{name:`命运转变「精神性灾厄」`,type:`1D6`,items:[`倦怠。被疲劳感侵袭，做什么都提不起劲。`,`出走。对自己现在所处的地方没有安心感，离开后失踪。`,`憎恶。对身边的某人或者PC抱有强烈的憎恶感。`,`不眠。无法入睡，感到疲劳。`,`谎言。变得无法说出真话。`,`记忆丧失。忘记朋友或者PC。`]},ICT:{name:`命运转变「狂气性灾厄」`,type:`1D6`,items:[`双重人格。出现了另一种人格并开始擅自行动。`,`恐惧。患上对高处、异性、或者蜘蛛等某种特定事物的恐惧症。`,`妄想。脑中总是浮现离奇的妄想。`,`偏爱。对某种特定东西或情况显示出异常狂热的偏爱。`,`暴走。偶尔无法控制自身情绪，变得凶暴。`,`发情。体温上升、心跳加快、进入性兴奋状态。`]},SCT:{name:`命运转变「社会性灾厄」`,type:`1D6`,items:[`逮捕。因冤罪被逮捕拘留。`,`背叛。被信赖之人欺骗，或者恋人出轨。`,`暴露。自己想要隐藏的秘密暴露了。`,`笼络。被明显有问题的可疑之人夺走了心。`,`加害。伤害他人、甚至杀人。`,`忙碌。被巨大的工作量追赶着，身心俱疲。`]},XCT:{name:`命运转变「超自然灾厄」`,type:`1D6`,items:[`通灵。变得能够看到本应无法看见的东西。`,`不幸。身边频繁发生不幸的偶然事件。`,`感染。渐渐变成吸血鬼、僵尸之类的怪物。`,`阻碍。只有魔法性存在才能看到自己。`,`变身。外表变为动物或者其他人。`,`靶子。容易吸引杀人狂、魔法灾厄等。`]},WCT:{name:`命运转变「不可思议的灾厄」`,type:`1D6`,items:[`中二病。总是不自觉地做出中二的言行举止。`,`冒失。经常平地摔、弄坏东西，频率高到匪夷所思。`,`路痴。缺乏方向感，迷路到令人难以置信。`,`奇怪的句尾词。不知为何，自己说话时会加上奇怪的句尾词。`,`平假名。说出来的话全部变成了日语平假名。`,`病娇。病态般地爱慕着PC，对自己以外的对PC抱有好感的人持攻击性态度。`]},CCT:{name:`命运转变「喜剧性灾厄」`,type:`1D6`,items:[`性转。自身的肉体性别反转。`,`猫耳。头顶上长出了猫耳。`,`发胖。胖到令人惊讶。`,`脚臭。脚臭到令人心生怜悯。`,`饥饿。一顿不吃二十多碗饭就会饿到无法动弹。`,`脱衣。当场脱光所有衣服。`]},BST:{name:`空白秘密表`},PT:{name:`战利品表`,type:`2D6`,items:[`败者的躯体从内部开始破裂、四处散落。获得1点【功绩点】。`,`败者变为无数的虫子与小动物，成为胜者的使魔。胜者任意选择一个魂之特技以外的特技，在本局游戏期间，从【精灵召唤】【魔剑召唤】【噩梦召唤】中选择一种，习得以该特技为指定特技的召唤。`,`伴随着爆炸声，败者不知消失到何方，周围只剩下硫磺般的味道。胜者在本局游戏期间，有且仅有一次机会在任意时点回复一种「变调」。`,`败者变成了几枚形状奇怪的金币。胜者获得与击败的对手的Rank数相等的魔货。`,`败者被从地面突然涌现的无数只手拽住，向胜者送上称赞的同时道出了重要的事情。选择一个已公开的概要，公开对应的【秘密】。`,`败者化为无数颗光粒，可以从中获得魔素。胜者任意获得2个魔素（也可让渡给见证人）。`,`败者化为凌乱的纸张散落地面，可以从中获得未知的力量。胜者获得2点【临时魔力】。`,`败者化身为奇妙的音乐，曲子沁人心脾。胜者获得与打倒的对手的Rank数相等的魔货。`,`败者变成一朵花。胜者在本局游戏期间，有且仅有一次机会可以重掷自己的行为判定骰。`,`败者化为支离破碎的言语，胜者从中读取了未来的命运。胜者使用「事件表」，并记录结果。之后，在本局游戏的剧情场景中，有且仅有一次机会可以对同一场景中登场的一名角色使用前述事件表的结果。`,`败者化为暗影，在灼烧下变为异境的入口。胜者任意选择一个异境，可以在本局游戏期间移动至该异境。`]},XEST:{name:`极限环境场景表`,type:`2D6`,items:[`无法分辨上下左右，陷入一片黑暗中。由一名在该场景中登场的PC用《光》进行判定。若成功，获得2个暗魔素；若失败，承受｢遮断｣变调。不论成功与否，只要有人进行判定后，该场景效果即失效。`,`出现在眼前的是一片业火之海，带着要吞噬一切的压倒性的敌意。以《炎》进行判定。若失败，【魔力】减少2。`,`极端的天气让地形发生剧烈变化，方才的光景如假象般一下子就被改变了。以《岚》进行判定。若失败，【魔力】减少1。`,`看不到尽头的沙漠。飞舞的沙尘让人无法睁开双眼。以《大地》进行判定。若失败，承受｢封印｣变调。`,`寒冷到连说出的话都好像会凝结成冰，完全感觉不到生命的气息。【魔力】减少1。`,`你们被残酷的自然环境逼入绝境。以%{skill}进行判定。若成功，好不容易找到了姑且能派上用场的东西，任意获得1个魔素；若失败，你受的伤跨越时间与空间，为你的锚点带去不幸，发生「命运转变」。`,`在一片满覆积雪的原野上，散落着一些残留的脚印。看来已经有人捷足先登了。`,`站在陡峭的悬崖上。眼底是宽广的大海，上空传来海鸟的叫声。`,`强重力之地，全身仿佛被灌满了铅。以《重力》进行判定。若失败，【魔力】减少1。`,`深邃的水底。被蓝色覆盖的空间中似乎漂着什么东西。可以允许一名在该场景中登场的PC用《海》进行判定。若成功，获得3个星魔素；若失败，【魔力】减少2。不论成功与否，只要有人进行判定后，该场景效果即失效。`,`振聋发聩般的轰鸣声。看来用言语与对方沟通是没指望了。以《旋律》进行判定。若失败，从已填充的魔素当中自行选择，共减少2个魔素。`]},IWST:{name:`内心世界场景表`,type:`2D6`,items:[`这里满是裸露的肌肤与湿热的吐息，无数男男女女正肆意放纵肉欲。可以允许一名在该场景中登场的PC用《爱欲》进行判定。若成功，获得1点【临时魔力】；若失败，【魔力】减少2。不论成功与否，只要有人进行判定后，该场景效果即失效。`,`房间的一面墙壁上密密麻麻地爬满了黑色的虫子，能听到翅膀煽动的声音。这个精神世界的主人到底是喜欢虫子，还是讨厌虫子呢？可以允许一名在该场景中登场的PC用《虫》进行判定。若成功，在本局游戏期间，元型「虫之骑士」将成为同伴。身为同伴的元型直到被破坏或者消灭为止，进行该判定的角色在任何场景中登场时都会被一同召唤。若失败，所有虫子一同扑面飞来，在该场景中登场的所有PC的【魔力】全部减1。不论成功与否，只要有人进行判定后，该场景效果即失效。`,`空无一人的教室。可不知为何好像能听到从哪儿传来悄悄的议论的声音，也能感觉到盯着自己的视线。可以允许一名在该场景中登场的PC用《不安》进行判定。若成功，选择一个已公开的概要，公开对应的【秘密】；若失败，承受｢遮断｣变调。不论成功与否，只要有人进行判定后，该场景效果即失效。`,`昏暗但温暖的十分安宁的空间，就好像身处母亲的子宫中。在该场景中登场的PC如果消耗魔素来回复【魔力】，每消耗1个魔素可以回复2点【魔力】。`,`游乐园。热闹的游行队伍从眼前经过，却没有一名游客。`,`夜路。模糊的黑影在身后追赶着你。明明无法看清样子，却让人觉得异常恐惧。在该场景中登场的PC以%{skill}进行判定。若成功，任意获得2个魔素；若失败，模糊的黑影会出现在你的锚点身前，发生「命运转变」。`,`夕阳下的街道。总觉得有些寂寞。`,`地板、墙壁、甚至连天花板都沾染上暗红色，房间里充斥着腥臭味。可以允许一名在该场景中登场的PC用《血》进行判定。若成功，获得2点【临时魔力】；若失败，【魔力】减少1。不论成功与否，只要有人进行判定后，该场景效果即失效。`,`在不知开往何方的列车中，除了你以外似乎没有其他乘客……可以允许一名在该场景中登场的PC用《异界》进行判定。若成功，将发现可以通往任意一个异境的魔法门；若失败，在该场景中登场的所有PC的【魔力】全部减2。不论成功与否，只要有人进行判定后，该场景效果即失效。`,`熙熙攘攘的来往人群中，谁也不会在意你。在该场景中可以无视「不干涉」这条世界法则，对任意角色进行调查。`,`不知是何处的空间，你最爱的人出现在眼前。可以允许一名在该场景中登场的PC用《热情》进行判定。若成功，可以对任意一个锚点的【命运】值上升1；若失败，发生「命运转变」。不论成功与否，只要有人进行判定后，该场景效果即失效。`]},MCST:{name:`魔法都市场景表`,type:`2D6`,items:[`突然发生了爆炸，似乎是谁在做实验时失败了。承受「破绽」变调后，获得2个「力」魔素。`,`陈列标本的地下室，由实验造出的魔法生物被塞在瓶子里罗列着。`,`杂乱的市场。不仅有各种各样的食材与日用品，也贩卖幻兽的眼睛、曼陀罗根等魔法媒介。在该场景中登场的PC，每人各有一次机会消耗1点功绩点来换取2个魔素。`,`聚集着魔法使的沙龙，在这里能获得有用的情报吧。可以允许一名在该场景中登场的PC用《物语》进行判定。若成功，选择一个已公开的概要，公开对应的【秘密】；若失败，承受｢封印｣变调。不论成功与否，只要有人进行判定后，该场景效果即失效。`,`大道。时不时就有幻兽牵引的马车、绒毯和扫帚之类的可以飞上天空的乘坐工具经过，一片繁忙景象。`,`广场。魔法使之间的争吵导致各种魔法乱飞。在该场景中登场的PC以%{skill}进行判定。若成功，任意获得2个魔素；若失败，现场的魔法将跨越时空对锚点造成影响，发生「命运转变」。`,`热闹的酒吧，顾客中能看到很多妖精和魔物的身影。在该场景中登场的PC【魔力】回复1。`,`弯弯绕绕的小巷里，遭遇了由奇妙的异种族组成的盗贼团的袭击。以《雷》进行判定。若失败，【魔力】减少2，或者消耗2个已经填充的魔素。请自由选择失败的后果。`,`都市大门。为寻求新知识前来的人、动身回归自己世界的人……来自各个世界的各种各样的人们在此来来往往。`,`欢乐街。头顶长角背后有尾、拥有双翼裸露着肌肤的美女们正妖艳地送秋波。可以允许一名在该场景中登场的PC用《爱欲》进行判定。若成功，在本局游戏期间，元型「爱欲之乙女」将成为同伴。身为同伴的元型直到被破坏或者消灭为止，进行该判定的角色在任何场景中登场时都会被一同召唤。若失败，【魔力】减1。不论成功与否，只要有人进行判定后，该场景效果即失效。`,`斗技场。魔法使们让经过强化的元型和幻兽互相厮杀。发起该场景的PC拥有一次向基本规则书中记载的Rank4以下的〈书籍卿〉或〈越境者〉挑起魔法战的机会。若胜利，可以使用「战利品表」。`]},WDST:{name:`死后世界场景表`,type:`2D6`,items:[`寂落的村庄，偶尔有影子一般的人们路过。在这里，可以见到已经死去的角色。在该场景登场的PC中，有且仅有一人可以克服一个创伤。`,`一望无际的花田，充满着恬静的氛围。`,`法院。态度强硬的法官对大群死者一个接一个地下达判决。以《谎言》进行判定。若失败，【魔力】减少2。`,`被白色光芒包围的食堂，不间断地提供丰盛的料理与美酒。可以允许一名在该场景中登场的PC用《肉》进行判定。若成功，获得1点【临时魔力】；若失败，承受｢病魔｣变调。不论成功与否，只要有人进行判定后，该场景效果即失效。`,`在这里，地面化为白云，透过云层间隙好像可以看到现世的景象。以%{skill}进行判定。若成功，在本次跑团期间有且仅有一次机会重掷判定骰；若失败，锚点跨越时空看到了死后世界，发生｢命运转变｣。`,`宽阔河流的岸边。对岸就是现世吗？可以允许一名在该场景中登场的PC用《圆环》进行判定。若成功，可以重置魔力。不论成功与否，只要有人进行判定后，该场景效果即失效。`,`教堂。死后依旧不断祈祷的灵魂正沉默地跪着。可以允许一名在该场景中登场的PC用《祈祷》进行判定。若成功，获得2点【临时魔力】；若失败，承受｢不幸｣变调。不论成功与否，只要有人进行判定后，该场景效果即失效。`,`十分普通的住宅区，是重复着日常生活的灵魂们聚集的地方。`,`拷问所。鬼厉们让死者尝到无尽的痛苦。可以允许一名在该场景中登场的PC用《绝望》进行判定。若成功，获得2点【临时魔力】；若失败，承受｢破绽｣变调。不论成功与否，只要有人进行判定后，该场景效果即失效。`,`战场。戴着羽翼头盔的少女率领着战士们，与巨人不断征战。可以允许一名在该场景中登场的PC用《天空》进行判定。若成功，获得3点【临时魔力】；若失败，减少3点【魔力】。不论成功与否，只要有人进行判定后，该场景效果即失效。`,`不知是何处的空间，你最爱的人出现在眼前。可以允许一名在该场景中登场的PC用《热情》进行判定。若成功，可以对任意一个锚点的【命运】值上升1；若失败，发生「命运转变」。不论成功与否，只要有人进行判定后，该场景效果即失效。`]},LWST:{name:`迷宫世界场景表`,type:`2D6`,items:[`空旷的石制房间，画在地板上的魔法阵散发着诡异的光芒。可以允许一名在该场景中登场的PC用《异界》进行判定。若成功，可以将那个魔法阵作为返回地球的魔法门来使用；若失败，被从魔法门中涌现的怪物袭击，该场景中登场的所有PC减少1D6【魔力】。不论成功与否，只要有人进行判定后，该场景效果即失效。`,`被油灯微弱的灯光照亮的监狱，牢笼中散落着朽烂的骸骨。可以允许一名在该场景中登场的PC用《死》进行判定。若成功，选择一个已公开的概要，公开对应的【秘密】；若失败，尸体吐露诅咒的话语，该场景中登场的所有PC承受｢破绽｣变调。不论成功与否，只要有人进行判定后，该场景效果即失效。`,`道路的前方有一扇门与看板，看板上写着“旅馆”。在该场景中登场的所有PC有且仅有一次机会，可以消耗1点功绩点来进行一次调律。`,`狭窄到只容许一人通过的道路向前延伸，这条长廊的尽头到底在哪呢？`,`穿过好几扇门走过好几个岔道。咦？不知何时你居然迷路了。发起该场景的PC以外的其他PC若要登场，必须以《道路》进行判定。判定失败的PC无法在该场景中登场。`,`突然出现的怪物袭击了你们。该场景中登场的所有PC以%{skill}进行判定。若成功，则打倒怪物并任意获得1个魔素；若失败，你受的伤跨越时间与空间，为你的锚点带去不幸，发生「命运转变」。`,`眼前是一整排相似的门扉，要打开那一扇门呢？`,`黑暗中传来了低鸣，附近似乎潜藏着怪物。不知能否顺利通过呢……以《静寂》进行判定。若失败，【魔力】减少1。`,`前方无路可走，只有深邃的峡谷。亮光无法照到谷底，仿佛峡谷能一直通往地心深处。获得1个「暗」魔素。`,`金银财宝、宝石王冠，房间里堆满了山一般高的宝物，却不见守卫的踪影……可以允许一名在该场景中登场的PC用《黄金》进行判定。若成功，获得1D6的魔货或者3个随机魔素；若失败，在该场景中登场的所有PC的【魔力】减少1。不论成功与否，只要有人进行判定后，该场景效果即失效。`,`道路尽头的墙壁上排列着乍看之下不明所以的文字。如果想要继续前进，就必须解开这些文字谜题。可以允许一名在该场景中登场的PC用《谜》进行判定。若成功，选择一个已公开的概要，公开对应的【秘密】；若失败，暗藏在房间内的陷阱将启动，强制结束本次场景。不论成功与否，只要有人进行判定后，该场景效果即失效。`]},STB:{name:`大判场景表`,type:`2D6`,items:[`这里是与原本所在之处完全不同的地方。只有这短暂的一瞬间，来到了一个充满着魔法之力的异境。场景中产生1个「星」魔素。`,`梦境之中。遥远的往事浮现在你眼前。场景中产生1个「梦」魔素。`,`狂风呼啸，云层翻动，远处传来了雷鸣声。场景中产生1个「力」魔素。`,`安静的咖啡店内。伴随着咖啡的香气，满溢着温馨平和的气氛。`,`无人的小巷。在这里不会被任何人打扰。`,`周围发生了由《断章》引起的魔法灾厄。以%{skill}进行判定。若成功任意获得1个魔素；若失败使用「命运转变表」。`,`平淡无奇的平静景象。但在日常的表象下，似乎能感觉到魔法灾厄的气息。`,`合上正在阅读的书籍。书中记载了许多你想要知晓的事情。原来如此，是这么一回事啊。`,`行走在夜晚的街道上，远处能看到温暖的万家灯火。场景中产生1个「歌」魔素。`,`聚满人群的热闹广场，是不是正在举行什么庆祝活动呢？听到了呼唤某人的声音。场景中产生1个「兽」魔素。`,`悲剧的预感。家人的不幸、亲友的绝望、同伴之死……幻觉之中看到了将来可能会发生的事情。场景中产生1个「暗」魔素。`]},MGCT:{name:`命运转变「魔法使的灾厄」`,type:`1D6`,items:[`厌恶。厌恶〈愚者〉，开始对〈大法典〉的做法抱有疑问。该不幸发生两次后，这个魔法使不会死亡但会变为NPC〈书籍卿〉。若该不幸降临在〈书籍卿〉身上，则没有效果。`,`邪恶。与魔法相关的强烈愿望或者邪恶的欲望持续膨胀。该不幸发生两次后，这个魔法使在死后会变为NPC〈禁书〉。`,`幽灵。肉体几乎完全丧失，只留下灵魂。该不幸发生两次后，这个魔法使直接消亡（不是死亡，因而无法进行复活判定）。`,`连锁。发生「命运转变」。即使该不幸发生两次，这个魔法使也不会死亡。`,`变调。随机承受一种变调。即使该不幸发生两次，这个魔法使也不会死亡。`,`消耗。【魔力】减少1。即使该不幸发生两次，这个魔法使也不会死亡。`]},MBST:{name:`魔法书架场景表`,type:`2D6`,items:[`获得了进入《禁书》保管库的许可。四周重重展开的结界、眼神锐利的书警们都异常显眼。可就趁着一瞬间的不注意，《禁书》居然偷袭了你们！必须从该场景登场的PC中选出一人，以《%{force}》进行判定。若失败，【魔力】减少3；若成功，【临时魔力】增加3。不论成功与否，只要有人进行判定后，该场景效果即失效。`,`私室。虽然有些狭窄，但是最能让人安下心来的地方。在该场景登场的PC中，有且只有一人可以将【魔力】回满至上限。`,`镇上的图书馆。不知何时回到了人界。在该场景登场的PC中，有且只有一人可以任意选择一个角色，对其使用「事件表」。`,`摆放着巨大圆桌的房间。看来这里应该是会议厅。`,`长长的走廊。身穿学院制服的少年少女们嬉笑着跑过。`,`荒废的房间中，倒落的空书架格外显眼。这是〈大破坏〉的影响吗……在该场景中登场的PC以%{skill}进行判定。若失败，将跨越时空对锚点造成影响，发生「命运转变」。`,`仓库。未整理的书籍堆积成山，司书们忙着分类整理。`,`迷路来到了某人的研究室内，对堆积的魔导书很感兴趣。`,`从地板直到高耸的天花板，书架上全都摆满了书籍。这些全部都是收藏于这座书库的魔导书。在该场景登场的PC中，有且只有一人获得1点【临时魔力】。`,`魔导书的阅览室。几名魔法使正专心致志地阅读着魔导书。可以允许一名在该场景中登场的PC用%{skill}进行判定。若成功，可以将已习得的魔法更换为另一个可以习得的魔法；若失败，承受｢封印｣变调。不论成功与否，只要有人进行判定后，该场景效果即失效。`,`书架与书架之间突然出现了一扇门。这扇连接异界的大门，到底会通向何方呢？掷异界场景表，并使结果生效。`]},MAST:{name:`魔法学院场景表`,type:`2D6`,items:[`一条美丽的黑龙出现在眼前，是学院的扎那尔帕托斯院长。他似乎想告诉你们什么。`,`突然被什么东西袭击！似乎是有学生召唤元型时失败了。在该场景登场的PC中选出一人，以《%{force}》进行判定。若失败，【魔力】减少3；若成功，【临时魔力】增加3。不论成功与否，只要有人进行判定后，该场景效果即失效。`,`这里是女生宿舍？有男性PC在该场景登场时，男性PC以《%{beast}》进行判定。若失败，承受｢封印｣变调。`,`宿舍走廊。“请问您是哪位？”叫住你的是宿管西格莉特。在该场景登场的PC以《自由》进行判定。若失败，在该场景中进行的所有判定都附加-1向下修正。`,`有着高耸天花板的走廊。从厚实的门扉背后传来些许老师授课的声音。`,`打开门后看到的是你熟识之人，好像不小心误闯学院了。以%{skill}进行判定。若失败，发生「命运转变」。`,`不小心迷路闯进了某人建造的秘密小屋。在学院不太能吃到的糖果像小山一样堆满了房间。`,`位于学院西部的阿尔丁森林，听到了鸟啼声。`,`正在上课的教室。讲师呼唤出的元型朝这边飞来！在该场景登场的PC中选出一人，以%{skill}进行判定。若失败，【魔力】减少1；若成功，可以召唤该特技的精灵。不论成功与否，只要有人进行判定后，该场景效果即失效。`,`学生央求你施展魔法给大家看看。在该场景登场的PC中选出一人，以《%{dream}》进行判定。若失败，承受「不幸」变调；若成功，获得2个「梦」魔素。不论成功与否，只要有人进行判定后，该场景效果即失效。`,`自习室。学生们绞尽脑汁尝试读懂魔导书。在该场景登场的PC中选出一人，以《%{star}》进行判定。若成功，任意获得2个魔素。不论成功与否，只要有人进行判定后，该场景效果即失效。`]},TCST:{name:`克雷德塔场景表`,type:`2D6`,items:[`一位少女出现在你的眼前。她是睡美人的领袖拉托乌娜。本应持续沉眠的她现身于此，到底想要告诉你些什么呢？`,`陷⼊狂⽓的睡美⼈突然袭来！在该场景登场的PC中选出一人，以《%{force}》进行判定。若失败，【魔力】减少3；若成功，【临时魔力】增加3。不论成功与否，只要有人进行判定后，该场景效果即失效。`,`向你搭话的天涯预言家告知了不幸的未来。在该场景登场的PC中选出一人，以《%{dream}》进行判定。若失败，【魔力】减少1；若成功，获得1个「梦」魔素。不论成功与否，只要有人进行判定后，该场景效果即失效。`,`塔的内侧墙壁上陈列着无数的魔导书，或许能从这些书籍中获取到什么线索吧。在该场景登场的PC中，有且仅有一人获得1点【临时魔力】。`,`狭小的客厅中正举行着与《大法典》派来的使者的会议。天涯或许正在向来者传达新的预言。`,`不应在这里的人突然出现在你眼前，似乎是误入了睡美人的梦境之中。以%{skill}进行判定。若失败，发生「命运转变」。`,`塔的上方。连绵的山脉与浮在上方的月亮正静静地注视着克雷德塔。`,`站在塔的外壁的螺旋楼梯上，被强风吹打着。`,`通往克雷德塔的险峻山路，似乎潜伏着什么……获得1个「兽」魔素。`,`幻梦殿中。听着睡美人们安详的呼吸声，你也有点困了。`,`眼前突然出现了一扇门。这扇连接异界的大门，到底会通向何方呢？掷异界场景表，并使结果生效。`]},PWST:{name:`平行世界场景表`,type:`2D6`,items:[`咖啡店的桌子上，FM收音机正在播放本应去年解散的乐队在前几日刚发布的新曲。在该场景登场的PC中，有且只有一人掷「时间流逝表」，并使结果生效。`,`热闹的街道。迎面走来一个与你长相完全相同的人，那就是这个世界的你自己吗？在该场景登场的PC中选出一人，以%{skill}进行判定。若成功，任意获得2个魔素；若失败，承受「病魔」变调。不论成功与否，只要有人进行判定后，该场景效果即失效。`,`行走在夜晚的街道上。明明应该是分外熟悉的风景，却总觉得有什么不一样的违和感。`,`顾客盈门的商业街。有些本已倒闭的的店铺依旧健在，而有些本该生意兴旺的店铺却反而倒闭了。`,`闹市。高楼上的大荧幕正在播报新闻，内容是关于你不知道的国家间的战争。`,`有缘之人的家门前。你不认识的人从大门走出，正以一种怀疑的眼神打量着你。这个人难道是……？以%{skill}进行判定。若失败，发生「命运转变」。`,`没有乘客的列车中。有时会在到站播报中听到不认识的站名。`,`车站前的环形交叉口，放学回家的学生们尤为醒目。那个学校的校服上的领结，真的是红色的吗？`,`站在洋房前。这里应该没有这种建筑才对。`,`经过小学门口。透过音乐教室的窗户，你看到了不认识的音乐家的肖像照。以《%{poem}》进行判定。若失败，承受「封印」变调。`,`眼前正发生着你曾经经历过的事情。而对于这个世界来说，这是正要发生的事情。在该场景登场的PC中，有且只有一人在该场景中的判定获得＋1向上修正。`]},PAST:{name:`终末世界场景表`,type:`2D6`,items:[`夜晚。为避雨踏入某个寺院之中，在这里感觉不到危险的气息，应该能好好休息一下吧。时间在静静地流逝。`,`夜晚。在杂草丛生长满爬山虎的无人山村中，遭遇前来袭击的食肉野兽。必须从该场景登场的PC中选出一人，以《牙》进行判定。若失败，【魔力】减少2。不论成功与否，只要有人进行判定后，该场景效果即失效。`,`夜晚。经历大规模爆炸后被夷为平地的战场遗迹，不知是哪国的国旗在夜风吹过时发出哗啦啦的声音。被一只虚凭袭击并进行魔法战。该魔法战在本局游戏中只会发生一次。`,`夜晚。已经化为废墟满是尘埃的城市之中，虚凭正在袭击愚者。可以允许一名在该场景中登场的PC用%{skill}进行判定。若成功，可救下愚者并对其【命运】上升1，属性可自由决定；若失败，【魔力】减少3。`,`夜晚。被一群虚凭包围。发起该场景的PC以《恶意》进行判定。若失败，在该场景中进行的所有判定都附加-2向下修正。`,`黎明。灰色的荒野上只有一条笔直的高速公路向远方延伸，安静到恐怖的环境中甚至能听见自己的心跳声。被一只虚凭袭击并进行魔法战，前两回合为夜晚，之后的回合作为白昼处理。该魔法战在本局游戏中只会发生一次。`,`白昼。愚者的孩子将历史遗迹当作游玩地独自玩耍着。这个孩子的未来会是什么样的呢。`,`白昼。在世界大战中坠落的战斗机大半被砂砾埋没，但引擎还没有完全损毁。可以允许一名在该场景中登场的PC用《风》进行判定。若成功，进行魔力重置。不论成功与否，只要有人进行判定后，该场景效果即失效。`,`白昼。建有成群宽阔建筑的美丽海岸。这里曾经是旅游度假村，现在却只覆着大量白色遗骨，不停被潮水冲刷。可以允许一名在该场景中登场的PC用《离别》进行判定。若成功，随机获得3个魔素。不论成功与否，只要有人进行判定后，该场景效果即失效。`,`白昼。在崩毁的农村的边缘一角，发现了美味的果实。以《大地》进行判定。若成功，【魔力】回复2。`,`黄昏。锈迹斑斑的铁轨周围满是凌乱的骷髅。被一只虚凭袭击并进行魔法战，前两回合为白昼，之后的回合作为夜晚处理。该魔法战在本局游戏中只会发生一次。`]},GBST:{name:`异世界酒吧场景表`,type:`2D6`,items:[`被酒吧老板雷神缠上了。在该场景登场的PC中选出一人，以雷神为对象掷「事件表」。`,`在闪耀着的神圣光辉之中，威严的神明降临于此，瞬间支配了整个空间的气氛。在该场景中，增加「调查阻碍」这条「世界法则」。`,`本想上楼，却发现一只奇美拉盘踞在楼梯上。在该场景登场的PC中选出一人，以《炎》进行判定。若失败，【魔力】减少1，并重复进行判定直至成功为止。该效果只发生一次。`,`“干杯！”一不注意就把盛满的酒喝光了，而且似乎是度数很高的蒸馏酒。可以允许一名在该场景中登场的PC以《水》进行判定。若成功，获得1个魔货。不论成功与否，该效果只发生一次。`,`干杯声、喝醉后的笑声、各个酒桌上大声交谈的声音……就跟随处可见的酒吧一样。`,`被一位客人强迫灌下烈酒。以%{skill}进行判定。若失败，发生「命运转变」。`,`正踩着楼梯上楼。已经不记得到底是什么时候开始爬楼梯的了，这长长的楼梯到底何时才是尽头？`,`明明是在屋子里，却突然雷云密布狂风四起。神明们正在吵架！在该场景登场的PC中选出一人，以《岚》进行判定。若失败，【魔力】减少2。不论成功与否，该效果只发生一次。`,`门扉前有妖怪阻拦着，不让你通过。“想要通过就交出东西！”妖怪叫喊着向你勒索。在该场景登场的PC中选出一人，任意减少1个魔素。如果没有可以减少的魔素，则【魔力】减少1。`,`本想上楼，却发现一头龙盘踞在楼梯上。在该场景登场的PC中选出一人，以《牙》进行判定。若失败，承受「破绽」变调。不论成功与否，该效果只发生一次。`,`美丽的女神正在窥视镜子。这似乎是能够映照出命运的镜子。可以允许一名在该场景中登场的PC用《未来》进行判定。若成功，自由选择与一名锚点的【命运】上升1。不论成功与否，该效果只发生一次。`]},SLST:{name:`星影场景表`,type:`2D6`,items:[`被列车长告知你持有的是无效「车票」，感觉到了其他乘客注视你的视线。必须从该场景登场的PC中选出一人，想方设法再获得一张车票。以魂之特技进行判定。若失败，重复判定直至成功为止。`,`哐啷哐啷、哐啷哐啷。列车行走在比玻璃更为通透的银河岸边，各色繁花在星光的照耀下闪烁着清澈的亮光。`,`不经意间苏醒。在摇晃的列车中不知不觉睡觉了，似乎在梦境中见到了某人。发起该场景的PC用《深渊》进行判定。若成功，随机与一名锚点的【命运】上升1。`,`漂浮在银河岸边的岛屿上，鲜明地耸立着雄伟的白色十字架。可以允许一名在该场景中登场的PC用《祈祷》进行判定。若成功，可以将之后本局游戏中发生的一次魔法灾厄无效化。不论成功与否，只要有人进行判定后，该场景效果即失效。`,`一名身着黑色外套的少女，正透过窗户注视着银河。注意到你后，她递给你一些糖果，微笑着离开了。发起该场景的PC随机获得1个魔素。`,`混杂着噪音的车内广播播报着到站通知，没过不久列车便停下了。角色们可以选择是否下车。若下车，决定该停靠站的世界法则后，在遵守法则的情况下继续推进场景。`,`车窗外，在星光的照耀下一片广阔的芒草原闪着青白色的光芒。芒草原中散落地立着几个三角标，上面刻有不可思议的纹样。`,`突然发现周围空无一人，只有盖在座位上的蓝色丝绒空虚地装点着车厢。发起该场景的PC以外的其他PC若要登场，必须以《静寂》进行判定。判定失败的PC无法在该场景中登场。`,`“请问我可以坐在这里吗？”〈书籍卿〉这么说着，在你身旁坐下。以%{skill}进行判定。若成功，选择一个已公开的概要，公开对应的【秘密】。不论成功与否，只要有人进行判定后，该场景效果即失效。`,`飞跃银河的一群候鸟与列车齐头并进了一会儿后转而离去，离车越来越远的候鸟们化为天河一般的光带，在天空中闪烁着。可以允许一名在该场景中登场的PC用《翼》进行判定。若成功，可以进行魔力重置。不论成功与否，只要有人进行判定后，该场景效果即失效。`,`从旁边车厢走来的竟然是你的锚点。随机选择一名在该场景登场的PC，并从那名PC的未在该异境出现的愚者锚点中随机选择一人、并让其登场。如果被选中的锚点能够成功返回原来的世界，游戏结束时对应PC获得1点【功绩点】。`]},WLAT:{name:`世界法则追加表`,type:`1D6`,items:[`世界法则「乐园」。这个停靠站是一个如此美丽、令人感到慰藉的地方。在这里下车的愚者会被美景夺走心神，一辈子停留在此。以「刻印百景」的特技进行判定，若成功，可以阻止愚者被魅惑。不论成功与否，对每位愚者只能进行一次该判定。`,`世界法则「夜祭」。在星光与灯笼的照耀下，不会结束的庆典依旧继续着。在该场景中登场的PC以「刻印百景」的特技进行判定。若成功，使用俗咒【补助】时，每消耗1个魔素可以回复2点【魔力】。`,`世界法则「遗弃」。这个停靠站的周围丢弃着各种各样的东西。在该场景中登场的PC以「刻印百景」的特技进行判定。若成功，会发生一次与魔法【回想】（大判P.110）相同的效果。效果对象从该场景登场的PC中随机选择。`,`世界法则「妖蝶」。这个停靠站的周围栖息着一群蝴蝶，奇色异彩的翅膀上蕴含着魔素。在该场景中登场的PC以「刻印百景」的特技进行判定。若成功，任意获得2个魔素；若失败，随机承受一种变调。`,`这个停靠站的周围是死去的愚者的终点。在这里下车的愚者会死亡。如果那个愚者是该场景中登场的PC的锚点，以「刻印百景」的特技进行判定。若成功，死去的愚者锚点不会成为“创伤”，可以直接从命运栏中消去。`,`世界法则「魔法门」。这里存在着通往其他异境的入口。以「刻印百景」的特技进行判定。若成功，可以发现那扇魔法门。`]},WMT:{name:`徘徊怪物表`,type:`1D6`,items:[`遭遇了由巨魔率领的半兽人和哥布林大军。数百只怪物发出野蛮的叫喊，朝魔法使们袭来。所有PC以《%{star}》进行判定。待全员完成判定后，失败的PC受到1D6点伤害。若有判定成功的PC，可以将伤害点数减去与成功人数相当的数值。`,`有着巨大猛牛头部的巨汉——弥诺陶洛斯阻挡在你身前，挥动着手中的青铜斧。随机选择一名在该场景登场的PC，以《%{beast}》进行判定。若失败，所有PC均受到2点伤害并承受「破绽」变调。`,`突然出现一条巨龙。全身覆盖着深红龙鳞的巨影抬起镰刀般的脖颈，几秒钟后朝你们吐出猛烈的火焰。在场景中登场的所有PC以《%{force}》进行判定。待全员完成判定后，所有PC受到与“1＋失败人数”相当的伤害。`,`身着白银盔甲的骑士出现在眼前。骑士对你发起一对一单挑。在该场景登场的PC中选出一人作为代表应战，以《%{poem}》进行判定。若失败，代表受到5点伤害。`,`上身美丽下身却是兽的女怪物出现在眼前。她扭动着妖艳的腰肢，向你伸出手。在场景中登场的所有PC以《%{dream}》进行判定。判定失败的PC受到3点伤害，并失去任意3个魔素。`,`披着黑色斗篷的幽鬼出现在眼前。它举起犹如枯木的细长双手，开始诅咒你。幽鬼的【魔力】为4。在场景中登场的所有PC以《%{night}》进行判定。判定失败的PC承受「不幸」变调，并发生「命运转变」。`]},FFT:{name:`落花表`,type:`1D6`,items:[`肉体如枯死的植物般开始崩坏，这份痛苦根本难以忍受。不成人话的痛苦嘶喊折磨着自己也折磨着他人，最终死去。对于将该〈永远〉设为锚点的角色，死亡的〈永远〉会成为创伤。`,`精神崩坏。张合的嘴唇如坏掉的乐器一般，反反复复地小声吐露着〈永远〉怀抱的梦想和愿望。迎来季节变换之时，最终死去。对于将该〈永远〉设为锚点的角色，死亡的〈永远〉会成为创伤。`,`生命力暴走导致〈永远〉重复着死亡与重生，甚至连哀求他人相助的力气都没有。1D6个月后，最终死去。对于将该〈永远〉设为锚点的角色，死亡的〈永远〉会成为创伤。`,`与《禁书》一起被封印魔法吞噬。〈永远〉反复出现在结下命运的PC的梦境中，哭喊着“好黑！好恐怖！求求你救救我！”。然而到了下一个新月之夜，却突然不再出现。对于将该〈永远〉设为锚点的角色，死亡的〈永远〉会成为创伤。`,`当时没有发生任何异常。或许是运气好吧，看起来似乎变回了〈愚者〉。然而一旦沉睡，就再也不会醒来，最终死去。对于将该〈永远〉设为锚点的角色，死亡的〈永远〉会成为创伤。`,`从枯萎的身体中落下一枚「种子」，但〈永远〉已经无法重生了。如果把种子埋入大地，会发芽长出什么植物吧。对于将该〈永远〉设为锚点的角色，失去这个锚点且不会留下创伤。`]},OLST:{name:`旧图书馆场景表`,type:`2D6`,items:[`拐角。《禁书》突然出现，朝你袭来！在该场景登场的PC用%{skill}进行判定。若失败，【魔力】减少3。`,`道路正中。打开门后《旧世界秩序》的〈书籍卿〉「古代书籍的化身」（大判P.174）出现在眼前，向该场景中登场的PC提出合作。必须从该场景登场的PC中选出一人，以《谎言》进行判定。若成功，这位〈书籍卿〉会在本局游戏期间，当判定的PC进行魔法战时作为见证人参战（该见证效果仅发生一次）。若失败，恼羞成怒的〈书籍卿〉会在下一个场景对判定的PC挑起魔法战。不论成功与否，只要有人进行判定后，该场景效果即失效。`,`曾经的研究室。损坏的试验道具凌乱地散落在地。`,`曾经的阅览室。几名魔法使正在休息，在这里应该能打探到一些情报吧。`,`排列着空空如也的书架的开阔空间。在这里能好好休息一下。`,`堆积地如小山一般的被破坏的魔导书。藏匿在书堆中的《断章》向你袭来！在该场景登场的PC以%{skill}进行判定。若成功，击败《断章》后任意获得1个魔素；若失败，将跨越时空对锚点造成影响，发生「命运转变」。`,`损毁的书架层层叠叠，形成了迷宫一般的道路。前方到底有什么在等待着你呢？`,`曾经的宿舍。残留着几张朴素的床。`,`道路尽头，不知为何摆放着一只大箱子。可以允许一名在该场景中登场的PC用《谜》进行判定。若成功，发现箱内的战利品，可以使用一次「战利品表」。若失败，则会触发箱内陷阱，爆炸的箱子导致在该场景中登场的所有PC的【魔力】均减少1。不论成功与否，只要有人进行判定后，该场景效果即失效。`,`不知从何涌出的水流在地面形成一口清泉，泉水上浮着被他人唤出的元型。以%{skill}进行判定。若成功，获得1点【临时魔力】；若失败，被元型攻击后减少1点【魔力】。不论成功与否，只要有人进行判定后，该场景效果即失效。`,`为什么，你会在这里？推开门后，PC的锚点正站在那儿。从发起该场景的PC的锚点中随机选择一人，并使其登场。发起该场景的PC能够以那名锚点为对象进行「事件」，事件结束后继续推进原场景。`]},TPTB:{name:`大判时间流逝表`,type:`1D6`,items:[`过着波澜万丈的动荡生活。这个时代发生的许多著名事件的背后，都有魔法性存在暗中推波助澜。你也与事件有关，不停地与《禁书》和《书籍卿》们战斗。以%{skill}进行判定。若成功在本局游戏结束后额外获得1个功绩点；若失败，自身发生「命运转变」。`,`在冒险的旅途中，无上的幸福降临了。以%{skill}进行判定。若成功使降临在自身锚点身上的一种灾厄、或者是自己背负的一个创伤无效化。`,`是进行了冥想吗？还是被什么东西封印了呢？从长眠中苏醒，不知不觉已经是这个时间了。不过多亏如此，得到了足够的休息。随机获得3个魔素，或者进行「魔力重置」，或者回复自己身上的所有变调。`,`到特殊的异境去旅行了，因而完全不知道人界到底发生了什么，就像浦岛太郎一样。作为从异境带回的伴手礼，获得1D6个魔货。`,`藏身于芸芸大众之中过着安稳和平的生活。这样的日子里也发生了些事件。可以选择自己的一名锚点，使用「事件表」。`,`每日刻苦钻研，精进魔法修行。如果玩家愿意，可以将藏书栏中的魔法变更为自己可习得的其他魔法。如果将已填充魔素的魔法更改为未习得的，则失去已填充的魔素。`]},FLT:{name:`那之后表`,items_lower:[`成就者变得容易被邪恶的魔法之力吸引。成就者如果在本局游戏中被《断章》凭依、或成为魔法灾厄的牺牲者，【堕落值】上升1，并进行堕落检定。若检定失败，成就者会丧命并成为PC的创伤。`,`成就者坚信自己的不幸是由魔法使造成的。当成就者遭遇不幸时，【堕落值】上升1，并进行堕落检定。若检定失败，实现其愿望的PC与成就者的【命运】值减少2。`,`成就者坚信自己是特别之人。不再为了实现愿望而努力，自甘堕落。成就者的【堕落值】上升2，并进行堕落检定。若检定失败，使用「命运转变表『狂气性灾厄』」，成就者遭受不幸。`,`实现愿望后，成就者的欲望进一步增大。下一次肯定会许下更难实现的愿望吧。成就者的【堕落值】上升1，并进行堕落检定。若检定失败，使用「命运转变表『社会性灾厄』」，成就者遭受不幸。`,`成就者注意到自己的愿望是靠魔法实现的。成就者的【堕落值】上升1，并进行堕落检定。若检定失败，使用「命运转变表『超自然灾厄』」，成就者遭受不幸。`,`成就者注意到自己的愿望是由PC实现的。成就者的【堕落值】变为与PC的【命运】相同的数值。如果因为该效果导致【堕落值】上升，进行堕落检定。若检定失败，成就者不再是〈愚者〉，而会成为魔法使。`],items_higher:[`成就者对于突然降临的幸运产生了罪恶感。如果成就者的【堕落值】在1以上，则进行堕落检定。若检定失败，使用「命运转变表『精神性灾厄』」，成就者遭受不幸。`,`成就者变得不再信任为其实现愿望的PC，开始怀疑自己是不是被利用了并疏远PC。PC与成就者的【命运】值减少1。`,`成就者丧失了想要实现的愿望。进行堕落检定。若检定成功，【堕落值】减少1。`,`成就者注意到为其实现愿望的PC是魔法使。此后，该成就者的【堕落值】上升时，将额外再上升1（该效果不累积）。如果不愿接受该效果，PC可以选择消去成就者与自己相关的记忆并使效果无效化。消去记忆后，PC与成就者的【命运】变为1。`,`成就者在感谢突然降临的幸运的同时，也依旧与自己的日常战斗着。如果成就者的【堕落值】在1以上，则【堕落值】减少1。`,`成就者认为只要愿意相信，梦想就会成真。成就者稍微变得积极了一些。PC获得1点功绩点。`]}}}}}};r(a);export{a as TRANSLATIONS};